// State for dashboard v2 (Kawaii Soft)
const DashState = {
    month: null,             // '01'..'12'
    year: null,              // '2026'
    period: 'month',         // 'month' | 'year' | 'all'  (2026-09-08)
    range: null,             // {first_date,last_date,count} ช่วงข้อมูลที่มีจริง
    member: 'ALL',           // 'ALL' or user_id — ตัวกรองหลักคือ "สมาชิก" ไม่ใช่บริษัท
    data: null,              // last /api/dashboard/summary response
    openWht: { received: null, withheld: null },  // open month key 'YYYY-MM' per direction
    openPlanIdx: -1,          // which month-tab is open in the calendar
    selPlanDay: null,         // selected day-of-month in the open calendar
    ownerColor: {},           // id -> color index (0-5)
    planMonths: []            // computed list of {key:'YYYY-MM', lbl, days, dow}
};

const DV2_MONTH_TH = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
const DV2_DOW_TH = ['อา','จ','อ','พ','พฤ','ศ','ส'];

function dv2F(n) {
    n = Number(n) || 0;
    const abs = Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return n < 0 ? '(' + abs + ')' : abs;
}
function dv2Sum(arr, fn) { return (arr || []).reduce((s, x) => s + (fn ? fn(x) : Number(x.amount) || 0), 0); }
function dv2Desc(arr, keyFn) {
    return [...(arr || [])].sort((a, b) => Math.abs((keyFn ? keyFn(b) : b.amount)) - Math.abs((keyFn ? keyFn(a) : a.amount)));
}
function dv2MonthLabel(moStr) {
    if (!moStr) return '-';
    const [y, m] = moStr.split('-');
    return `${DV2_MONTH_TH[parseInt(m, 10) - 1]} ${y}`;
}
function dv2DateTH(iso) {
    if (!iso) return '-';
    const [y, m, d] = String(iso).substring(0, 10).split('-');
    return `${parseInt(d, 10)} ${DV2_MONTH_TH[parseInt(m, 10) - 1]} ${y}`;
}
/* ป้ายช่วงเวลาที่กำลังดู — ใช้ทั้งแถบบน การ์ด และหน้าขยาย */
function dv2PeriodLabel() {
    if (DashState.period === 'all') {
        const r = DashState.range || {};
        return r.first_date ? `ทั้งหมด · ${dv2DateTH(r.first_date)} – ${dv2DateTH(r.last_date)}` : 'ทั้งหมด';
    }
    if (DashState.period === 'year') return `ปี ${DashState.year}`;
    return dv2MonthLabel(`${DashState.year}-${DashState.month}`);
}
function dv2OwnerClass(entityId) {
    if (!entityId) return 'dv2-own-0';
    if (!(entityId in DashState.ownerColor)) {
        DashState.ownerColor[entityId] = Object.keys(DashState.ownerColor).length % 6;
    }
    return 'dv2-own-' + DashState.ownerColor[entityId];
}
function dv2OwnerName(entityId) {
    const e = ((DashState.data && DashState.data.entities) || []).find(x => x.entity_id === entityId);
    return e ? e.name : (entityId || '-');
}
function dv2OwnerTag(entityId) {
    if (DashState.member !== 'ALL' || !entityId) return '';
    return `<span class="dv2-own ${dv2OwnerClass(entityId)}">${dv2OwnerName(entityId)}</span>`;
}
// User Member (สมาชิกที่บันทึกรายการ) — ต่างจาก Owner/Entity (Company ผู้รับรายได้-ค่าใช้จ่าย)
// ใช้แท็กนี้เพื่อบอกว่า "ใครทำรายการ" ส่วน Owner ใช้บอกว่า "รายการนี้เป็นของบริษัทไหน" เท่านั้น
function dv2UserClass(userId) {
    if (!userId) return 'dv2-own-0';
    if (!(userId in DashState.ownerColor)) {
        DashState.ownerColor[userId] = Object.keys(DashState.ownerColor).length % 6;
    }
    return 'dv2-own-' + DashState.ownerColor[userId];
}
function dv2UserTag(userId, userName) {
    if (DashState.member !== 'ALL' || !userId) return '';
    return `<span class="dv2-own ${dv2UserClass(userId)}">${userName || '-'}</span>`;
}
function dv2StopSign(id) {
    return `<svg viewBox="0 0 26 34" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="pole${id}" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stop-color="#8A95A3"/><stop offset=".35" stop-color="#D6DDE6"/>
        <stop offset=".62" stop-color="#AEB8C4"/><stop offset="1" stop-color="#6E7A88"/>
      </linearGradient>
      <linearGradient id="face${id}" x1=".2" y1="0" x2=".8" y2="1">
        <stop offset="0" stop-color="#F0574C"/><stop offset=".5" stop-color="#D8342B"/>
        <stop offset="1" stop-color="#A81F19"/>
      </linearGradient>
      <linearGradient id="edge${id}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#B02A22"/><stop offset="1" stop-color="#7C140F"/>
      </linearGradient>
    </defs>
    <rect x="11.2" y="17" width="3.6" height="16" rx="1.2" fill="url(#pole${id})"/>
    <ellipse cx="13" cy="32.6" rx="5" ry="1.5" fill="rgba(0,0,0,.2)"/>
    <path d="M8.6 20.4 L4.2 16 v-5.6 L8.6 6 h8.8 L21.8 10.4 V16 L17.4 20.4 z"
      fill="url(#edge${id})" transform="translate(0,1.1)"/>
    <path d="M8.6 20.4 L4.2 16 v-5.6 L8.6 6 h8.8 L21.8 10.4 V16 L17.4 20.4 z"
      fill="url(#face${id})" stroke="#fff" stroke-width="1.5" stroke-linejoin="round"/>
    <path d="M8.9 7.4 h8.2 L20.5 10.8 v1.1 L17 8.6 H9 z" fill="rgba(255,255,255,.32)"/>
    <text x="13" y="14.6" text-anchor="middle" font-family="Kanit,sans-serif"
      font-size="5.4" font-weight="700" fill="#fff" letter-spacing=".2">STOP</text>
  </svg>`;
}

async function loadDashboardV2Data() {
    const headers = { 'x-user-id': encodeURIComponent(getUserIdHeader()) };
    /* เปิดครั้งแรก: ขอ "เดือนล่าสุดที่มีรายการ" แทนเดือนปัจจุบัน (2026-09-08)
       เดิมเริ่มที่เดือนปัจจุบันเสมอ → ข้อมูลจริงจบ พ.ย. 2025 หน้าแรกเลยว่างเปล่า
       ทั้งที่มีรายการหมื่นกว่ารายการ North เข้าใจว่าระบบไม่แสดงผล */
    const monthStr = DashState.month ? `${DashState.year}-${DashState.month}` : 'latest';
    const res = await fetch(`${API_BASE}/api/dashboard/summary?month=${monthStr}&period=${DashState.period}&member=${encodeURIComponent(DashState.member)}`, { headers });
    const data = await res.json();
    if (data.error) throw new Error(data.error);
    DashState.data = data;
    DashState.range = data.range || null;
    if (data.month && /^\d{4}-\d{2}$/.test(data.month)) {
        DashState.year = data.month.substring(0, 4);
        DashState.month = data.month.substring(5, 7);
    }
}

function dv2SetMember(id) { DashState.member = id; loadDashboard(); }
function dv2SetPeriod(p) { DashState.period = p; loadDashboard(); }
function dv2ChangeMonth(delta) {
    if (DashState.period === 'all') return;
    let m = parseInt(DashState.month, 10);
    let y = parseInt(DashState.year, 10);
    if (DashState.period === 'year') { y += delta; }
    else {
        m += delta;
        if (m < 1) { m = 12; y--; } else if (m > 12) { m = 1; y++; }
    }
    DashState.month = String(m).padStart(2, '0');
    DashState.year = String(y);
    loadDashboard();
}

// ── Hero ──
function dv2Hero() {
    const d = DashState.data;
    const accounts = (d.accounts || []).filter(a => a.account_type !== 'CREDIT');
    const sBal = dv2Sum(accounts, a => a.balance);
    const sIn = dv2Sum(d.income);
    const sOut = dv2Sum(d.expense, x => Math.abs(x.amount));
    const tot = sIn + sOut;
    const pIn = tot ? (sIn / tot * 100) : 50;
    const pOut = 100 - pIn;
    const mLabel = dv2PeriodLabel();
    const memberChips = [`<span class="dv2-chip${DashState.member==='ALL'?' on':''}" onclick="dv2SetMember('ALL')">ทั้งครอบครัว</span>`]
        .concat((d.members || []).map(m => `<span class="dv2-chip${DashState.member===m.user_id?' on':''}" onclick="dv2SetMember('${m.user_id}')">${m.name}</span>`)).join('');
    return `<div class="dv2-hero">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:13px">
        <div><div class="dv2-sm">ยอดเงินคงเหลือรวม · เงินฝาก/เงินสด ${DashState.member==='ALL'?'· ทั้งครอบครัว':''}</div>
          <div class="dv2-big">${dv2F(sBal)}</div>
          <div class="dv2-xs" style="margin-top:6px">กระแสเงินสด ${mLabel} · <b>${dv2F(sIn-sOut)}</b></div>
          <div class="dv2-xs" style="margin-top:3px">📅 ข้อมูลถึง <b>${dv2DateTH(d.range?.last_date)}</b>${d.range?.count ? ` · ${d.range.count.toLocaleString('en-US')} รายการ` : ''}</div></div>
        <div style="display:flex;gap:5px;flex-wrap:wrap">${memberChips}</div>
      </div>
      <div class="dv2-hgauge"><div class="dv2-hseg dv2-hin" style="width:${pIn}%"><span>รับ ${dv2F(sIn)}</span></div>
        <div class="dv2-hseg dv2-hout" style="width:${pOut}%"><span>จ่าย ${dv2F(sOut)}</span></div></div>
      <div style="display:flex;justify-content:space-between;font-size:.7rem;margin-top:7px;color:rgba(255,255,255,.95)">
        <span>▲ รับเข้า ${pIn.toFixed(1)}%</span><span>${pOut.toFixed(1)}% จ่ายออก ▼</span></div></div>`;
}

/* สรุปตามหมวดหมู่ (2026-09-08 · North: "สินทรัพย์ investment รายรับ รายจ่าย อยากให้สรุปมาเป็นแบบ
   Category ตอนนี้เหมือนแยกรายการออกมา") — การ์ดเดิมไล่รายการทีละแถว พอมีเดือนละหลายร้อยแถว
   อ่านไม่รู้เรื่อง · ตอนนี้รวมเป็นหมวดก่อน กดที่หมวดในหน้าขยายถึงจะเห็นรายการข้างใน */
function dv2ByCat(rows, valueFn) {
    const map = new Map();
    for (const x of rows || []) {
        const key = x.category_id || x.category_name || '-';
        if (!map.has(key)) map.set(key, { category_id: key, name: x.category_name || x.category_id || '-', n: 0, sum: 0, items: [] });
        const g = map.get(key);
        g.n += 1; g.sum += valueFn ? valueFn(x) : (Number(x.amount) || 0); g.items.push(x);
    }
    return [...map.values()].sort((a, b) => Math.abs(b.sum) - Math.abs(a.sum));
}
function dv2CatLI(groups, cls) {
    return groups.map(g => `<div class="dv2-item">
      <div class="dv2-itxt"><div class="dv2-iname">${g.name}</div>
        <div class="dv2-imeta">${g.n} รายการ</div></div>
      <div class="dv2-iamt ${cls}">${dv2F(g.sum)}</div></div>`).join('');
}
function dv2LI(arr, cls) {
    return arr.map(x => `<div class="dv2-item">
      <div class="dv2-itxt"><div class="dv2-iname">${x.title}</div>
        <div class="dv2-imeta">${(x.date||'').substring(0,10)}${dv2UserTag(x.user_id, x.user_name)}</div></div>
      <div class="dv2-iamt ${cls}">${dv2F(x.amount)}</div></div>`).join('');
}

function dv2Income() {
    const a = DashState.data.income || [];
    const g = dv2ByCat(a, x => Number(x.amount) || 0);
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">📥</span>รายรับ · ตามหมวด</span>
      <span class="dv2-xs">${g.length} หมวด · ${a.length} รายการ</span><button class="dv2-zoombtn" onclick="dv2Zoom('income')" title="ขยายดูชัด ๆ">🔍</button></h3>
      <div class="dv2-mid dv2-pos" style="margin-bottom:9px">${dv2F(dv2Sum(a))}</div>
      <div class="dv2-list">${g.length ? dv2CatLI(g,'dv2-pos') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ไม่มีรายการ</div>'}</div></div>`;
}
function dv2Expense() {
    const a = DashState.data.expense || [];
    const g = dv2ByCat(a, x => Math.abs(Number(x.amount) || 0));
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">📤</span>รายจ่าย · ตามหมวด</span>
      <span class="dv2-xs">${g.length} หมวด · ${a.length} รายการ</span><button class="dv2-zoombtn" onclick="dv2Zoom('expense')" title="ขยายดูชัด ๆ">🔍</button></h3>
      <div class="dv2-mid dv2-neg" style="margin-bottom:9px">${dv2F(dv2Sum(a, x => Math.abs(x.amount)))}</div>
      <div class="dv2-list">${g.length ? dv2CatLI(g,'dv2-neg') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ไม่มีรายการ</div>'}</div></div>`;
}
function dv2Avg() {
    const d = DashState.data;
    let daysInMonth = new Date(parseInt(DashState.year), parseInt(DashState.month), 0).getDate();
    const today = new Date();
    const isCurrentMonth = DashState.period === 'month' && DashState.year === String(today.getFullYear()) && DashState.month === String(today.getMonth()+1).padStart(2,'0');
    let dayOfMonth = isCurrentMonth ? today.getDate() : daysInMonth;
    // ดูทั้งปี/ทั้งหมด: เฉลี่ยตามจำนวนวันจริงของช่วงนั้น ไม่ใช่ 30 วัน
    if (DashState.period === 'year') { const leap = (y => (y%4===0 && y%100!==0) || y%400===0)(parseInt(DashState.year)); daysInMonth = dayOfMonth = leap ? 366 : 365; }
    if (DashState.period === 'all' && d.range?.first_date && d.range?.last_date) {
        daysInMonth = dayOfMonth = Math.max(1, Math.round((new Date(d.range.last_date) - new Date(d.range.first_date)) / 86400000) + 1);
    }
    const sOut = dv2Sum(d.expense, x => Math.abs(x.amount));
    const perDay = dayOfMonth ? sOut / dayOfMonth : 0;
    const worst = d.expense.length ? d.expense.reduce((m,x)=>Math.abs(x.amount)>Math.abs(m.amount)?x:m, d.expense[0]) : null;
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">📊</span>เฉลี่ย</span></h3>
      <div class="dv2-mid dv2-accent" style="margin-bottom:9px">${dv2F(perDay)}</div>
      <div class="dv2-list">
        <div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">เฉลี่ยรายจ่ายต่อวัน</div>
          <div class="dv2-imeta">${dayOfMonth} วันผ่านไป</div></div><div class="dv2-iamt">${dv2F(perDay)}</div></div>
        <div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">รายจ่ายสูงสุดรายการเดียว</div>
          <div class="dv2-imeta">${worst ? (worst.date||'').substring(0,10) : '—'}${worst?dv2UserTag(worst.user_id, worst.user_name):''}</div></div>
          <div class="dv2-iamt dv2-neg">${dv2F(worst?Math.abs(worst.amount):0)}</div></div>
        <div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">คาดการณ์ทั้งเดือน</div>
          <div class="dv2-imeta">${daysInMonth} วัน</div></div><div class="dv2-iamt">${dv2F(perDay*daysInMonth)}</div></div>
        <div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">เฉลี่ยรายรับ/รายการ</div>
          <div class="dv2-imeta">${d.income.length} รายการ</div></div>
          <div class="dv2-iamt dv2-pos">${dv2F(d.income.length ? dv2Sum(d.income)/d.income.length : 0)}</div></div>
        <div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">เฉลี่ยรายจ่าย/รายการ</div>
          <div class="dv2-imeta">${d.expense.length} รายการ</div></div>
          <div class="dv2-iamt dv2-neg">${dv2F(d.expense.length ? sOut/d.expense.length : 0)}</div></div>
      </div></div>`;
}

// ── Statement / Credit / Investment ──
function dv2Stmt() {
    const a = dv2Desc((DashState.data.accounts||[]).filter(x=>x.account_type!=='CREDIT'), x=>x.balance);
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">🏦</span>Statement · เงินฝาก/เงินสด</span>
      <span class="dv2-xs">${a.length} บัญชี</span><button class="dv2-zoombtn" onclick="dv2Zoom('stmt')" title="ขยายดูชัด ๆ">🔍</button></h3>
      <div class="dv2-mid dv2-accent" style="margin-bottom:9px">${dv2F(dv2Sum(a,x=>x.balance))}</div>
      <div class="dv2-list">${a.length ? a.map(x=>`<div class="dv2-item">
        <div class="dv2-itxt"><div class="dv2-iname"><span class="dv2-ico" style="font-size:.95rem">${x.account_type==='CASH'?'💵':'🏦'}</span> ${x.name}</div>
          <div class="dv2-imeta">${x.bank_name||''}${dv2OwnerTag(x.entity_id)}</div></div>
        <div class="dv2-iamt">${dv2F(x.balance)}</div></div>`).join('') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ยังไม่มีบัญชี</div>'}</div></div>`;
}
function dv2Credit() {
    const a = dv2Desc((DashState.data.accounts||[]).filter(x=>x.account_type==='CREDIT'), x=>x.balance);
    const uTot = dv2Sum(a, x=>Math.abs(x.balance));
    const lTot = dv2Sum(a, x=>x.credit_limit||0);
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">💳</span>Credit Card · ยอดใช้ไป</span>
      <span class="dv2-xs">${a.length} ใบ</span><button class="dv2-zoombtn" onclick="dv2Zoom('credit')" title="ขยายดูชัด ๆ">🔍</button></h3>
      <div class="dv2-mid dv2-neg" style="margin-bottom:4px">${dv2F(uTot)}</div>
      <div class="dv2-xs" style="margin-bottom:9px">วงเงินรวม ${dv2F(lTot)} · ใช้ไป ${lTot?(uTot/lTot*100).toFixed(1):0}% · เหลือ ${dv2F(lTot-uTot)}</div>
      <div class="dv2-list">${a.length ? a.map(x=>{
        const use = Math.abs(x.balance); const lim = x.credit_limit || 0;
        const p = lim ? Math.min(100, use/lim*100) : 0;
        const col = p>=80?'#C9352C':(p>=50?'#DE8E12':'#3E8F58');
        const due = x.due_day ? `ครบกำหนดวันที่ ${x.due_day}` : 'ยังไม่ตั้งวันครบกำหนด';
        return `<div class="dv2-item" style="display:block">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:9px">
            <div class="dv2-itxt"><div class="dv2-iname"><span class="dv2-ico" style="font-size:.95rem">💳</span> ${x.name}</div>
              <div class="dv2-imeta">${due} · วงเงิน ${dv2F(lim)}${dv2OwnerTag(x.entity_id)}</div></div>
            <div class="dv2-iamt ${use>0?'dv2-neg':''}">${dv2F(use)}</div></div>
          <div style="position:relative;height:6px;background:rgba(0,0,0,.07);border-radius:4px;margin-top:6px">
            <div style="position:absolute;left:0;top:0;height:100%;border-radius:4px;width:${p}%;background:${col};box-shadow:inset 0 1px 0 rgba(255,255,255,.4)"></div></div></div>`;
      }).join('') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ยังไม่มีบัตรเครดิต</div>'}</div></div>`;
}
function dv2Invest() {
    const a = DashState.data.investment || [];
    const g = dv2ByCat(a);
    const tot = dv2Sum(a), pos = dv2Sum(a.filter(x=>x.amount>0)), neg = dv2Sum(a.filter(x=>x.amount<0));
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">💎</span>Investment · ตามหมวด</span>
      <span class="dv2-xs">${g.length} หมวด · ${a.length} รายการ</span><button class="dv2-zoombtn" onclick="dv2Zoom('invest')" title="ขยายดูชัด ๆ">🔍</button></h3>
      <div class="dv2-mid ${tot>=0?'dv2-pos':'dv2-neg'}" style="margin-bottom:4px">${dv2F(tot)}</div>
      <div class="dv2-xs" style="margin-bottom:9px">เงินกลับเข้า ${dv2F(pos)} · เงินออกไปลงทุน ${dv2F(neg)}</div>
      <div class="dv2-list">${g.length ? g.map(x=>`<div class="dv2-item">
        <div class="dv2-itxt"><div class="dv2-iname"><span class="dv2-ico" style="font-size:.95rem">${x.sum>=0?'📈':'📉'}</span> ${x.name}</div>
          <div class="dv2-imeta">${x.n} รายการ</div></div>
        <div class="dv2-iamt ${x.sum>=0?'dv2-pos':'dv2-neg'}">${dv2F(x.sum)}</div></div>`).join('') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ยังไม่มีเงินลงทุน</div>'}</div></div>`;
}

// ── เงินไปไหน ──
function dv2BudgetRow(b, i) {
    const scale = Math.max(b.spent, b.budget) * 1.15 || 1;
    const wUse = Math.min(100, b.spent/scale*100);
    const wBud = Math.min(100, b.budget/scale*100);
    const over = b.spent > b.budget && b.budget > 0;
    const diff = Math.abs(b.spent - b.budget);
    const pct = b.budget ? (b.spent/b.budget*100) : 0;
    const grad = over ? 'linear-gradient(180deg,#F0625A,#C9352C)' : (pct>=80?'linear-gradient(180deg,#F5B34D,#DE8E12)':'linear-gradient(180deg,#6BBB80,#3E8F58)');
    const amtCls = over?'dv2-neg':(pct>=80?'':'dv2-pos');
    return `<div>
      <div class="dv2-split"><span style="font-size:.8rem;font-weight:500;cursor:pointer" onclick="dv2OpenBudgetModal('${b.category_id}')">${b.category_name}</span>
        <span class="dv2-iamt ${amtCls}">${dv2F(b.spent)} / ${b.budget?dv2F(b.budget):'ยังไม่ตั้งงบ'}</span></div>
      <div class="dv2-gauge"><div class="dv2-gfill" style="width:${wUse}%;background:${grad}"></div>
        ${b.budget ? `<div class="dv2-gstop" style="left:${wBud}%">${dv2StopSign('b'+i)}</div>` : ''}</div>
      <div class="dv2-xs ${over?'dv2-neg':''}">${b.budget ? (over?`เกินงบ ${dv2F(diff)}`:`เหลือ ${dv2F(diff)}`) : 'แตะชื่อหมวดเพื่อตั้งงบ'}</div></div>`;
}
function dv2Budget() {
    const b = DashState.data.budget || [];
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">🎯</span>เงินไปไหน · เทียบงบ</span>
      <span class="dv2-xs">รวมทั้งครอบครัว · ${b.length} หมวด · ใช้ ${dv2F(dv2Sum(b,x=>x.spent))} / งบ ${dv2F(dv2Sum(b,x=>x.budget))}</span><button class="dv2-zoombtn" onclick="dv2Zoom('budget')" title="ขยายดูชัด ๆ">🔍</button></h3>
      <div class="dv2-bcols">${b.length ? b.map((x,i)=>dv2BudgetRow(x,i)).join('') : '<div class="dv2-xs">ยังไม่มีค่าใช้จ่ายในช่วงนี้</div>'}</div></div>`;
}

// ── AR / AP ──
function dv2AR() {
    const a = dv2Desc(DashState.data.ar, x=>x.amount);
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">💰</span>ลูกหนี้ · รับเข้า</span>
      <span style="display:flex;gap:5px"><span class="dv2-chip" onclick="dv2ExportList('ar','PDF')">PDF</span><span class="dv2-chip" onclick="dv2ExportList('ar','Excel')">XLS</span></span></h3>
      <div class="dv2-mid dv2-pos" style="margin-bottom:9px">${dv2F(dv2Sum(a))}</div>
      <div class="dv2-list">${a.length ? a.map(x=>`<div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">${x.party}</div>
        <div class="dv2-imeta">${x.count} รายการ${dv2OwnerTag(x.entity_id)}</div></div><div class="dv2-iamt dv2-pos">${dv2F(x.amount)}</div></div>`).join('') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ไม่มีลูกหนี้คงค้าง</div>'}</div></div>`;
}
function dv2AP() {
    const a = dv2Desc(DashState.data.ap, x=>x.amount);
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">🧾</span>เจ้าหนี้ · ต้องจ่าย</span>
      <span style="display:flex;gap:5px"><span class="dv2-chip" onclick="dv2ExportList('ap','PDF')">PDF</span><span class="dv2-chip" onclick="dv2ExportList('ap','Excel')">XLS</span></span></h3>
      <div class="dv2-mid dv2-neg" style="margin-bottom:9px">${dv2F(dv2Sum(a))}</div>
      <div class="dv2-list">${a.length ? a.map(x=>`<div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname">${x.party}</div>
        <div class="dv2-imeta">${x.count} รายการ${dv2OwnerTag(x.entity_id)}</div></div><div class="dv2-iamt dv2-neg">${dv2F(x.amount)}</div></div>`).join('') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ไม่มีเจ้าหนี้ค้างจ่าย</div>'}</div></div>`;
}
function dv2ExportList(key, kind) {
    const src = key === 'ar' ? DashState.data.ar : DashState.data.ap;
    const rows = dv2Desc(src, x=>x.amount);
    const title = key === 'ar' ? 'ลูกหนี้ (รับเข้า)' : 'เจ้าหนี้ (ต้องจ่าย)';
    const cols = [
        { h: 'คู่ค้า', w: 240, get: r => r.party },
        { h: 'จำนวนรายการ', w: 100, get: r => r.count, align:'c' },
        { h: 'บริษัท/เจ้าของ', w: 160, get: r => r.entity_name || '-' },
        { h: 'ยอดคงเหลือ', w: 120, get: r => dv2F(r.amount), raw: r => r.amount, align:'r', num:true, total:true }
    ];
    if (kind === 'PDF') dv2OpenReportWindow(title, `ณ วันที่ ${new Date().toLocaleDateString('th-TH')}`, cols, rows);
    else dv2ExportExcel(title, cols, rows);
}

// ── WHT ──
function dv2WhtCard(key, title, sub, baseLbl) {
    const arr = (DashState.data.wht && DashState.data.wht[key]) || [];
    const g = {};
    arr.forEach(x => { (g[x.mo] = g[x.mo] || []).push(x); });
    const months = Object.keys(g).sort((p,q) => dv2Sum(g[q],x=>x.wht) - dv2Sum(g[p],x=>x.wht));
    const open = DashState.openWht[key];
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">${key==='received'?'📋':'🏛️'}</span>${title}</span>
      <span class="dv2-xs">${sub}</span></h3>
      <div class="dv2-mid dv2-accent" style="margin-bottom:9px">${dv2F(dv2Sum(arr,x=>x.wht))}</div>
      <div class="dv2-list">${months.length ? months.map(mo => {
        const rows = dv2Desc(g[mo], x=>x.wht);
        const on = open === mo;
        return `<div style="border-bottom:1px solid var(--line)">
          <div class="dv2-item" style="border-bottom:none;cursor:pointer" onclick="dv2ToggleWht('${key}','${mo}')">
            <div class="dv2-itxt"><div class="dv2-iname"><span style="display:inline-block;width:12px;color:var(--ac)">${on?'▾':'▸'}</span> ${dv2MonthLabel(mo)}</div>
              <div class="dv2-imeta">${rows.length} รายการ</div></div>
            <div class="dv2-iamt">${dv2F(dv2Sum(rows,x=>x.wht))}</div></div>
          ${on ? `<div class="dv2-whtdetail">
            <div class="dv2-whthd"><span>วันที่</span><span>รายการ</span><span>Company</span><span>Customer</span><span>ค่าบริการ</span><span>${baseLbl}</span><span>User</span></div>
            ${rows.map(r => `<div class="dv2-whtrow">
              <span>${r.date}</span><span title="${r.title}">${r.title}</span>
              <span title="${r.company}">${r.company}</span><span title="${r.customer}">${r.customer}</span>
              <span class="dv2-num">${dv2F(r.base)}</span><span class="dv2-num">${dv2F(r.wht)}</span>
              <span>${r.user_id?`<span class="dv2-own ${dv2UserClass(r.user_id)}">${r.user_name||'-'}</span>`:'—'}</span></div>`).join('')}
            <div class="dv2-whtrow dv2-whtsum">
              <span></span><span></span><span></span><span>รวมเดือนนี้</span>
              <span class="dv2-num">${dv2F(dv2Sum(rows,x=>x.base))}</span><span class="dv2-num">${dv2F(dv2Sum(rows,x=>x.wht))}</span><span></span></div>
            <div class="dv2-whtexp">
              <span class="dv2-chip" onclick="event.stopPropagation();dv2ExportWht('PDF','${key}','${title}','${baseLbl}','${mo}')">📄 PDF · ${dv2MonthLabel(mo)}</span>
              <span class="dv2-chip" onclick="event.stopPropagation();dv2ExportWht('Excel','${key}','${title}','${baseLbl}','${mo}')">📊 Excel · ${dv2MonthLabel(mo)}</span></div></div>` : ''}
        </div>`;
      }).join('') : '<div class="dv2-xs" style="text-align:center;padding:14px 0">ไม่มีรายการในปีนี้</div>'}</div>
      <div class="dv2-row dv2-tot"><span>รวมทั้งปี</span><span class="dv2-iamt dv2-accent">${dv2F(dv2Sum(arr,x=>x.wht))}</span></div></div>`;
}
function dv2ToggleWht(key, mo) {
    DashState.openWht[key] = (DashState.openWht[key] === mo) ? null : mo;
    dv2Render();
}

// ── Export: report window (print→PDF) + styled Excel ──
function dv2ColTotals(cols, rows) {
    return cols.map(c => c.total ? dv2Sum(rows, c.raw || (r => parseFloat(String(c.get(r)).replace(/[(),]/g, m => m === '(' ? '-' : '')) || 0)) : null);
}
function dv2ReportWindowHTML(title, subtitle, cols, rows) {
    const totals = dv2ColTotals(cols, rows);
    const firstTotalIdx = totals.findIndex(t => t !== null);
    const tb = rows.map((r,i) => `<tr class="${i%2?'alt':''}"><td class="c">${i+1}</td>${cols.map(c=>`<td class="${c.align==='r'?'r':(c.align==='c'?'c':'')}">${c.get(r)}</td>`).join('')}</tr>`).join('');
    const tfootCells = cols.map((c,i) => {
        if (totals[i] !== null) return `<td class="r">${dv2F(totals[i])}</td>`;
        if (i === firstTotalIdx - 1) return `<td style="text-align:right">รวมทั้งสิ้น</td>`;
        return `<td></td>`;
    }).join('');
    return `<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><title>${title}</title>
<link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600;700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Sarabun',sans-serif;background:#F4F7FB;padding:28px;color:#16233A}
.sheet{max-width:1000px;margin:0 auto;background:#fff;border:1px solid #C9D9EC;border-radius:10px;overflow:hidden;box-shadow:0 6px 26px rgba(20,60,110,.1)}
.hd{background:linear-gradient(135deg,#0B2E63,#164A96);color:#fff;padding:20px 26px}
.hd h1{font-size:1.22rem;font-weight:700}
.hd .sub{font-size:.83rem;color:#A9CDF5;margin-top:5px;font-weight:400}
table{width:100%;border-collapse:collapse;font-size:.81rem}
thead th{background:#164A96;color:#B9D8FA;font-weight:600;font-size:.76rem;padding:11px 10px;text-align:center;border-right:1px solid rgba(255,255,255,.16);border-bottom:2px solid #0B2E63;white-space:nowrap}
thead th:last-child{border-right:none}
tbody td{padding:9px 10px;border-right:1px solid #DCE7F4;border-bottom:1px solid #E7EFF8;font-weight:400;color:#1D2C42}
tbody td:last-child{border-right:none}
tbody tr.alt td{background:#F7FAFE}
td.r{text-align:right;font-variant-numeric:tabular-nums} td.c{text-align:center}
tfoot td{background:#EEF4FC;font-weight:700;color:#0B2E63;padding:12px 10px;border-top:2px solid #164A96;border-right:1px solid #DCE7F4}
tfoot td:last-child{border-right:none} tfoot td.r{text-align:right;font-variant-numeric:tabular-nums}
.ft{padding:15px 26px;font-size:.71rem;color:#63758E;display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;border-top:1px solid #E7EFF8}
.bar{max-width:1000px;margin:0 auto 16px;display:flex;gap:9px;justify-content:flex-end}
.bar button{padding:9px 18px;border:none;border-radius:8px;cursor:pointer;font-family:inherit;font-size:.82rem;font-weight:600;background:#164A96;color:#fff}
.bar button.alt{background:#fff;color:#164A96;border:1.5px solid #164A96}
@media print{body{background:#fff;padding:0}.bar{display:none}.sheet{border:none;box-shadow:none;border-radius:0}}
</style></head><body>
<div class="bar"><button onclick="window.print()">🖨️ พิมพ์ / บันทึกเป็น PDF</button><button class="alt" onclick="window.close()">ปิด</button></div>
<div class="sheet"><div class="hd"><h1>${title}</h1><div class="sub">${subtitle}</div></div>
<table><thead><tr><th style="width:42px">ลำดับ</th>${cols.map(c=>`<th style="width:${c.w}px">${c.h}</th>`).join('')}</tr></thead>
<tbody>${tb}</tbody>
<tfoot><tr><td></td>${tfootCells}</tr></tfoot></table>
<div class="ft"><span>เอกสารนี้จัดทำโดยระบบ RecordRevenue</span><span>วันที่ออกรายงาน ${new Date().toLocaleDateString('th-TH')}</span></div></div>
</body></html>`;
}
function dv2OpenReportWindow(title, subtitle, cols, rows) {
    const w = window.open('', '_blank', 'width=1080,height=760');
    if (!w) { alert('เบราว์เซอร์บล็อกป๊อปอัป — กรุณาอนุญาตแล้วลองใหม่'); return; }
    w.document.write(dv2ReportWindowHTML(title, subtitle, cols, rows));
    w.document.close();
}
function dv2ExportExcel(filename, cols, rows) {
    const XL = (typeof XLSXStyle !== 'undefined') ? XLSXStyle : XLSX;
    if (typeof XL === 'undefined') { alert('ไม่พบไลบรารีส่งออกไฟล์ กรุณารีเฟรชหน้าเว็บ'); return; }
    const numFmt = '#,##0.00_);(#,##0.00)';
    const blueHdr = { font:{bold:true,color:{rgb:'FFFFFF'},sz:11}, fill:{fgColor:{rgb:'2563EB'},patternType:'solid'},
        alignment:{horizontal:'center',vertical:'center'}, border:{top:{style:'thin',color:{rgb:'BFDBFE'}},bottom:{style:'thin',color:{rgb:'BFDBFE'}},left:{style:'thin',color:{rgb:'BFDBFE'}},right:{style:'thin',color:{rgb:'BFDBFE'}}} };
    const cellStyle = { font:{color:{rgb:'1D4ED8'}}, border:{top:{style:'thin',color:{rgb:'DBEAFE'}},bottom:{style:'thin',color:{rgb:'DBEAFE'}},left:{style:'thin',color:{rgb:'DBEAFE'}},right:{style:'thin',color:{rgb:'DBEAFE'}}} };
    const totals = dv2ColTotals(cols, rows);
    const firstTotalIdx = totals.findIndex(t => t !== null);
    const header = ['ลำดับ', ...cols.map(c=>c.h)];
    const aoa = [header];
    rows.forEach((r,i) => aoa.push([i+1, ...cols.map(c => c.num ? (c.raw ? c.raw(r) : (parseFloat(String(c.get(r)).replace(/[(),]/g, m => m === '(' ? '-' : '')) || 0)) : c.get(r))]));
    aoa.push(['', ...cols.map((c,i) => totals[i] !== null ? totals[i] : (i === firstTotalIdx - 1 ? 'รวมทั้งสิ้น' : ''))]);
    const ws = XL.utils.aoa_to_sheet(aoa);
    const range = XL.utils.decode_range(ws['!ref']);
    for (let C = range.s.c; C <= range.e.c; C++) {
        const hc = XL.utils.encode_cell({ r:0, c:C });
        if (ws[hc]) ws[hc].s = blueHdr;
    }
    for (let R = 1; R <= range.e.r; R++) {
        for (let C = range.s.c; C <= range.e.c; C++) {
            const cellRef = XL.utils.encode_cell({ r:R, c:C });
            if (ws[cellRef]) {
                ws[cellRef].s = { ...cellStyle, font: R === range.e.r ? { ...cellStyle.font, bold: true } : cellStyle.font };
                if (C > 0 && cols[C-1] && cols[C-1].num) ws[cellRef].z = numFmt;
            }
        }
    }
    ws['!cols'] = [{wch:6}, ...cols.map(c=>({wch:Math.round((c.w||100)/7)}))];
    const wb = XL.utils.book_new();
    XL.utils.book_append_sheet(wb, ws, filename.slice(0,28));
    XL.writeFile(wb, `${filename}_${new Date().toISOString().slice(0,10)}.xlsx`);
}
function dv2ExportWht(kind, key, title, baseLbl, mo) {
    const arr = ((DashState.data.wht && DashState.data.wht[key]) || []).filter(x => x.mo === mo);
    const rows = dv2Desc(arr, x=>x.wht);
    const cols = [
        { h:'วันที่', w:90, get:r=>r.date },
        { h:'รายการ', w:160, get:r=>r.title },
        { h:'Company', w:160, get:r=>r.company },
        { h:'Customer', w:160, get:r=>r.customer },
        { h:'ค่าบริการ', w:100, get:r=>dv2F(r.base), raw:r=>r.base, align:'r', num:true, total:true },
        { h:baseLbl, w:100, get:r=>dv2F(r.wht), raw:r=>r.wht, align:'r', num:true, total:true },
        { h:'User', w:100, get:r=>r.user_id?(r.user_name||'-'):'—', align:'c' }
    ];
    if (kind === 'PDF') dv2OpenReportWindow(`รายงาน${title}`, `ประจำเดือน ${dv2MonthLabel(mo)} · RecordRevenue`, cols, rows);
    else dv2ExportExcel(`${title}_${mo}`, cols, rows);
}

// ── แผนรายจ่ายล่วงหน้า + ปฏิทิน ──
function dv2BuildPlanMonths() {
    const now = new Date();
    const months = [];
    for (let i = 0; i < 6; i++) {
        const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
        const y = d.getFullYear(), m = d.getMonth();
        const days = new Date(y, m + 1, 0).getDate();
        const dow = new Date(y, m, 1).getDay();
        months.push({ key: `${y}-${String(m+1).padStart(2,'0')}`, lbl: DV2_MONTH_TH[m], y, days, dow });
    }
    DashState.planMonths = months;
    return months;
}
function dv2PlanItemsForMonth(mkey) {
    return (DashState.data.plans || []).filter(p => (p.due_date||'').substring(0,7) === mkey);
}
function dv2PlanMonthTotal(mkey) { return dv2Sum(dv2PlanItemsForMonth(mkey), x=>x.amount); }
function dv2PlanActionIcons(p) {
    return `<span class="dv2-actions">
      <span onclick="event.stopPropagation();dv2OpenPlanModal('${p.plan_id}')" title="แก้ไข">✏️</span>
      <span onclick="event.stopPropagation();dv2DonePlan('${p.plan_id}')" title="ทำแล้ว">✅</span>
      <span onclick="event.stopPropagation();dv2DeletePlan('${p.plan_id}')" title="ลบ">🗑️</span></span>`;
}
function dv2CalHTML(mi) {
    const m = DashState.planMonths[mi];
    const items = dv2PlanItemsForMonth(m.key);
    const byDay = {};
    items.forEach(x => { const day = parseInt((x.due_date||'').substring(8,10),10); (byDay[day]=byDay[day]||[]).push(x); });
    let c = '';
    for (let i=0; i<m.dow; i++) c += '<div class="dv2-cday empty"></div>';
    for (let d=1; d<=m.days; d++) {
        const has = byDay[d];
        const sum = has ? dv2Sum(has) : 0;
        const sel = (DashState.selPlanDay === d) ? ' sel' : '';
        c += `<div class="dv2-cday${has?' has':''}${sel}" ${has?`onclick="dv2PickPlanDay(${d})"`:''}>
          <span class="dv2-cn">${d}</span>${has?`<span class="dv2-ca">${dv2F(sum)}</span>`:''}</div>`;
    }
    let detail = '';
    if (DashState.selPlanDay && byDay[DashState.selPlanDay]) {
        const dItems = byDay[DashState.selPlanDay];
        detail = `<div class="dv2-caldetail"><div class="dv2-xs" style="margin-bottom:7px">
          <b style="color:var(--h3);font-size:.8rem">${DashState.selPlanDay} ${m.lbl} ${m.y}</b> · ${dItems.length} รายการ</div>
          ${dItems.map(x => `<div class="dv2-item">
            <div class="dv2-itxt"><div class="dv2-iname"><span class="dv2-ico" style="font-size:.94rem">${x.icon||'💡'}</span> ${x.title}
              ${x.recurrence && x.recurrence!=='NONE' ? `<span class="dv2-chip" style="font-size:.62rem;padding:1px 7px">${x.recurrence==='MONTHLY'?'ทุกเดือน':x.recurrence==='QUARTERLY'?'ทุกไตรมาส':'ทุกปี'}</span>` : ''}</div>
              <div class="dv2-imeta">${dv2UserTag(x.created_by_user_id, x.user_name)}</div></div>
            <div style="display:flex;align-items:center;gap:9px"><span class="dv2-iamt dv2-neg">${dv2F(x.amount)}</span>${dv2PlanActionIcons(x)}</div></div>`).join('')}</div>`;
    } else {
        detail = `<div class="dv2-caldetail dv2-xs" style="text-align:center;padding:6px 0">แตะวันที่มีเงินเพื่อดูรายละเอียด</div>`;
    }
    return `<div class="dv2-calwrap">
      <div class="dv2-calhd"><b>📅 ${m.lbl} ${m.y}</b><span class="dv2-iamt dv2-neg">รวม ${dv2F(dv2PlanMonthTotal(m.key))}</span></div>
      <div class="dv2-cal">${DV2_DOW_TH.map(d=>`<div class="dv2-cdow">${d}</div>`).join('')}${c}</div>${detail}</div>`;
}
function dv2UpcomingHTML() {
    const items = [...(DashState.data.plans || [])].sort((a,b) => (a.due_date||'').localeCompare(b.due_date||''));
    if (!items.length) return `<div class="dv2-xs" style="text-align:center;padding:14px 0">ยังไม่มีแผนรายจ่าย</div>`;
    return `<div class="dv2-list">${items.map(x => `<div class="dv2-item">
      <div class="dv2-itxt"><div class="dv2-iname"><span class="dv2-ico" style="font-size:.95rem">${x.icon||'💡'}</span> ${x.title}
        ${x.recurrence && x.recurrence!=='NONE' ? `<span class="dv2-chip" style="font-size:.62rem;padding:1px 7px">${x.recurrence==='MONTHLY'?'ทุกเดือน':x.recurrence==='QUARTERLY'?'ทุกไตรมาส':'ทุกปี'}</span>` : ''}</div>
        <div class="dv2-imeta">${(x.due_date||'').substring(0,10)}${dv2UserTag(x.created_by_user_id, x.user_name)}</div></div>
      <div style="display:flex;align-items:center;gap:9px"><span class="dv2-iamt dv2-neg">${dv2F(x.amount)}</span>${dv2PlanActionIcons(x)}</div></div>`).join('')}</div>`;
}
function dv2Plan() {
    const months = dv2BuildPlanMonths();
    const monthsRow = `<div class="dv2-mrow">${months.map((m,i) => `<div class="dv2-mbox${DashState.openPlanIdx===i?' on':''}" onclick="dv2PickPlanMonth(${i})">
      <div class="dv2-xs">${m.lbl}</div><b>${dv2F(dv2PlanMonthTotal(m.key))}</b></div>`).join('')}</div>`;
    const listSide = `<div class="dv2-pl-list"><div class="dv2-pl-abs">
        <div class="dv2-xs" style="margin-bottom:6px;font-weight:500">รายการที่จะมาถึง · ${(DashState.data.plans||[]).length} รายการ</div>${dv2UpcomingHTML()}</div></div>`;
    const body = DashState.openPlanIdx >= 0
        ? `<div class="dv2-plansplit">${listSide}<div class="dv2-pl-cal">${dv2CalHTML(DashState.openPlanIdx)}</div></div>`
        : listSide;
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">📅</span>แผนรายจ่ายล่วงหน้า</span>
      <span class="dv2-chip on" onclick="dv2OpenPlanModal()">+ เพิ่ม</span></h3>${monthsRow}${body}</div>`;
}
function dv2PickPlanMonth(i) {
    DashState.openPlanIdx = (DashState.openPlanIdx === i) ? -1 : i;
    DashState.selPlanDay = null;
    dv2Render();
}
function dv2PickPlanDay(d) {
    DashState.selPlanDay = (DashState.selPlanDay === d) ? null : d;
    dv2Render();
}

// ── Planned Expense modal (add/edit) ──
function dv2FillPlanFormSelects() {
    const entSel = document.getElementById('plan-entity');
    if (entSel) {
        entSel.innerHTML = '<option value="">-- ทั้งครอบครัว --</option>' +
            ((DashState.data && DashState.data.entities) || []).map(e => `<option value="${e.entity_id}">${e.name}</option>`).join('');
    }
    const catSel = document.getElementById('plan-category');
    if (catSel) {
        const cats = (AppState.categories || []).filter(c => {
            const cap = (AppState.captions || []).find(x => x.type_id === c.caption_id);
            return cap && (cap.behavior === 'EXPENSE' || cap.behavior === 'LIABILITY') && cap.sub_behavior !== 'INVESTMENT';
        });
        catSel.innerHTML = '<option value="">-- ไม่ระบุ --</option>' + cats.map(c => `<option value="${c.category_id}">${c.name}</option>`).join('');
    }
}
function dv2OpenPlanModal(planId) {
    dv2FillPlanFormSelects();
    const modal = document.getElementById('plan-modal');
    const form = document.getElementById('plan-form');
    form.reset();
    document.getElementById('plan-id').value = planId || '';
    document.getElementById('plan-icon').value = '💡';
    if (planId) {
        const p = (DashState.data.plans || []).find(x => x.plan_id === planId);
        if (p) {
            document.getElementById('plan-modal-title').textContent = 'แก้ไขแผนรายจ่าย';
            document.getElementById('plan-icon').value = p.icon || '💡';
            document.getElementById('plan-title').value = p.title || '';
            document.getElementById('plan-amount').value = p.amount || 0;
            document.getElementById('plan-due-date').value = (p.due_date||'').substring(0,10);
            document.getElementById('plan-entity').value = p.entity_id || '';
            document.getElementById('plan-recurrence').value = p.recurrence || 'NONE';
            document.getElementById('plan-category').value = p.category_id || '';
            document.getElementById('plan-note').value = p.note || '';
        }
    } else {
        document.getElementById('plan-modal-title').textContent = 'เพิ่มแผนรายจ่าย';
        if (DashState.selPlanDay && DashState.openPlanIdx >= 0) {
            const d = DashState.planMonths[DashState.openPlanIdx];
            document.getElementById('plan-due-date').value = `${d.key}-${String(DashState.selPlanDay).padStart(2,'0')}`;
        }
    }
    modal.classList.remove('hidden');
}
function dv2ClosePlanModal() { document.getElementById('plan-modal').classList.add('hidden'); }
async function dv2SavePlan(evt) {
    evt.preventDefault();
    const id = document.getElementById('plan-id').value;
    const payload = {
        icon: document.getElementById('plan-icon').value,
        title: document.getElementById('plan-title').value,
        amount: parseFloat(document.getElementById('plan-amount').value) || 0,
        due_date: document.getElementById('plan-due-date').value,
        entity_id: document.getElementById('plan-entity').value || null,
        recurrence: document.getElementById('plan-recurrence').value,
        category_id: document.getElementById('plan-category').value || null,
        note: document.getElementById('plan-note').value || null
    };
    const headers = { 'x-user-id': encodeURIComponent(getUserIdHeader()), 'Content-Type': 'application/json' };
    try {
        const res = await fetch(`${API_BASE}/api/planned-expenses${id ? '/'+id : ''}`, {
            method: id ? 'PUT' : 'POST', headers, body: JSON.stringify(payload)
        });
        const j = await res.json();
        if (j.error) { showToast('บันทึกไม่สำเร็จ: ' + j.error, 'error'); return; }
        showToast('บันทึกแผนรายจ่ายแล้ว', 'success');
        dv2ClosePlanModal();
        loadDashboard();
    } catch (e) { showToast('บันทึกไม่สำเร็จ: ' + e.message, 'error'); }
}
async function dv2DonePlan(planId) {
    if (!confirm('ทำรายการนี้แล้วใช่ไหม?')) return;
    const headers = { 'x-user-id': encodeURIComponent(getUserIdHeader()), 'Content-Type': 'application/json' };
    try {
        await fetch(`${API_BASE}/api/planned-expenses/${planId}/done`, { method: 'POST', headers, body: JSON.stringify({}) });
        showToast('บันทึกว่าทำแล้ว', 'success');
        loadDashboard();
    } catch (e) { showToast('ผิดพลาด: ' + e.message, 'error'); }
}
async function dv2DeletePlan(planId) {
    if (!confirm('ลบแผนรายจ่ายนี้?')) return;
    const headers = { 'x-user-id': encodeURIComponent(getUserIdHeader()) };
    try {
        await fetch(`${API_BASE}/api/planned-expenses/${planId}`, { method: 'DELETE', headers });
        showToast('ลบแล้ว', 'success');
        loadDashboard();
    } catch (e) { showToast('ผิดพลาด: ' + e.message, 'error'); }
}

// ── Budget modal ──
function dv2OpenBudgetModal(categoryId) {
    const catSel = document.getElementById('budget-category');
    const cats = (AppState.categories || []).filter(c => {
        const cap = (AppState.captions || []).find(x => x.type_id === c.caption_id);
        return cap && (cap.behavior === 'EXPENSE' || cap.behavior === 'LIABILITY') && cap.sub_behavior !== 'INVESTMENT';
    });
    catSel.innerHTML = cats.map(c => `<option value="${c.category_id}">${c.name}</option>`).join('');
    if (categoryId) catSel.value = categoryId;
    const existing = (DashState.data.budget || []).find(b => b.category_id === catSel.value);
    document.getElementById('budget-amount').value = existing ? (existing.budget || '') : '';
    document.getElementById('budget-modal').classList.remove('hidden');
}
function dv2CloseBudgetModal() { document.getElementById('budget-modal').classList.add('hidden'); }
async function dv2SaveBudget(evt) {
    evt.preventDefault();
    const payload = {
        category_id: document.getElementById('budget-category').value,
        period_type: 'MONTHLY',
        period: `${DashState.year}-${DashState.month}`,
        amount: parseFloat(document.getElementById('budget-amount').value) || 0
    };
    const headers = { 'x-user-id': encodeURIComponent(getUserIdHeader()), 'Content-Type': 'application/json' };
    try {
        const res = await fetch(`${API_BASE}/api/budgets`, { method: 'POST', headers, body: JSON.stringify(payload) });
        const j = await res.json();
        if (j.error) { showToast('บันทึกไม่สำเร็จ: ' + j.error, 'error'); return; }
        showToast('บันทึกงบประมาณแล้ว', 'success');
        dv2CloseBudgetModal();
        loadDashboard();
    } catch (e) { showToast('บันทึกไม่สำเร็จ: ' + e.message, 'error'); }
}


/* ── หน้าตาแบบ A (mockup งาน 001 · 2026-10-15) ─────────────────────────────
   แถวบน: ตัวเลขสำคัญ 4 ตัว (รายรับ · รายจ่าย · คงเหลือสุทธิ · รอตรวจสอบ)
   แถว 2: เงินฝาก/เงินสด · บัตรเครดิต · เงินลงทุน (การ์ดเดิม)
   แถว 3: วงกลมรายรับตามหมวด · วงกลมรายจ่ายตามหมวด · เงินไปไหน 5 อันดับ
   ที่เหลือ (งบ · เฉลี่ย · ลูกหนี้/เจ้าหนี้ · ภาษีหัก ณ ที่จ่าย · แผน) อยู่ด้านล่างเหมือนเดิม */
const DV2_PAL = ['#7950F2', '#20C997', '#FF922B', '#4DABF7', '#F06595', '#ADB5BD'];
function dv2Kpis() {
    const d = DashState.data;
    const sIn = dv2Sum(d.income), sOut = dv2Sum(d.expense, x => Math.abs(x.amount)), net = sIn - sOut;
    const pend = DashState.pendingCount;
    const card = (ic, bg, col, label, val, sub, onclick) => `<div class="dv2-kpi"${onclick ? ` onclick="${onclick}" style="cursor:pointer"` : ''}>
        <span class="dv2-kic" style="background:${bg};color:${col}">${ic}</span>
        <div class="dv2-ktx"><div class="dv2-klab">${label}</div><div class="dv2-kval" style="color:${col}">${val}</div><div class="dv2-ksub">${sub}</div></div></div>`;
    return `<div class="dv2-kpis">
      ${card('<i class="fa-solid fa-arrow-trend-up"></i>', 'rgba(32,201,151,.14)', 'var(--pos)', `รายรับ${DashState.period === 'month' ? 'เดือนนี้' : ''}`, dv2F(sIn), `จาก ${(d.income || []).length} รายการ`)}
      ${card('<i class="fa-solid fa-arrow-down"></i>', 'rgba(240,82,82,.13)', 'var(--neg)', `รายจ่าย${DashState.period === 'month' ? 'เดือนนี้' : ''}`, dv2F(-sOut), `จาก ${(d.expense || []).length} รายการ`)}
      ${card('<i class="fa-solid fa-wallet"></i>', 'rgba(121,80,242,.13)', net < 0 ? 'var(--neg)' : 'var(--ac)', 'คงเหลือสุทธิ', dv2F(net), 'รายรับ - รายจ่าย')}
      ${card('<i class="fa-regular fa-clock"></i>', 'rgba(245,159,0,.15)', '#E67700', 'รอตรวจสอบ', pend == null ? '…' : `${pend.toLocaleString('en-US')} <small>รายการ</small>`, 'แตะเพื่อไปตรวจ', "switchView('pending')")}
    </div>`;
}
function dv2Donut(kind) {
    const isIn = kind === 'income';
    const a = (isIn ? DashState.data.income : DashState.data.expense) || [];
    const g = dv2ByCat(a, x => Math.abs(Number(x.amount) || 0));
    const total = g.reduce((s, x) => s + x.sum, 0);
    const top = g.slice(0, 5); const rest = g.slice(5).reduce((s, x) => s + x.sum, 0);
    if (rest > 0) top.push({ name: 'อื่น ๆ', sum: rest });
    let acc = 0;
    const stops = top.map((x, i) => { const from = acc; acc += total ? x.sum / total * 100 : 0; return `${DV2_PAL[i % DV2_PAL.length]} ${from}% ${acc}%`; }).join(',');
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">${isIn ? '📥' : '📤'}</span>${isIn ? 'รายรับตามหมวด' : 'รายจ่ายตามหมวด'}</span>
        <span class="dv2-xs">รวม <b class="${isIn ? 'dv2-pos' : 'dv2-neg'}">${dv2F(isIn ? total : -total)}</b></span><button class="dv2-zoombtn" onclick="dv2Zoom('${kind}')" title="ขยายดูชัด ๆ">🔍</button></h3>
      ${g.length ? `<div class="dv2-donutwrap"><div class="dv2-donut" style="background:conic-gradient(${stops})"><div><b>${dv2F(total)}</b><small>บาท</small></div></div>
        <div class="dv2-legend">${top.map((x, i) => `<div><i style="background:${DV2_PAL[i % DV2_PAL.length]}"></i><span>${x.name}</span><b class="${isIn ? '' : 'dv2-neg'}">${dv2F(isIn ? x.sum : -x.sum)}</b><em>${total ? (x.sum / total * 100).toFixed(1) : 0}%</em></div>`).join('')}</div></div>`
        : '<div class="dv2-xs" style="text-align:center;padding:24px 0">ไม่มีรายการในช่วงนี้</div>'}</div>`;
}
function dv2Top5() {
    const b = [...(DashState.data.budget || [])].filter(x => x.spent > 0).sort((p, q) => q.spent - p.spent).slice(0, 5);
    return `<div class="dv2-card"><h3><span class="dv2-ti"><span class="dv2-ico">🎯</span>เงินไปไหน</span>
        <span class="dv2-xs">5 อันดับรายจ่ายสูงสุด</span><button class="dv2-zoombtn" onclick="dv2Zoom('budget')" title="ดูทุกหมวด">🔍</button></h3>
      <div class="dv2-list">${b.length ? b.map((x, i) => `<div class="dv2-item"><div class="dv2-itxt"><div class="dv2-iname"><span class="dv2-rank">${i + 1}</span> ${x.category_name}</div>
        ${x.budget ? `<div class="dv2-imeta">งบ ${dv2F(x.budget)} · ${x.spent > x.budget ? 'เกินงบ' : 'เหลือ'} ${dv2F(Math.abs(x.budget - x.spent))}</div>` : ''}</div>
        <div class="dv2-iamt dv2-neg">${dv2F(-x.spent)}</div></div>`).join('') : '<div class="dv2-xs" style="text-align:center;padding:24px 0">ยังไม่มีรายจ่ายในช่วงนี้</div>'}</div></div>`;
}
async function dv2LoadPendingCount() {
    try {
        const res = await fetch(`${API_BASE}/api/transactions?status=PENDING_REVIEW&count=1`, { headers: { 'x-user-id': encodeURIComponent(getUserIdHeader()) } });
        DashState.pendingCount = Number((await res.json())?.count) || 0;
    } catch { DashState.pendingCount = null; }
}


/* ── หน้ารอตรวจสอบ แบบ A (mockup งาน 002 · 2026-10-15) ─────────────────────
   แถวบน: ตัวเลข 4 ตัว (รอตรวจ · รับ · จ่าย · ผลนำเข้าล่าสุด) + ปุ่มใหญ่ 3 ปุ่ม (PDF · Excel · เพิ่มเอง)
   ปุ่มใหญ่เรียกปุ่มเดิมในแถบหัว (ยังอยู่ แค่ซ่อนเมื่อใช้หน้าตาแบบ A) — ขั้นตอนนำเข้าเหมือนเดิมทุกอย่าง */
function renderPendingHero() {
    const box = document.getElementById('pending-hero'); if (!box) return;
    const list = AppState.pendingTransactions || [];
    let sIn = 0, sOut = 0, nIn = 0, nOut = 0;
    for (const tx of list) {
        const t = tx.auto_match?.type || tx.details?.[0]?.type || 'INCOME';
        const exp = t === 'EXPENSE' || t === 'CREDIT_AR' || Number(tx.details?.[0]?.amount) < 0;
        if (exp) { sOut += Math.abs(Number(tx.total_amount) || 0); nOut++; } else { sIn += Math.abs(Number(tx.total_amount) || 0); nIn++; }
    }
    let last = null; try { last = JSON.parse(localStorage.getItem('rr_last_import') || 'null'); } catch { /* */ }
    const f = n => dv2F(n);
    const kpi = (ic, bg, col, lab, val, sub) => `<div class="dv2-kpi"><span class="dv2-kic" style="background:${bg};color:${col}">${ic}</span>
        <div class="dv2-ktx"><div class="dv2-klab">${lab}</div><div class="dv2-kval" style="color:${col}">${val}</div><div class="dv2-ksub">${sub}</div></div></div>`;
    const sel = document.getElementById('import-account-selector');
    const accOpts = (AppState.accounts || []).map(a => `<option value="${a.account_id}" ${sel && sel.value === a.account_id ? 'selected' : ''}>${a.name}</option>`).join('');
    box.innerHTML = `<div class="ph-actions">
        <div class="ph-act ph-pdf"><span class="dv2-kic" style="background:rgba(240,82,82,.12);color:#E03131"><i class="fa-solid fa-file-pdf"></i></span>
          <div class="ph-at"><b>นำเข้า Statement</b><small style="margin-top:-2px">PDF ธนาคาร/บัตร · ภาพแคป TrueMoney/Shopee</small><select id="ph-acc" aria-label="เลือกบัญชี"><option value="">— เลือกบัญชีก่อน —</option>${accOpts}</select></div>
          <button type="button" class="ph-go" id="ph-pdf-go">เลือกไฟล์</button></div>
        <div class="ph-act ph-xlsw"><button type="button" id="ph-xls" class="ph-xbtn"><span class="dv2-kic" style="background:rgba(32,201,151,.14);color:#087F5B"><i class="fa-solid fa-file-excel"></i></span>
          <span class="ph-at"><b>นำเข้า Excel ▾</b><small>รายการ .xlsx · แม่แบบ · ข้อมูลเก่า</small></span></button>
          <div class="ph-menu" id="ph-xls-menu" hidden>
            <button type="button" data-x="normal">📥 นำเข้าเป็น "รอตรวจสอบ" (ตรวจซ้ำให้)</button>
            <button type="button" data-x="bulk-pending">📦 ข้อมูลเก่าจำนวนมาก → รอตรวจสอบ</button>
            <button type="button" data-x="bulk-confirmed">✅ ข้อมูลเก่าจำนวนมาก → บันทึกเป็นยืนยันแล้วเลย</button>
            <button type="button" data-x="template">⬇️ ดาวน์โหลดแม่แบบ Excel</button>
          </div></div>
        <button type="button" class="ph-act" id="ph-add"><span class="dv2-kic" style="background:rgba(121,80,242,.13);color:#6D4AE0"><i class="fa-solid fa-plus"></i></span>
          <span class="ph-at"><b>เพิ่มรายการเอง</b><small>บันทึกด้วยมือ</small></span></button>
        <label class="ph-act" id="ph-slip"><span class="dv2-kic" style="background:rgba(245,159,0,.15);color:#E67700"><i class="fa-solid fa-receipt"></i></span>
          <span class="ph-at"><b>สลิป / ใบเสร็จ / Order</b><small>เลือกทีละหลายร้อยรูปได้ · อัปไว้ก่อน ระบบทยอยอ่านและแนบให้เอง</small></span><span class="ph-go" id="ph-slip-go" style="display:grid;place-items:center">อัปโหลด</span>
          <input type="file" id="ph-slip-in" accept="image/*,application/pdf" multiple hidden></label>
      </div>
      <div class="ph-tools">${list.length ? `<button type="button" id="ph-autofill" class="pt-ok" title="รายการที่ยังไม่มีหมวด และผู้รับ/ร้านนี้เคยบันทึกหมวดเดิมสม่ำเสมอ → เติมให้ (ยังไม่ยืนยัน)">🪄 เติมหมวดจากประวัติ</button><button type="button" id="ph-bulkcat" class="pt-ok">🏷️ ใส่หมวดหลายรายการ</button><button type="button" id="ph-saveall" class="pt-ok">💾 บันทึกทั้งหมดที่พร้อม</button><button type="button" id="ph-group" class="pt-ok${AppState.pendingGroupMode ? ' on' : ''}" title="รวมรายการผู้รับ/ร้านเดียวกันเป็นกลุ่ม → ใส่หมวด/Company ทีเดียวทั้งกลุ่ม">👥 จัดกลุ่มผู้รับ/ร้าน</button><button type="button" id="ph-rules" class="pt-ok" title="ร้าน/ผู้รับที่ยืนยันหมวดเดิมซ้ำ → ยืนยันให้อัตโนมัติ">⚡ กฎอัตโนมัติ</button>` : ''}
        ${(() => { const all = AppState.pendingTransactions || [], n = all.filter(t => t.slip_image_url).length, f = AppState.pendingSlipFilter || 'ALL';
            return `<button type="button" class="ph-slipf${f === 'SLIP' ? ' on' : ''}" data-f="SLIP">📎 มีสลิป ${n.toLocaleString('en-US')}</button><button type="button" class="ph-slipf${f === 'NOSLIP' ? ' on' : ''}" data-f="NOSLIP">ไม่มีสลิป ${(all.length - n).toLocaleString('en-US')}</button>`; })()}
        ${DupPairs.count() ? `<button type="button" class="ph-slipf ph-dup${(AppState.pendingSlipFilter || '') === 'DUP' ? ' on' : ''}" data-f="DUP">🔁 อาจซ้ำ ${DupPairs.count().toLocaleString('en-US')}</button><button type="button" id="ph-dupall" class="pt-ok">🔁 รวมรายการซ้ำทั้งหมด</button>` : ''}
        ${TransferPairs.count() ? `<button type="button" class="ph-slipf ph-trf${(AppState.pendingSlipFilter || '') === 'TRF' ? ' on' : ''}" data-f="TRF" title="รายการออกจากบัญชีหนึ่ง กับเข้าอีกบัญชีของเรา ยอดเท่ากัน ห่างไม่เกิน 2 วัน">⇄ น่าจะเป็นโอน ${TransferPairs.count().toLocaleString('en-US')} คู่</button><button type="button" id="ph-trfall" class="pt-ok">⇄ ยืนยันโอนทั้งหมด</button>` : ''}
        <button type="button" id="ph-slipreview" class="pt-ok">🧾 สลิปที่ยังไม่จับคู่</button><span id="ph-queue" class="ph-queue"${SlipQueue.remaining() ? '' : ' hidden'}>${SlipQueue.label()}</span>
        <button type="button" id="ph-revchart" class="pt-ok">👥 ผังรายได้</button>
        ${pendingImportBatches().length ? `<button type="button" id="ph-delbatch">🗑️ ลบทั้งชุดที่นำเข้า</button>` : ''}</div>
      <div id="ph-status"></div>
      <div class="dv2-kpis">
        ${kpi('<i class="fa-regular fa-clock"></i>', 'rgba(245,159,0,.15)', '#E67700', 'รอตรวจสอบ', `${list.length.toLocaleString('en-US')} <small>รายการ</small>`, 'ตรวจแล้วกดบันทึก ✓')}
        ${kpi('<i class="fa-solid fa-arrow-trend-up"></i>', 'rgba(32,201,151,.14)', 'var(--success-color)', 'รวมรายรับ (รอตรวจ)', f(sIn), `จาก ${nIn} รายการ`)}
        ${kpi('<i class="fa-solid fa-arrow-down"></i>', 'rgba(240,82,82,.13)', 'var(--danger-color)', 'รวมรายจ่าย (รอตรวจ)', f(-sOut), `จาก ${nOut} รายการ`)}
        ${kpi('<i class="fa-solid fa-rotate"></i>', 'rgba(121,80,242,.13)', 'var(--primary-color)', 'ผลนำเข้าล่าสุด', last ? `${Number(last.imported || 0).toLocaleString('en-US')} <small>รายการ</small>` : '-',
            last ? `${last.merged ? `จับคู่สลิป ${last.merged} · ` : ''}ข้ามซ้ำ ${last.skipped || 0} · ${String(last.at || '').slice(0, 10)}` : 'ยังไม่เคยนำเข้า')}
      </div>`;
    // ข้อความความคืบหน้าการนำเข้า (ของเดิมอยู่ในแถบหัว) → ย้ายมาแสดงตรงนี้
    const st = document.getElementById('statement-upload-status'); if (st) document.getElementById('ph-status').appendChild(st);
    const acc = box.querySelector('#ph-acc');
    acc.onchange = () => { if (sel) { sel.value = acc.value; sel.dispatchEvent(new Event('change')); } };
    box.querySelector('#ph-pdf-go').onclick = () => {
        if (sel) sel.value = acc.value;   // ไม่เลือกบัญชีก็ได้ถ้านำเข้าหลายไฟล์ (ระบบหาบัญชีจากเลขในไฟล์)
        document.getElementById('btn-trigger-statement-upload')?.click();
    };
    // ปุ่มเดิมแสดงความคืบหน้า (กำลังอ่าน / กำลังบันทึก n/m) → สะท้อนมาที่ปุ่ม "เลือกไฟล์"
    const trig = document.getElementById('btn-trigger-statement-upload'), go = box.querySelector('#ph-pdf-go');
    if (trig && !trig._phObs) { const orig = trig.innerHTML; trig._phObs = new MutationObserver(() => { const g = document.getElementById('ph-pdf-go'); if (g) { g.innerHTML = trig.innerHTML === orig ? 'เลือกไฟล์' : trig.innerHTML; g.disabled = trig.disabled; } });
        trig._phObs.observe(trig, { childList: true, subtree: true, characterData: true, attributes: true }); }
    /* เมนู Excel: ปุ่มเดิมทั้ง 4 อย่างในแถบหัว (ซ่อนในหน้าตาแบบ A) — กดแล้วเรียกของเดิมตรง ๆ */
    const xm = box.querySelector('#ph-xls-menu');
    box.querySelector('#ph-xls').onclick = e => { e.stopPropagation(); xm.hidden = !xm.hidden; };
    xm.onclick = e => { const b = e.target.closest('[data-x]'); if (!b) return; xm.hidden = true;
        const st = document.getElementById('bulk-import-status-select');
        if (b.dataset.x === 'normal') document.getElementById('btn-pending-upload-csv')?.click();
        else if (b.dataset.x === 'template') document.getElementById('btn-pending-download-template')?.click();
        else { if (st) st.value = b.dataset.x === 'bulk-confirmed' ? 'CONFIRMED' : 'PENDING_REVIEW'; document.getElementById('bulk-import-file-input')?.click(); } };
    if (!window._phMenuClose) { window._phMenuClose = true; document.addEventListener('click', () => { const m = document.getElementById('ph-xls-menu'); if (m) m.hidden = true; }); }
    // หน้าต่างความคืบหน้าของการนำเข้าจำนวนมาก อยู่ในแถบหัวที่ซ่อน → ย้ายออกมาให้เห็น
    const ov = document.getElementById('bulk-import-overlay'); if (ov && ov.parentElement !== document.body) document.body.appendChild(ov);
    if (AppState._openXlsMenu) { AppState._openXlsMenu = false; xm.hidden = false; xm.scrollIntoView({ block: 'center' }); }
    box.querySelector('#ph-add').onclick = () => document.getElementById('btn-pending-add-row')?.click();
    const sin = box.querySelector('#ph-slip-in'); sin.onchange = () => { const fs = [...sin.files]; sin.value = ''; uploadSlipFiles(fs); };
    box.querySelector('#ph-delbatch')?.addEventListener('click', deleteImportBatch);
    box.querySelector('#ph-slipreview')?.addEventListener('click', () => SlipReview.open());
    box.querySelector('#ph-revchart')?.addEventListener('click', () => RevenueChart.open());
    box.querySelector('#ph-dupall')?.addEventListener('click', () => DupPairs.mergeAll());
    box.querySelector('#ph-trfall')?.addEventListener('click', () => TransferPairs.applyAll());
    box.querySelectorAll('.ph-slipf').forEach(b => b.onclick = () => { AppState.pendingSlipFilter = AppState.pendingSlipFilter === b.dataset.f ? 'ALL' : b.dataset.f; renderPendingTransactions(); renderPendingHero(); });
    box.querySelector('#ph-bulkcat')?.addEventListener('click', bulkCategorize);
    box.querySelector('#ph-autofill')?.addEventListener('click', autofillFromHistory);
    box.querySelector('#ph-saveall')?.addEventListener('click', bulkSaveReady);
    box.querySelector('#ph-rules')?.addEventListener('click', () => AutoRules.open());
    box.querySelector('#ph-group')?.addEventListener('click', () => { AppState.pendingGroupMode = !AppState.pendingGroupMode; AppState.pendingGroupKey = null; renderPendingTransactions(); renderPendingHero(); });
}


/* 🏷️ ใส่หมวดหลายรายการ + 💾 บันทึกทุกการ์ดที่พร้อม (2026-10-15 · ข้อเสนอ ข.)
   ใส่หมวด: เลือกคำในข้อความธนาคาร (เช่น "7-ELEVEN") → ทุกการ์ดรอตรวจที่ข้อความมีคำนี้ ได้หมวด/Company/คู่ค้าเดียวกัน (แถวย่อยแรก)
   บันทึกทั้งหมด: การ์ดที่มีหมวดครบและยอดลงตัว (✅) → บันทึก+ยืนยันทีละ 3 การ์ด แล้ว "จำ" สลิปที่มากับ LINE */
function pendingCards() { return [...document.querySelectorAll('#pending-cards-container .tx-card')]; }
function cardText(card) { return ((card.dataset.desc || '') + ' ' + (card.querySelector('.input-stmt-note')?.value || '')).toLowerCase(); }
/* 🪄 เติมหมวดจากประวัติให้ทุกการ์ดที่ยังไม่มีหมวด (2026-10-31 · ข้อเสนอ ก.)
   ใช้คำใบ้ที่ "มั่นใจ" เท่านั้น: ผู้รับ/ร้านเดียวกันเคยบันทึกหมวดเดียวกันทุกครั้ง หรือ ≥ 3 ครั้งและหมวดเดียวกัน ≥ 60% · เติมอย่างเดียว ยังไม่ยืนยัน */
async function autofillFromHistory() {
    await AppState._pendingRenderRest?.();   // ⚡ v255: การ์ดวาดตามการเลื่อน → วาดให้ครบก่อนทำทีละหลายรายการ
    const btn = document.getElementById('ph-autofill'), old = btn?.innerHTML; if (btn) { btn.disabled = true; btn.innerHTML = '⏳ กำลังหา…'; }
    try {
        const hints = (await (await fetch(`${API_BASE}/api/transactions/category-hints`)).json()).hints || {};
        let filled = 0, seen = 0;
        for (const c of pendingCards()) {
            const row = c.querySelector('.sub-row-item'); if (!row || row.querySelector('.select-category')?.value) continue;
            const tx = (AppState.pendingTransactions || []).find(t => t.transaction_id === c.dataset.txid); if (!tx) continue;
            seen++;
            const k = statementKey(tx.statement_desc), dir = (Number(tx.total_amount) < 0 || tx.details?.[0]?.type === 'EXPENSE') ? 'OUT' : 'IN';
            const h = k && (hints[dir + '|' + k] || hints['N:' + dir + '|' + (payeeKey(k) || k)]);   // ตรงทั้งบรรทัดก่อน · ไม่เจอ → ผู้รับเดียวกันต่างธนาคาร
            if (!h) continue;
            Similar.applyToCard(c, { category_id: h.category_id, entity_id: h.entity_id, contact_id: h.contact_id }, true);
            c.dataset.autofill = '1'; filled++;
        }
        alert(`🪄 เติมหมวดจากประวัติแล้ว ${filled} จาก ${seen} การ์ดที่ยังไม่มีหมวด (กรอบเขียว)\n\nตรวจแล้วกด "💾 บันทึกทั้งหมดที่พร้อม" หรือยืนยันทีละการ์ด`);
    } catch (e) { alert('เติมไม่สำเร็จ: ' + e.message); }
    finally { if (btn) { btn.disabled = false; btn.innerHTML = old; } }
}
async function bulkCategorize() {
    await AppState._pendingRenderRest?.();   // ⚡ v255: การ์ดวาดตามการเลื่อน → วาดให้ครบก่อนทำทีละหลายรายการ
    const cats = (AppState.categories || []).filter(c => !/uncategor/i.test(c.category_id || '') && !String(c.name || '').includes('รอการระบุ'));
    const caps = AppState.captions || [];
    const byCap = caps.map(cp => ({ cp, list: cats.filter(c => c.caption_id === cp.type_id) })).filter(x => x.list.length);
    const opt = list => list.map(x => `<option value="${x.id}">${String(x.name).replace(/</g, '&lt;')}</option>`).join('');
    const html = `<div style="text-align:left;display:grid;gap:10px">
        <label>ข้อความในรายการมีคำว่า<input id="bk-q" class="swal2-input" style="margin:4px 0 0;width:100%" placeholder="เช่น 7-ELEVEN, GRAB, ค่าไฟ"></label>
        <label>หมวด<select id="bk-cat" class="swal2-select" style="margin:4px 0 0;width:100%"><option value="">— เลือกหมวด —</option>${byCap.map(x => `<optgroup label="${String(x.cp.name).replace(/</g, '&lt;')}">${opt(x.list.map(c => ({ id: c.category_id, name: c.name })))}</optgroup>`).join('')}</select></label>
        <label>Company (ไม่บังคับ)<select id="bk-ent" class="swal2-select" style="margin:4px 0 0;width:100%"><option value="">— ไม่เปลี่ยน —</option>${opt((AppState.entities || []).map(e => ({ id: e.entity_id, name: e.name })))}</select></label>
        <label>คู่ค้า (ไม่บังคับ)<select id="bk-con" class="swal2-select" style="margin:4px 0 0;width:100%"><option value="">— ไม่เปลี่ยน —</option>${opt((AppState.contacts || []).map(c => ({ id: c.contact_id, name: c.name })))}</select></label>
        <label style="display:flex;gap:8px;align-items:center"><input type="checkbox" id="bk-empty" checked> เฉพาะการ์ดที่ยังไม่มีหมวด</label>
        <div id="bk-n" style="color:#5F3DC4;font-weight:700">พิมพ์คำเพื่อดูจำนวนการ์ดที่ตรง</div></div>`;
    const match = (q, onlyEmpty) => pendingCards().filter(c => q && cardText(c).includes(q) && (!onlyEmpty || !c.querySelector('.sub-row-item .select-category')?.value));
    const r = await Swal.fire({ title: 'ใส่หมวดหลายรายการ', html, width: 560, showCancelButton: true, cancelButtonText: 'ยกเลิก', confirmButtonText: 'ใส่หมวด',
        didOpen: () => { const upd = () => { const n = match(document.getElementById('bk-q').value.trim().toLowerCase(), document.getElementById('bk-empty').checked).length; document.getElementById('bk-n').textContent = `ตรง ${n} การ์ด`; };
            document.getElementById('bk-q').oninput = upd; document.getElementById('bk-empty').onchange = upd; },
        preConfirm: () => { const v = { q: document.getElementById('bk-q').value.trim().toLowerCase(), cat: document.getElementById('bk-cat').value, ent: document.getElementById('bk-ent').value, con: document.getElementById('bk-con').value, empty: document.getElementById('bk-empty').checked };
            if (!v.q) { Swal.showValidationMessage('พิมพ์คำที่ใช้ค้นก่อน'); return false; } if (!v.cat) { Swal.showValidationMessage('เลือกหมวดก่อน'); return false; } return v; } });
    if (!r.isConfirmed) return;
    const v = r.value, cards = match(v.q, v.empty);
    for (const c of cards) {
        const row = c.querySelector('.sub-row-item'); if (!row) continue;
        const cat = row.querySelector('.select-category'), cap = row.querySelector('.select-caption'), catObj = (AppState.categories || []).find(x => x.category_id === v.cat);
        if (cap && catObj?.caption_id) { cap.value = catObj.caption_id; cap.dispatchEvent(new Event('change')); }
        if (cat) { cat.value = v.cat; cat.dispatchEvent(new Event('change')); }
        if (v.ent) { const e = row.querySelector('.select-entity'); if (e) { e.value = v.ent; e.dispatchEvent(new Event('change')); } }
        if (v.con) { const e = row.querySelector('.select-contact'); if (e) { fillContactSelect(e); e.value = v.con; e.dispatchEvent(new Event('change')); } }
        c.style.outline = '2px solid #20C997';
    }
    try { showToast(`🏷️ ใส่หมวดแล้ว ${cards.length} การ์ด — ตรวจแล้วกด "บันทึกทั้งหมดที่พร้อม"`); } catch { /* */ }
}
function slipDocIdOf(card) { const m = String(card.dataset.slip || '').match(/\/api\/inbox\/file\/([\w-]+)/); return m ? m[1] : null; }
async function bulkSaveReady() {
    await AppState._pendingRenderRest?.();   // ⚡ v255: การ์ดวาดตามการเลื่อน → วาดให้ครบก่อนทำทีละหลายรายการ
    const ready = pendingCards().filter(c => { const rows = [...c.querySelectorAll('.sub-row-item')];
        return rows.length && rows.every(r => r.querySelector('.select-category')?.value && r.querySelector('.select-caption')?.value) && /✅/.test(c.querySelector('.zero-sum-status')?.textContent || ''); });
    if (!ready.length) { alert('ยังไม่มีการ์ดที่พร้อมบันทึก (ต้องมี Caption + หมวดครบทุกแถว และยอดลงตัว ✅)'); return; }
    if (!confirm(`บันทึกและยืนยัน ${ready.length} การ์ดที่พร้อมแล้ว?`)) return;
    const btn = document.getElementById('ph-saveall'), orig = btn?.innerHTML;
    let ok = 0, fail = 0, done = 0; const q = ready.slice(), errs = [];
    const worker = async () => { while (q.length) { const c = q.shift();
        const p = getCardPayload(c);
        if (p) try {
            const r = await fetch(`${API_BASE}/api/transactions`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-user-id': encodeURIComponent(getUserIdHeader()) }, body: JSON.stringify(p) });
            const j = await r.json().catch(() => ({}));
            if (r.ok && !j.error) { const cr = await fetch(`${API_BASE}/api/transactions/confirm`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ transaction_id: p.transaction_id }) });
                if (cr.ok) { ok++; const d = slipDocIdOf(c); if (d) fetch(`${API_BASE}/api/inbox/${d}/learn`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }).catch(() => {}); } else fail++; }
            else { fail++; errs.push(j.error || r.status); }
        } catch { fail++; } else fail++;
        done++; if (btn) btn.innerHTML = `⏳ ${done}/${ready.length}`; } };
    await Promise.all([worker(), worker(), worker()]);
    if (btn) btn.innerHTML = orig;
    alert(`✅ บันทึกแล้ว ${ok} รายการ` + (fail ? `\n⚠️ ไม่สำเร็จ ${fail}` + (errs.length ? `: ${[...new Set(errs)].slice(0, 3).join(' · ')}` : '') : ''));
    fetchMasterData(); loadPending();
}

// ── Top bar + master render ──
function dv2TopBar() {
    const p = DashState.period;
    const chip = (key, label) => `<span class="dv2-chip${p===key?' on':''}" onclick="dv2SetPeriod('${key}')">${label}</span>`;
    const nav = p === 'all' ? '' : `<button onclick="dv2ChangeMonth(-1)" title="${p==='year'?'ปีก่อน':'เดือนก่อน'}"><i class="fa-solid fa-chevron-left"></i></button>
        <span class="dv2-chip on dv2-plabel" style="cursor:default">${dv2PeriodLabel()}</span>
        <button onclick="dv2ChangeMonth(1)" title="${p==='year'?'ปีถัดไป':'เดือนถัดไป'}"><i class="fa-solid fa-chevron-right"></i></button>`;
    const thru = DashState.range?.last_date ? `<span class="dv2-thru">📅 ข้อมูลถึง ${dv2DateTH(DashState.range.last_date)}</span>` : '';
    const d = DashState.data || {};
    const mem = [`<span class="dv2-chip${DashState.member==='ALL'?' on':''}" onclick="dv2SetMember('ALL')">ทั้งหมด</span>`]
        .concat((d.members || []).map(m => `<span class="dv2-chip${DashState.member===m.user_id?' on':''}" onclick="dv2SetMember('${m.user_id}')">${m.name}</span>`)).join('');
    return `<div class="dv2-topbar">
      <div><h2>ภาพรวม</h2><div class="dv2-xs">สรุปสถานะการเงินของคุณและครอบครัว</div></div>
      <div class="dv2-period">
        <span class="dv2-pswitch dv2-members"><i class="fa-solid fa-user-group" style="opacity:.6;padding:0 4px"></i>${mem}</span>
        <span class="dv2-pswitch">${chip('month','เดือน')}${chip('year','ปี')}${chip('all','ทั้งหมด')}</span>
        ${nav}
        ${p === 'all' ? `<span class="dv2-chip on dv2-plabel" style="cursor:default">${dv2PeriodLabel()}</span>` : ''}
        <button onclick="loadDashboard()" title="โหลดใหม่"><i class="fa-solid fa-rotate-right"></i></button>
        ${thru}
      </div>
    </div>`;
}

/* ── หน้าขยาย (2026-09-08) ────────────────────────────────────────────
   North: "ข้อมูลตัวเล็กเกินไป ต้องการให้มีปุ่ม พอกดไปแล้วเห็นการ์ดในแต่ละเรื่อง
   และตัวเลขชัดเจน เช่น Statement ก็เห็นยอดคงเหลือทั้งหมด และบอกด้วยว่าข้อมูลถึงวันไหน"
   หน้าเดียวใช้กับทุกการ์ด — รับชนิดการ์ดแล้วดึงข้อมูลจาก DashState.data ชุดเดิม */
function dv2ZoomRows(kind) {
    const d = DashState.data || {};
    const accs = d.accounts || [];
    const owner = id => (DashState.member === 'ALL' && id) ? dv2OwnerName(id) : '';
    const money = x => Math.abs(Number(x.amount) || 0);
    switch (kind) {
        case 'stmt': {
            const a = dv2Desc(accs.filter(x => x.account_type !== 'CREDIT'), x => x.balance);
            return { title: '🏦 Statement · เงินฝาก/เงินสด', total: dv2Sum(a, x => x.balance), cls: 'dv2-accent',
                     sub: `${a.length} บัญชี · ยอดคงเหลือ ณ วันที่ข้อมูลล่าสุดของแต่ละบัญชี`, period: false,
                     rows: a.map(x => ({ name: `${x.account_type==='CASH'?'💵':'🏦'} ${x.name}`,
                            meta: [x.bank_name, owner(x.entity_id), x.last_date ? `รายการล่าสุด ${dv2DateTH(x.last_date)}` : 'ยังไม่มีรายการ', x.tx_count ? `${Number(x.tx_count).toLocaleString('en-US')} รายการ` : ''].filter(Boolean).join(' · '),
                            amount: x.balance, cls: Number(x.balance) < 0 ? 'dv2-neg' : '' })) };
        }
        case 'credit': {
            const a = dv2Desc(accs.filter(x => x.account_type === 'CREDIT'), x => x.balance);
            return { title: '💳 Credit Card · ยอดใช้ไป', total: dv2Sum(a, x => Math.abs(x.balance)), cls: 'dv2-neg',
                     sub: `${a.length} ใบ · ยอดค้างชำระ ณ วันที่ข้อมูลล่าสุด`, period: false,
                     rows: a.map(x => ({ name: `💳 ${x.name}`,
                            meta: [x.credit_limit ? `วงเงิน ${dv2F(x.credit_limit)}` : 'ยังไม่ตั้งวงเงิน', x.due_day ? `ครบกำหนดวันที่ ${x.due_day}` : '', owner(x.entity_id), x.last_date ? `รายการล่าสุด ${dv2DateTH(x.last_date)}` : ''].filter(Boolean).join(' · '),
                            amount: Math.abs(x.balance), cls: Math.abs(x.balance) > 0 ? 'dv2-neg' : '' })) };
        }
        case 'invest': {
            const a = d.investment || [];
            const g = dv2ByCat(a);
            return { title: '💎 Investment · เงินลงทุน ตามหมวด', total: dv2Sum(a), cls: dv2Sum(a) >= 0 ? 'dv2-pos' : 'dv2-neg',
                     sub: `${g.length} หมวด · ${a.length} รายการ · บวก = เงินกลับเข้ามา · ลบ = เงินออกไปลงทุน · แตะหมวดเพื่อดูรายการ`, period: true,
                     rows: g.map(x => ({ name: `${x.sum>=0?'📈':'📉'} ${x.name}`, meta: `${x.n} รายการ`, amount: x.sum, cls: x.sum >= 0 ? 'dv2-pos' : 'dv2-neg',
                            items: dv2Desc(x.items, i => i.amount).map(i => ({ name: i.title, meta: [dv2DateTH(i.date), owner(i.entity_id)].filter(Boolean).join(' · '), amount: i.amount, cls: i.amount >= 0 ? 'dv2-pos' : 'dv2-neg' })) })) };
        }
        case 'income': {
            const a = d.income || [];
            const g = dv2ByCat(a, x => Number(x.amount) || 0);
            return { title: '📥 รายรับ ตามหมวด', total: dv2Sum(a), cls: 'dv2-pos', sub: `${g.length} หมวด · ${a.length} รายการ · แตะหมวดเพื่อดูรายการ`, period: true,
                     rows: g.map(x => ({ name: x.name, meta: `${x.n} รายการ`, amount: x.sum, cls: 'dv2-pos',
                            items: dv2Desc(x.items, i => i.amount).map(i => ({ name: i.title, meta: [dv2DateTH(i.date), owner(i.entity_id), i.contact_name].filter(Boolean).join(' · '), amount: money(i), cls: 'dv2-pos' })) })) };
        }
        case 'expense': {
            const a = d.expense || [];
            const g = dv2ByCat(a, money);
            return { title: '📤 รายจ่าย ตามหมวด', total: dv2Sum(a, money), cls: 'dv2-neg', sub: `${g.length} หมวด · ${a.length} รายการ · แตะหมวดเพื่อดูรายการ`, period: true,
                     rows: g.map(x => ({ name: x.name, meta: `${x.n} รายการ`, amount: x.sum, cls: 'dv2-neg',
                            items: dv2Desc(x.items, i => i.amount).map(i => ({ name: i.title, meta: [dv2DateTH(i.date), owner(i.entity_id), i.contact_name].filter(Boolean).join(' · '), amount: money(i), cls: 'dv2-neg' })) })) };
        }
        case 'budget': {
            const a = [...(d.budget || [])].sort((p1, p2) => p2.spent - p1.spent);
            return { title: '🎯 เงินไปไหน · ค่าใช้จ่ายตามหมวด', total: dv2Sum(a, x => x.spent), cls: 'dv2-neg', sub: `${a.length} หมวด · เรียงจากมากไปน้อย`, period: true,
                     rows: a.map(x => ({ name: x.category_name, meta: x.budget ? `งบ ${dv2F(x.budget)} · ${x.spent > x.budget ? 'เกินงบ ' + dv2F(x.spent - x.budget) : 'เหลือ ' + dv2F(x.budget - x.spent)}` : 'ยังไม่ตั้งงบ', amount: x.spent, cls: x.budget && x.spent > x.budget ? 'dv2-neg' : '' })) };
        }
    }
    return null;
}
function dv2Zoom(kind) {
    const z = dv2ZoomRows(kind);
    if (!z) return;
    let el = document.getElementById('dv2-zoom');
    if (!el) { el = document.createElement('div'); el.id = 'dv2-zoom'; document.body.appendChild(el); }
    const thru = DashState.range?.last_date ? `ข้อมูลถึง ${dv2DateTH(DashState.range.last_date)}` : '';
    const period = z.period ? `ช่วงที่ดู: ${dv2PeriodLabel()}` : '';
    el.innerHTML = `<div class="dv2-zoom-box" role="dialog" aria-modal="true">
      <div class="dv2-zoom-head">
        <div><div class="dv2-zoom-title">${z.title}</div>
          <div class="dv2-zoom-sub">${[period, thru].filter(Boolean).join(' · ')}</div></div>
        <button class="dv2-zoom-close" onclick="dv2ZoomClose()" aria-label="ปิด">✕</button>
      </div>
      <div class="dv2-zoom-total ${z.cls}">${dv2F(z.total)}</div>
      <div class="dv2-zoom-sub2">${z.sub}</div>
      <div class="dv2-zoom-list">${z.rows.length ? z.rows.map(r => `<div class="dv2-zoom-row${r.items ? ' dv2-zoom-cat' : ''}"${r.items ? ' onclick="dv2ZoomToggle(this)"' : ''}>
          <div class="dv2-zoom-name">${r.items ? '<span class="dv2-zoom-caret">▸</span> ' : ''}${r.name}<div class="dv2-zoom-meta">${r.meta || ''}</div></div>
          <div class="dv2-zoom-amt ${r.cls || ''}">${dv2F(r.amount)}</div></div>${r.items ? `<div class="dv2-zoom-items" hidden>${r.items.map(i => `<div class="dv2-zoom-row dv2-zoom-sub">
          <div class="dv2-zoom-name">${i.name}<div class="dv2-zoom-meta">${i.meta || ''}</div></div>
          <div class="dv2-zoom-amt ${i.cls || ''}">${dv2F(i.amount)}</div></div>`).join('')}</div>` : ''}`).join('')
        : '<div class="dv2-zoom-empty">ไม่มีรายการในช่วงนี้</div>'}</div>
    </div>`;
    el.classList.add('open');
    document.body.style.overflow = 'hidden';
    el.onclick = e => { if (e.target === el) dv2ZoomClose(); };
    document.addEventListener('keydown', dv2ZoomEsc);
}
function dv2ZoomClose() {
    const el = document.getElementById('dv2-zoom');
    if (el) el.classList.remove('open');
    document.body.style.overflow = '';
    document.removeEventListener('keydown', dv2ZoomEsc);
}
function dv2ZoomEsc(e) { if (e.key === 'Escape') dv2ZoomClose(); }
function dv2ZoomToggle(row) {
    const items = row.nextElementSibling;
    if (!items || !items.classList.contains('dv2-zoom-items')) return;
    items.hidden = !items.hidden;
    row.classList.toggle('open', !items.hidden);
}
function dv2Render() {
    const root = document.getElementById('dv2-root');
    if (!root || !DashState.data) return;
    root.innerHTML = `${dv2TopBar()}
      ${dv2Kpis()}
      <div class="dv2-sec" id="fam-home"></div>
      <div class="dv2-sec" id="acc-home"><div class="av-mute" style="padding:14px">กำลังโหลดบัญชี…</div></div>
      <div class="dv2-sec dv2-g3">${dv2Stmt()}${dv2Credit()}${dv2Invest()}</div>
      <div class="dv2-sec dv2-g3">${dv2Donut('income')}${dv2Donut('expense')}${dv2Top5()}</div>
      <div class="dv2-sec dv2-g1">${dv2Budget()}</div>
      <div class="dv2-sec dv2-g3">${dv2Avg()}${dv2AR()}${dv2AP()}</div>
      <div class="dv2-sec dv2-g2">${dv2WhtCard('received','ถูกหัก ณ ที่จ่าย','เครดิตภาษีขอคืนได้','ถูกหัก')}${dv2WhtCard('withheld','หัก ณ ที่จ่ายไว้','ต้องนำส่งสรรพากร','หักไว้')}</div>
      <div class="dv2-sec dv2-g1">${dv2Plan()}</div>`;
}

async function loadDashboard() {
    try {
        await Promise.all([loadDashboardV2Data(), dv2LoadPendingCount()]);
        dv2Render();
        AccView.home(DashState.period === 'month' && DashState.month ? `${DashState.year}-${DashState.month}` : null);   // 🏦 การ์ดบัญชี (แนวคิด ข · 2026-10-30)
        FamView.load();   // 👨‍👩‍👧 ครอบครัว & ธุรกิจ (2026-10-31)
    } catch (err) {
        console.error('Dashboard Load Error:', err);
        const root = document.getElementById('dv2-root');
        if (root) root.innerHTML = `<div style="text-align:center;padding:40px;color:#993720;">โหลดข้อมูลไม่สำเร็จ: ${err.message}</div>`;
    }
}

// Removed pure canvas renderBarChart function as we now use Chart.js



function getBankIcon(bankName) {
    if (!bankName) return '💵';
    const name = bankName.toLowerCase();
    if (name.includes('kbank')) return '🟢';
    if (name.includes('scb')) return '🟣';
    if (name.includes('bay') || name.includes('krungsri')) return '🟡';
    if (name.includes('ktb')) return '🔵';
    if (name.includes('bbl')) return '🔵';
    return '💵';
}

function formatDate(dateStr) {
    if (!dateStr) return '';
    const datePart = dateStr.split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length === 3) {
        return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    return datePart;
}

function updateRowCategories(tr, captionId, selectedCatId) {
    const catSel = tr.querySelector('.select-category');
    if (!catSel) return;
    const cleanCats = AppState.categories.filter(c =>
        !c.name?.toLowerCase().includes('uncategor') &&
        !c.name?.includes('รอการระบุ') &&
        !c.category_id?.toLowerCase().includes('uncategor')
    );
    const filteredCats = captionId
        ? cleanCats.filter(c => c.caption_id === captionId)
        : cleanCats;

    const placeholder = captionId ? '-- เลือกหมวดหมู่ --' : 'Category';
    let html = `<option value="">${placeholder}</option>`;
    html += filteredCats.map(item => `<option value="${item.category_id}" ${item.category_id == selectedCatId ? 'selected' : ''}>${item.name}</option>`).join('');
    catSel.innerHTML = html;
}

