// 📄 PDF STATEMENT UPLOAD LOGIC
// ==========================================
function bindPendingPageActions() {
    // + เพิ่มรายการ
    document.getElementById("btn-pending-add-row")?.addEventListener("click", () => {
        createNewPendingCard();
    });

    // ดาวน์โหลด Template Excel (flat format with column widths)
    document.getElementById("btn-pending-download-template")?.addEventListener("click", () => {
        downloadCSVTemplate();
    });

    // นำเข้า Excel (normal — PENDING_REVIEW, check dups)
    document.getElementById("btn-pending-upload-csv")?.addEventListener("change", (e) => {
        const file = e.target.files[0];
        if (!file) return;
        parseExcelFileToPending(file);
        e.target.value = '';
    });

    // Bulk Import Excel (ข้อมูลเก่าจำนวนมาก — ส่ง batch 500 ต่อ call)
    document.getElementById("bulk-import-file-input")?.addEventListener("change", (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const statusSel = document.getElementById("bulk-import-status-select");
        const importStatus = statusSel ? statusSel.value : 'PENDING_REVIEW';
        bulkImportExcelFile(file, importStatus);
        e.target.value = '';
    });
}

// ==========================================
// 🏦 นำเข้า statement — ยกเครื่อง 2026-10-12 (ปรับจากของเดิม ไม่ได้สร้างใหม่)
//   1) อ่านตัวหนังสือใน PDF เองก่อน (ไม่ใช้ AI) — e-Statement ตรงถึงสตางค์ · ไม่ติดคิว AI (503)
//      ทดสอบ: KBANK 14 หน้า 462 รายการ ยอดฝาก/ถอนตรงกับที่ธนาคารพิมพ์
//   2) รหัสผ่าน PDF: ลองไม่ใส่ → บัญชีที่เลือก → ธนาคารเดียวกัน → ทุกบัญชีที่ตั้งรหัสไว้
//   3) อ่านเองไม่ได้ (สแกน/Print to PDF) → ใช้ AI แบบเดิม (เซิร์ฟเวอร์สลับรุ่นสำรองเมื่อ AI ไม่ว่าง)
//   4) สร้างรายการรอตรวจสอบทีละ 6 รายการพร้อมกัน (เดิมยิงทั้งหมดพร้อมกัน ไฟล์ใหญ่ล้ม)
// ==========================================
/* อ่าน statement จากตัวหนังสือใน PDF โดยไม่ใช้ AI (2026-10-12 · หลักการจากระบบ BKP)
   · จัดคำเป็นบรรทัดตามแกน y · บรรทัดที่ขึ้นต้นด้วยวันที่ = รายการ · บรรทัดไม่มีวันที่ใต้รายการ = ข้อความต่อ
   · ตัวเลขเงินขวาสุด = ยอดคงเหลือ · ทิศเงินเข้า/ออก ตัดสินจากผลต่างยอดคงเหลือ แล้วเทียบกับยอดที่อ่านได้
   · บรรทัด "ยอดยกมา" ไม่ใช่รายการ (ใช้เป็นยอดยกมาครั้งแรก) · ไม่ผ่านเกณฑ์ → คืน ok:false ให้ไปใช้ AI แทน */
/* 📌 ผู้ออกเอกสาร (ใช้จำรูปแบบนำเข้าต่อบัญชี · 2026-10-31) */
function detectStatementIssuer(text) {
  const t = String(text || '');
  if (/CardX|Card X Co/i.test(t)) return 'CardX';
  if (/KRUNGTHAI CARD|บัตรกรุงไทย|\bKTC\b/i.test(t)) return 'KTC';
  if (/KASIKORN|กสิกร|KBANK|K PLUS|K BIZ/i.test(t)) return 'KBank';
  if (/SIAM COMMERCIAL|ไทยพาณิชย์|\bSCB\b/i.test(t)) return 'SCB';
  if (/KRUNGSRI|AYUDHYA|กรุงศรี/i.test(t)) return 'Krungsri';
  if (/BANGKOK BANK|ธนาคารกรุงเทพ|\bBBL\b/i.test(t)) return 'BBL';
  if (/KRUNG THAI BANK|ธนาคารกรุงไทย|\bKTB\b/i.test(t)) return 'KTB';
  if (/\bttb\b|ทหารไทยธนชาต|TMBTHANACHART/i.test(t)) return 'ttb';
  return null;
}
async function parseTextStatement(pdf) {
  const MONEY = /^-?\(?[\d,]+\.\d{2}\)?$/;
  const DATE = /^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2}|\d{4})$/;
  const TIME = /^\d{1,2}:\d{2}(:\d{2})?$/;
  /* 2026-10-30: KBank ภาษาอังกฤษใช้ "Beginning Balance" — เดิมไม่รู้จัก → ไม่มียอดยกมา → แถวแรกเดาเป็นเงินออก (Transfer Deposit 2,134 กลายเป็นจ่าย) */
  const OPEN_RE = /ยอดยกมา|ยกมา|BROUGHT\s*FORWARD|Balance\s*Forward|Beginning\s*Balance|Opening\s*Balance/i, CLOSE_RE = /ยอดยกไป|CARRIED\s*FORWARD|Ending\s*Balance|Closing\s*Balance/i;
  const num = s => { const neg = /^\(.*\)$|^-/.test(s); const v = Number(String(s).replace(/[(),-]/g, '')); return neg ? -v : v; };
  const r2 = n => Math.round(n * 100) / 100;
  const isoDate = (d, m, y) => { let yy = +y; if (yy < 100) yy = yy >= 40 ? yy + 2500 - 543 : yy + 2000; if (yy > 2400) yy -= 543;
    if (+m < 1 || +m > 12 || +d < 1 || +d > 31) return null; return `${yy}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`; };
  const rows = []; let opening = null, closing = null, accountNumber = null, textChars = 0, allTxt = '', taxX = null;
  for (let p = 1; p <= pdf.numPages; p++) {
    const page = await pdf.getPage(p);
    const tc = await page.getTextContent();
    const items = tc.items.filter(it => it.str && it.str.trim() && !/^[lI|]{1,4}$/.test(it.str.trim())).map(it => { const [a, b] = it.transform, rot = Math.abs(b) > Math.abs(a);
      /* 2026-10-31 · กรุงไทย Business (JasperReports): หน้าแนวนอนที่ตัวหนังสือหมุน 90° → แถว = แกน x · คอลัมน์ = แกน y → สลับแกนกลับให้เป็นแนวปกติ */
      return { x: rot ? (b > 0 ? it.transform[5] : -it.transform[5]) : it.transform[4], y: rot ? (b > 0 ? -it.transform[4] : it.transform[4]) : it.transform[5], s: it.str.trim().replace(/[\u0158-\u0161]/g, c => String(c.charCodeAt(0) - 0x158)), w: it.width || 0 }; });   /* v266 กรุงไทย: ตัวเลขในฟอนต์ฝังแสดงเป็น Ř–š (U+0158…0161 = 0…9) เช่น /řŘŠŞŠŚ = /108682 */   // ตัดขีดขอบกระดาษ "l"/"ll" (2026-10-30)
    textChars += items.reduce((n, it) => n + it.s.length, 0);
    if (allTxt.length < 20000) allTxt += items.map(it => it.s).join(' ') + '\n';
    /* 2026-10-30 · SCB: วันที่กับเวลาอยู่ช่องเดียว "05/01/26 22:02" → แยกเป็น 2 ช่อง (เดิมไม่เจอวันที่ → "ไม่พบตารางรายการ") */
    for (let k = items.length - 1; k >= 0; k--) {
      /* 2026-10-31 · กรุงศรี ออมทรัพย์: "01/11/2025 01:01:19 รับโอนเงิน" วันที่ เวลา และรายการอยู่ช่องเดียว → แยกเป็น 3 ช่อง */
      const m = items[k].s.match(/^(\d{1,2}[-/.]\d{1,2}[-/.](?:\d{2}|\d{4}))\s+(\d{1,2}:\d{2}(?::\d{2})?)(?:\s+(.+))?$/);
      if (m) items.splice(k, 1, { ...items[k], s: m[1] }, { ...items[k], x: items[k].x + 0.5, s: m[2] }, ...(m[3] ? [{ ...items[k], x: items[k].x + 1, s: m[3].trim() }] : []));
    }
    if (!accountNumber) { const a = items.find(it => /^[\dXx*]{3}-[\dXx*]-[\dXx*]{5}-[\dXx*]$|^[\dXx*]{3}-[\dXx*]{6}-[\dXx*]$/.test(it.s)); if (a) accountNumber = a.s; }
    // จัดเป็นบรรทัด (y ใกล้กัน ≤ 2.5)
    items.sort((a, b) => b.y - a.y || a.x - b.x);
    const lines = [];
    for (const it of items) { const L = lines.find(l => Math.abs(l.y - it.y) <= 2.5); if (L) L.items.push(it); else lines.push({ y: it.y, items: [it] }); }
    lines.sort((a, b) => b.y - a.y);
    let prevRow = null;
    /* v265 · กรุงไทย: คอลัมน์ "ภาษี" (ภาษีหัก ณ ที่จ่ายของดอกเบี้ย) → ไม่ใช่ยอดรายการ · ยอดที่เข้าจริง = ยอด − ภาษี */
    { const th = items.find(it => /^ภาษี$|^Tax$/i.test(it.s)); if (th) taxX = th.x; }
    for (const L of lines) {
      L.items.sort((a, b) => a.x - b.x);
      const first = L.items[0], dm = first.s.match(DATE);
      /* 2026-10-30 · SCB: บรรทัด "ยอดเงินคงเหลือยกมา (BALANCE BROUGHT FORWARD)" ไม่มีวันที่ → เดิมถูกข้าม ไม่มียอดยกมา */
      if (!dm) {
        const lt = L.items.filter(it => !MONEY.test(it.s)).map(it => it.s).join(' '), lm = L.items.filter(it => MONEY.test(it.s));
        if (lm.length === 1 && OPEN_RE.test(lt) && opening == null) { opening = num(lm[0].s); prevRow = null; continue; }
        if (lm.length === 1 && CLOSE_RE.test(lt)) { closing = num(lm[0].s); prevRow = null; continue; }
      }
      if (dm) {
        const date = isoDate(dm[1], dm[2], dm[3]);
        const rest = L.items.slice(1);
        const money = rest.filter(it => MONEY.test(it.s));
        const text = rest.filter(it => !MONEY.test(it.s) && !TIME.test(it.s) && !DATE.test(it.s));
        const time = rest.find(it => TIME.test(it.s))?.s || null;
        const all = text.map(t => t.s).join(' ');
        if (!date || !money.length) { prevRow = null; continue; }
        const balIt = money[money.length - 1];
        if (OPEN_RE.test(all)) { if (opening == null) opening = num(balIt.s); prevRow = null; continue; }
        if (CLOSE_RE.test(all)) { closing = num(balIt.s); prevRow = null; continue; }
        if (money.length < 2) { prevRow = null; continue; }
        const taxIt = taxX != null ? money.find(m => m !== balIt && Math.abs(m.x - taxX) < 30) : null;
        const amtIt = money.filter(m => m !== balIt && m !== taxIt && num(m.s) !== 0).pop() || money.filter(m => m !== balIt && m !== taxIt).pop() || money[money.length - 2];
        const left = text.filter(t => t.x < amtIt.x), right = text.filter(t => t.x > balIt.x);
        const row = { date, time, amountAbs: Math.abs(num(amtIt.s)), tax: taxIt ? Math.abs(num(taxIt.s)) : 0, balance: num(balIt.s), desc: left.map(t => t.s).join(' '), tail: right.map(t => t.s), tailX: right.length ? right[right.length - 1].x : null, y: L.y };
        rows.push(row); prevRow = row;
      } else if (prevRow && prevRow.tailX != null && L.items.every(it => !MONEY.test(it.s)) && Math.abs(L.items[0].x - prevRow.tailX) < 6 && prevRow.y - L.y < 30) {
        prevRow.tail[prevRow.tail.length - 1] += ' ' + L.items.map(it => it.s).join(' ');   // ข้อความต่อบรรทัด
        prevRow.y = L.y;
      } else if (!dm) { /* หัว/ท้ายกระดาษ */ }
    }
  }
  if (textChars < 200) return { ok: false, reason: 'ไฟล์นี้ไม่มีตัวหนังสือ (สแกน/Print to PDF)' };
  if (rows.length < 1) return { ok: false, reason: 'ไม่พบตารางรายการที่อ่านได้' };
  // ทิศทางเงินจากผลต่างยอดคงเหลือ
  let prev = opening ?? r2(rows[0].balance - 0);   // ไม่มียอดยกมา → แถวแรกตัดสินไม่ได้
  let agree = 0, firstUnknown = opening == null;
  const out = rows.map((r, i) => {
    let amount, wht = 0;
    /* ไม่มียอดยกมา: แถวแรกดูจากคำ (ฝาก/รับ/Deposit = เข้า) แทนการเดาว่าออกเสมอ */
    if (i === 0 && firstUnknown) amount = /deposit|รับโอน|รับเงิน|ฝาก|เงินเข้า|transfer\s*in|interest|ดอกเบี้ย/i.test([r.desc, ...r.tail].join(' ')) && !/withdraw|ถอน|โอนไป|จ่าย/i.test(r.desc) ? r.amountAbs : -r.amountAbs;
    else {
      const diff = r2(r.balance - prev);
      if (Math.abs(Math.abs(diff) - r.amountAbs) < 0.005) { amount = diff; agree++; }
      /* มีภาษีหัก: เงินเข้า = ยอด − ภาษี · เงินออก = ยอด + ภาษี */
      else if (r.tax && (Math.abs(diff - (r.amountAbs - r.tax)) < 0.005 || Math.abs(diff + r.amountAbs + r.tax) < 0.005)) { amount = diff; wht = r.tax; agree++; }
      else amount = -r.amountAbs;
    }
    prev = r.balance;
    return { date: r.date, time: r.time, description: [r.desc, ...r.tail].filter(Boolean).join(' · '), amount, balance: r.balance, ...(wht ? { wht } : {}) };
  });
  const checkable = out.length - (firstUnknown ? 1 : 0);
  const rate = checkable ? agree / checkable : 0;
  if (checkable && rate < 0.95) return { ok: false, reason: `อ่านตัวเลขได้ไม่ตรงยอดคงเหลือ ${Math.round((1 - rate) * 100)}%` };
  return { ok: true, lines: out, opening, closing: closing ?? out[out.length - 1].balance, account_number: accountNumber, agree, checkable, issuer: detectStatementIssuer(allTxt) };
}

function statementPdfPasswords(accId) {
    const accs = AppState.accounts || [];
    const sel = accs.find(a => a.account_id === accId);
    return [...new Set([sel?.pdf_password,
        ...accs.filter(a => a.pdf_password && a.bank_name && a.bank_name === sel?.bank_name).map(a => a.pdf_password),
        ...accs.map(a => a.pdf_password)].filter(Boolean).map(String))];
}
/* เปิด PDF ด้วย pdf.js โดยลองรหัสตามลำดับ · คืน { pdf, password } หรือ { needPassword: true } */
/* 💳 อ่านใบแจ้งยอดบัตรเครดิตจากตัวหนังสือใน PDF (2026-10-30 · North: "ในชุดเอกสารเดียวกันมีบัตร 2 ใบ · ยอดติดลบ = ชำระหรือยกเลิก")
   · แยกรายการตามหัว "เลขที่บัตร" (เช่น KBank: "/ ACCOUNT DETAILS KBANK-SHOPEE 4221 82XX XXXX 3000") · แต่ละบัตร: PREVIOUS BALANCE = ยกมา · TOTAL BALANCE = ยกไป
   · แถวรายการ = วันที่ใช้บัตร วันที่บันทึก รายละเอียด ยอด · ยอดบวก = ใช้จ่าย · ติดลบ = เงินเข้าบัตร (ชำระ = "PAYMENT/ชำระ/ขอบคุณ" · ที่เหลือ = คืนเงิน/ยกเลิก)
   · กรุงศรี: ส่วน "รายการชำระเงิน" มาก่อนหัวบัตร → ใส่บัตรแรก · ตรวจ ยกมา + ใช้จ่าย − เงินเข้า = ยกไป ต่อบัตร
   · ไม่ใช่ใบแจ้งยอดบัตร / อ่านไม่ได้ → ok:false (ไปใช้ AI ตามเดิม) */
async function parseCardStatement(pdf) {
  /* 2026-10-30 · CardX (บัตร SCB เดิม): วันที่รายการไม่มีปี "10/11" → ใช้ DM แล้วเติมปีจากวันสรุปยอด */
  /* 2026-10-30 · KTC: "- 120.00" (ลบมีช่องว่าง) · เลขบัตร "4304-45XX-XXXX-3128" (คั่นด้วยขีด) */
  const MONEY = /^-?\s?\(?[\d,]+\.\d{2}\)?-?$/, DATE = /^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/, DM = /^(\d{1,2})\/(\d{1,2})$/;
  const CARD = /(\d{4})[\s-]?(\d{2})[Xx*]{2}[\s-]?[Xx*]{4}[\s-]?(\d{4})/;
  const num = s => { const neg = /^\(.*\)$|^-|-$/.test(s); const v = Number(String(s).replace(/[(),\s-]/g, '')); return neg ? -v : v; };
  const r2 = n => Math.round(n * 100) / 100;
  /* ปี 2 หลัก: < 60 = ค.ศ. (25 → 2025) · ≥ 60 = พ.ศ. (68 → 2025) · ปี 4 หลัก พ.ศ. → ลบ 543 */
  const iso = (d, m, y) => { let yy = +y; if (yy < 100) yy = yy >= 60 ? 2500 + yy - 543 : 2000 + yy; if (yy > 2400) yy -= 543; return `${yy}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`; };
  const cards = [], byKey = {}, loose = []; let cur = null, stmtDate = null, allText = '', wantStmtDate = false, postFirst = false, anyCard = null;
  /* 2026-10-31 · กรุงศรี HomePro: ฟอนต์ไทยฝังแบบเข้ารหัส → ชื่อรายการอ่านเป็น "Ñ¯Ï…" · เก็บแถวไว้ก่อน แล้วตั้งชื่อจากบรรทัดสรุปภาษาอังกฤษที่ตามมา
     · ตาราง "สรุปรายการบัญชีทั้งหมด" (เลขบัตร · วันสรุปยอด · วงเงิน · ยอดใช้ไป) = ยอดยกไปของแต่ละบัตร */
  const sumClose = {}; let gq = [];
  const GARBLED = s => !/[A-Za-zก-๙]/.test(s) && /[\u00A0-\u024F]/.test(s);
  const cardOf = m => { const key = m[3], masked = `${m[1]} ${m[2]}XX XXXX ${m[3]}`; if (!byKey[key]) { byKey[key] = { masked, last4: key, type: '', opening: null, closing: null, rows: [] }; cards.push(byKey[key]); } return byKey[key]; };
  for (let p = 1; p <= pdf.numPages; p++) {
    const tc = await (await pdf.getPage(p)).getTextContent();
    /* ขีดดำขอบกระดาษ (เครื่องหมายเครื่องพิมพ์) ถูกเก็บเป็นตัวอักษร "l"/"ll" อยู่บรรทัดเดียวกับรายการ → ตัดทิ้ง ไม่งั้นบรรทัดไม่ขึ้นต้นด้วยวันที่แล้วถูกข้าม (2026-10-30 · 13/05/26 134.00 หาย) */
    const items = tc.items.filter(it => it.str && it.str.trim() && !/^[lI|]{1,4}$/.test(it.str.trim())).map(it => ({ x: it.transform[4], y: it.transform[5], s: it.str.trim(), r: it.transform[4] + (it.width || 0) }));
    items.sort((a, b) => b.y - a.y || a.x - b.x);
    const lines = [];
    for (const it of items) { const L = lines.find(l => Math.abs(l.y - it.y) <= 2.5); if (L) L.items.push(it); else lines.push({ y: it.y, items: [it] }); }
    lines.sort((a, b) => b.y - a.y);
    for (const L of lines) {
      L.items.sort((a, b) => a.x - b.x);
      const text = L.items.map(i => i.s).join(' '); allText += text + '\n';
      const textNS = text.replace(/\s+/g, '');   // กรุงศรี: ตัวไทยแตกเป็นชิ้น "ยอ ด เรียกเก็บขอ ง …" → เทียบแบบไม่มีช่องว่าง
      /* 2026-10-30 · CardX: คอลัมน์แรก = วันที่บันทึก (POSTING) คอลัมน์สอง = วันที่เกิดรายการ → ใช้คอลัมน์สอง (KBank กลับกัน) */
      { const pi = L.items.find(i => /^POSTING/i.test(i.s)), ti = L.items.find(i => /^TRANS(ACTION)?$|^TRANS\b/i.test(i.s)); if (pi && ti) postFirst = pi.x < ti.x; }
      const money = L.items.filter(i => MONEY.test(i.s)), dates = L.items.filter(i => DATE.test(i.s));
      if (!stmtDate && /STATEMENT DATE|วันที่สรุปยอด/i.test(text) && dates.length) { const d = dates[dates.length - 1].s.match(DATE); stmtDate = iso(d[1], d[2], d[3]); }
      /* CardX: หัวข้อ "CLOSING DATE / วันสรุปยอดบัญชี" อยู่บรรทัดหนึ่ง วันที่อยู่บรรทัดถัดไป (วันแรกในบรรทัด) */
      else if (!stmtDate && wantStmtDate && dates.length) { const d = dates[0].s.match(DATE); stmtDate = iso(d[1], d[2], d[3]); wantStmtDate = false; }
      if (!stmtDate && /CLOSING DATE|วันสรุปยอดบัญชี/i.test(text) && !dates.length) wantStmtDate = true;
      const cm = text.match(CARD); if (cm && !anyCard) anyCard = cm;
      /* กรุงศรี: หัวกระดาษหน้าแรก "เลขบัตร  31/05/26" (ไม่มีคำว่าวันที่สรุปยอด) = วันสรุปยอด */
      if (!stmtDate && p === 1 && cm && dates.length === 1 && !money.length) { const d = dates[0].s.match(DATE); stmtDate = iso(d[1], d[2], d[3]); continue; }
      /* หัวบัตร: มีเลขบัตร ไม่มีตัวเงิน ไม่มีวันที่ (ไม่ใช่แถวสรุปวงเงิน/ใบนำฝาก) */
      if (cm && !money.length && !dates.length) { cur = cardOf(cm); const t = text.match(/ACCOUNT DETAILS\s+(.+?)\s+\d{4}\s?\d{2}[Xx*]/i) || text.match(/\d{4}\s?\d{2}[Xx*]{2}\s?[Xx*]{4}\s?\d{4}\s+([A-Za-z][A-Za-z ]+?)(?:\s+[\d,]+)*$/);
        if (t && !cur.type) cur.type = t[1].trim(); continue; }
      /* กรุงศรี: "ยอดรวมที่ต้องชำระสำหรับบัตรเครดิต / Total Payment Due For Credit Card" = ยอดยกไป (ใช้เมื่อยอดเดินตรงเท่านั้น ดูท้ายฟังก์ชัน) */
      if (/Interest and Other Fees Amount/i.test(text) && money.length) { gq.forEach(r => { r.desc = r.value < 0 ? 'ยกเลิกดอกเบี้ย/ค่าธรรมเนียม' : 'ดอกเบี้ย/ค่าธรรมเนียม'; }); gq = []; continue; }
      if (/Total Payments\b/i.test(text) && money.length) { gq.forEach(r => { if (r.value < 0) r.desc = 'ชำระบัตร (PAYMENT)'; }); gq = []; continue; }
      if (cm && money.length && !dates.length && L.items.some(i => /^\d{1,2}$/.test(i.s)) && !/[A-Za-z]{3,}/.test(text.replace(CARD, ''))) { sumClose[cm[3]] = num(money[money.length - 1].s); continue; }
      if (/TOTAL PAYMENT DUE FOR CREDIT CARD/i.test(text) && money.length) { const t = cur || cards[cards.length - 1]; if (t && t.dueClose == null) t.dueClose = num(money[money.length - 1].s); continue; }
      if (/PREVIOUS BALANCE|ยอดเรียกเก็บของรอบบัญชีที่แล้ว|ยอดเรียกเก็บรอบที่แล้ว|ยอดยกมา/i.test(text + ' ' + textNS) && money.length) { const v = num(money[money.length - 1].s); if (cur) { if (cur.opening == null) cur.opening = v; } else loose.opening = v; continue; }
      if (/TOTAL BALANCE|สรุปยอดรอบนี้/i.test(text) && money.length) { if (cur && cur.closing == null && cur.rows.length) cur.closing = num(money[money.length - 1].s); else if (!cur && !cards.length && loose.length && loose.closing == null) loose.closing = num(money[money.length - 1].s); cur = null; continue; }
      const f0 = L.items[0]?.s.match(DATE) || L.items[0]?.s.match(DM), f1 = L.items[1]?.s.match(DATE) || L.items[1]?.s.match(DM);
      if (f0 && f1 && money.length) {
        const amtIt = money[money.length - 1], v = num(amtIt.s);
        let desc = L.items.slice(2).filter(i => i.x < amtIt.x && !MONEY.test(i.s)).map(i => i.s).join(' ').replace(/\s+/g, ' ').trim();
        const garbled = GARBLED(desc); if (garbled) desc = 'รายการบัตร (ชื่อร้านอ่านจากไฟล์ไม่ได้)';
        if (!/[A-Za-zก-๙]/.test(desc) || /x\s*\d+%|ดอกเบี้ย.*=/.test(desc)) continue;
        /* CardX: บรรทัดรับชำระไม่มีเครื่องหมายลบ ("Payment received from Easy App 57,770.73") → เป็นเงินเข้า */
        const row = { d0: postFirst ? f1 : f0, d1: postFirst ? f0 : f1, desc, value: r2(v > 0 && /PAYMENT RECEIVED|รับชำระ/i.test(desc) ? -v : v), right: amtIt.r, raw: v };
        /* รับแถวเฉพาะในหัวบัตรที่ยังไม่ปิด (หลัง TOTAL BALANCE = ส่วนตัวอย่างคิดดอกเบี้ย/ใบนำฝาก) · ก่อนเจอหัวบัตรแรก = ส่วนรายการชำระ (กรุงศรี) */
        if (garbled) gq.push(row);
        if (cur && cur.closing == null) cur.rows.push(row); else if (!cur && !cards.length) loose.push(row);
      }
    }
  }
  /* KTC: บรรทัดเลขบัตรมีวงเงินอยู่ด้วย (ไม่ใช่หัวบัตรตามกติกา) → ไฟล์บัตรใบเดียว: ใช้เลขบัตรแรกที่เจอ กับรายการทั้งหมด */
  if (!cards.length && anyCard && loose.length) { const c = cardOf(anyCard); c.opening = loose.opening ?? null; c.closing = loose.closing ?? null; c.rows.push(...loose.splice(0)); }
  if (!cards.length || !/CREDIT CARD|บัตรเครดิต|Billing Statement/i.test(allText)) return { ok: false, reason: 'ไม่ใช่ใบแจ้งยอดบัตรเครดิต' };
  /* แปลงวันที่: มีปีใช้ปีนั้น · ไม่มีปี (วัน/เดือน) → ปีของวันสรุปยอด ถ้าเดือนเกินเดือนสรุปยอด = ปีก่อน */
  const sY = stmtDate ? +stmtDate.slice(0, 4) : new Date().getFullYear(), sM = stmtDate ? +stmtDate.slice(5, 7) : 12;
  const toIso = m => m[3] ? iso(m[1], m[2], m[3]) : iso(m[1], m[2], String(+m[2] > sM ? sY - 1 : sY));
  for (const r of [...loose, ...cards.flatMap(c => c.rows)]) if (r.d0) { r.date = toIso(r.d0); r.post = toIso(r.d1); delete r.d0; delete r.d1; }
  if (loose.length) { cards[0].rows.unshift(...loose); if (cards[0].opening == null && loose.opening != null) cards[0].opening = loose.opening;
    if (cards[0].closing == null && loose.closing != null) cards[0].closing = loose.closing; }   // KTC: ยอดยกไป "สรุปยอดรอบนี้" อยู่ก่อนหัวบัตร (หน้า 2)
  { const t = allText.match(/TYPE OF CARD\s*:?\s*([^\n]+)/i); if (t && cards.length === 1 && !cards[0].type) cards[0].type = t[1].trim(); }   // KTC: "ประเภทบัตร TYPE OF CARD : KTC VISA SIGNATURE"
  const used = cards.filter(c => c.rows.length || c.closing);
  if (!used.some(c => c.rows.length)) return { ok: false, reason: 'ไม่พบรายการในใบแจ้งยอด' };
  for (const c of used) {
    c.sum = r2(c.rows.reduce((t, r) => t + r.value, 0));
    /* ยอดยกไปจากตารางสรุปบัญชี (ใช้เมื่อหายอดยกไปแบบอื่นไม่ได้) · ไม่มียอดยกมา (ป้ายเป็นฟอนต์อ่านไม่ได้) → ยกมา = ยกไป − รายการ */
    if (c.closing == null && sumClose[c.last4] != null) { c.closing = sumClose[c.last4]; if (c.opening == null) { c.opening = r2(c.closing - c.sum); c.openDerived = true; } }
    /* ยอดยกไปจาก "Total Payment Due" (กรุงศรี) ใช้เมื่อ ยกมา + รายการ = ยอดนั้นพอดี (กันไปหยิบยอดขั้นต่ำของบัตรอื่น) */
    if (c.closing == null && c.dueClose != null && c.opening != null && Math.abs(r2(c.opening + c.sum) - c.dueClose) < 0.01) c.closing = c.dueClose;
    c.agree = c.opening != null && c.closing != null ? Math.abs(r2(c.opening + c.sum) - c.closing) < 0.01 : null;
    /* 2026-10-30 · CardX: เครื่องหมายลบไม่อยู่ในตัวหนังสือ (วาดแยก) แต่ตัวเลขติดลบชิดขวาน้อยกว่าตัวอื่น ~3.4 จุด
       → ยอดเดินไม่ตรง: ลองกลับเครื่องหมายแถวที่ขอบขวาสั้นกว่าคอลัมน์ · ใช้เฉพาะเมื่อกลับแล้วยอดเดินตรง */
    if (c.agree === false) {
      const maxR = Math.max(...c.rows.map(r => r.right || 0));
      const cand = c.rows.filter(r => r.raw > 0 && r.right && maxR - r.right > 1.5 && maxR - r.right < 8);
      const trial = c.rows.map(r => cand.includes(r) ? -Math.abs(r.raw) : r.value), sum2 = r2(trial.reduce((t, v) => t + v, 0));
      if (cand.length && Math.abs(r2(c.opening + sum2) - c.closing) < 0.01) { c.rows.forEach((r, i) => { r.value = r2(trial[i]); }); c.sum = sum2; c.agree = true; }
    }
    c.txs = c.rows.map(r => {
      const pay = r.value < 0 && /PAYMENT|ชำระ|ขอบคุณ|THANK YOU/i.test(r.desc);
      return { date: r.date, time: '00:00:00', type: r.value > 0 ? 'EXPENSE' : 'INCOME', amount: Math.abs(r.value), ref_code: null,
        statement_desc: r.desc, note: r.value < 0 ? (pay ? 'ชำระบัตร' : /IPP|INSTAL/i.test(r.desc) ? 'แปลงเป็นผ่อนชำระ (IPP)' : 'คืนเงิน/ยกเลิกรายการ') : null, balance: null };
    });
  }
  return { ok: true, cards: used, statementDate: stmtDate, issuer: detectStatementIssuer(allText) };
}

/* นำเข้าใบแจ้งยอดบัตรที่อ่านแล้ว: บัตรละ 1 บัญชี (หาบัญชีบัตรจากเลขบัตรในตั้งค่า · ไม่เจอ = ให้เลือก) แล้วผ่านด่านตรวจเดิม (statementPrecheck) ทีละบัตร */
/* รอบบัญชีบัตร: วันสรุปยอดเดือนก่อน + 1 วัน → วันสรุปยอด (ช่วง statement ไม่ขึ้นกับวันที่รายการแรก/สุดท้าย) */
function cardCycle(stmtDate, txs) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(stmtDate || '')) return {};
  const [y, m, d] = stmtDate.split('-').map(Number), prev = new Date(Date.UTC(y, m - 2, Math.min(d, 28)));
  if (d > 28) prev.setUTCDate(Math.min(d, new Date(Date.UTC(y, m - 1, 0)).getUTCDate()));
  const from = new Date(prev.getTime() + 864e5).toISOString().slice(0, 10), first = (txs || []).map(t => t.date).sort()[0];
  return { period_from: first && first < from ? first : from, period_to: stmtDate };
}
async function importCardStatement(card, selectedAccId, fileName, btn, fileObj = null) {
  const accs = AppState.accounts || [], f = n => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const guess = c => {
    const hit = accs.filter(a => statementAccountMatches(c.masked, a.account_number) === true);
    if (hit.length === 1) return hit[0].account_id;
    const tail = accs.filter(a => a.account_type === 'CREDIT' && String(a.account_number || '').replace(/[^0-9]/g, '').endsWith(c.last4));   // ใส่เลขบัตรไว้แค่ 4 ตัวท้าย
    if (tail.length === 1) return tail[0].account_id;
    return card.cards.length === 1 ? selectedAccId : ''; };
  const plan = card.cards.map(c => ({ c, acc: guess(c) }));
  const opts = sel => `<option value="">— ไม่นำเข้าบัตรนี้ —</option>` + accs.map(a => `<option value="${esc(a.account_id)}"${a.account_id === sel ? ' selected' : ''}>${a.account_type === 'CREDIT' ? '💳' : '🏦'} ${esc(a.name)}</option>`).join('');
  const html = `<div style="text-align:left;font-size:.9rem">ในไฟล์นี้มีบัตร <b>${plan.length}</b> ใบ — แต่ละบัตรนำเข้าเป็นคนละบัญชี${plan.map((p, i) => `
    <div style="border:1px solid #E9E3FA;border-radius:12px;padding:10px 12px;margin-top:10px">
      <div><b>💳 ${esc(p.c.masked)}</b> ${esc(p.c.type)}</div>
      <div style="color:#5C5872;font-size:.82rem">${p.c.rows.length} รายการ · ยกมา ${f(p.c.opening)} · ใช้จ่าย ${f(p.c.rows.filter(r => r.value > 0).reduce((t, r) => t + r.value, 0))} · เงินเข้า (ชำระ/คืนเงิน) ${f(-p.c.rows.filter(r => r.value < 0).reduce((t, r) => t + r.value, 0))} · ยกไป ${f(p.c.closing)}
        ${p.c.agree === true ? '<span style="color:#087F5B">✅ ยอดเดินตรง</span>' : p.c.agree === false ? '<span style="color:#C92A2A">⚠️ ยอดเดินไม่ตรง</span>' : ''}</div>
      <select data-i="${i}" style="width:100%;margin-top:6px;min-height:40px;border-radius:10px">${opts(p.acc)}</select>
      ${p.acc ? '' : '<div style="color:#E67700;font-size:.8rem;margin-top:4px">ยังไม่รู้ว่าเป็นบัตรไหน — เลือกบัญชีบัตร (ใส่เลขบัตรใน ตั้งค่า→บัญชี ครั้งหน้าระบบเลือกให้เอง)</div>'}
    </div>`).join('')}</div>`;
  const ok = window.Swal ? (await Swal.fire({ title: '💳 ใบแจ้งยอดบัตรเครดิต', html, width: 620, showCancelButton: true, confirmButtonText: 'นำเข้า', cancelButtonText: 'ยกเลิก',
      preConfirm: () => { document.querySelectorAll('.swal2-html-container select[data-i]').forEach(s => { plan[+s.dataset.i].acc = s.value; }); } })).isConfirmed
    : confirm(`ในไฟล์มีบัตร ${plan.length} ใบ — นำเข้าแยกบัญชีตามเลขบัตร?`);
  if (!ok) return null;
  const done = [];
  for (const p of plan) {
    if (!p.acc) continue;
    const useAcc = await statementPrecheck(p.acc, { account_number: p.c.masked, rows: p.c.txs, opening: p.c.opening, closing: p.c.closing });
    if (!useAcc) continue;
    /* จุดตรวจยอด: ยอดค้างตามใบแจ้งยอด ณ วันสรุปยอด (ระบบเก็บบัตรเป็นลบ) */
    if (p.c.closing != null) window._rrCheckpoint = { account_id: useAcc, as_of: card.statementDate || p.c.txs.map(t => t.date).sort().pop(), balance: -Math.abs(p.c.closing) };
    const res = await importStatementRows(useAcc, p.c.txs, (d, n) => { if (btn) btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> 💳 ${p.c.last4} ${d}/${n}`; },
      { opening: p.c.opening, closing: p.c.closing, source_kind: 'CREDIT_CARD', file_name: `${fileName} · ${p.c.masked}`, ...cardCycle(card.statementDate, p.c.txs),
        format: { kind: 'CARD', issuer: card.issuer, parser: 'card', read: p.c.masked }, walk: p.c.agree });
    if (fileObj && res.stmtId) DriveStore.saveStatement(fileObj, useAcc, res.stmtId, card.statementDate);   // 📁 เก็บไฟล์ต้นฉบับใน Drive (2026-10-31)
    done.push(`💳 ${p.c.masked} → ${(accs.find(a => a.account_id === useAcc) || {}).name || useAcc}: นำเข้า ${res.importedCount}` + (res.mergedCount ? ` · จับคู่ ${res.mergedCount}` : '') + (res.skippedCount ? ` · มีอยู่แล้ว ${res.skippedCount}` : '') + (res.removedCount ? ` · 🧹 ลบที่ซ้ำ ${res.removedCount}` : '') + (res.errorCount ? ` · ⚠️ ไม่สำเร็จ ${res.errorCount}` : '') +
      (res.skippedCount && res.addedDetails?.length && res.addedDetails.length <= 10 ? `\n   ➕ ${res.addedDetails.join('\n   ➕ ')}` : ''));
  }
  alert('อ่านใบแจ้งยอดบัตรจากตัวหนังสือในไฟล์ (ไม่ใช้ AI)\n\n' + (done.join('\n') || 'ไม่ได้นำเข้าบัตรใด'));
  loadPending();
  return done.length;
}

async function openStatementPdf(fileBytes, accId) {
    if (typeof pdfjsLib === 'undefined') return {};
    for (const pw of ['', ...statementPdfPasswords(accId)]) {
        try { const pdf = await pdfjsLib.getDocument({ data: new Uint8Array(fileBytes.slice(0)), password: pw || undefined }).promise; return { pdf, password: pw || null }; }
        catch (e) { if (e?.name !== 'PasswordException') return {}; }
    }
    return { needPassword: true };
}
/* เลขบัญชีในไฟล์ตรงกับบัญชีที่เลือกไหม (ไฟล์มักปิดบางหลัก) */
function statementAccountMatches(read, mine) {
    /* 2026-10-31 (North: "บัตรเครดิตเปลี่ยนเลขบัตรภายหลัง"): ใส่ได้หลายเลขในบัญชีเดียว คั่นด้วย , / ; หรือขึ้นบรรทัดใหม่ (เลขใหม่ + เลขเก่า) → ตรงเลขใดเลขหนึ่ง = บัญชีนี้ */
    const parts = String(mine || '').split(/[,;\n/|]+/).map(x => x.trim()).filter(Boolean);
    if (parts.length > 1) { const rs = parts.map(x => statementAccountMatches(read, x)); return rs.includes(true) ? true : rs.includes(false) ? false : null; }
    const norm = x => String(x || '').toLowerCase().replace(/\*/g, 'x').replace(/[^0-9x]/g, '');
    const groups = norm(read).split('x').filter(g => g.length >= 3), b = norm(mine).replace(/x/g, '');
    if (!groups.length || b.length < 4) return null;
    return groups.every(g => b.includes(g));
}
/* ✅ ตรวจก่อนนำเข้า statement (2026-10-15 · North: "นำเข้าผิดบัญชี ให้ระบบตรวจสอบความถูกต้องก่อนนำเข้า")
   แสดงสรุปทุกครั้งก่อนบันทึก: เลขบัญชีในไฟล์เทียบบัญชีที่เลือก · ถ้าไม่ตรงแต่ตรงกับบัญชีอื่น → เสนอให้สลับ
   ช่วงวันที่ · จำนวน · เงินเข้า/ออก · ยอดยกมา/ยกไป · คืนค่า account_id ที่จะใช้ หรือ null = ยกเลิก */
async function statementPrecheck(accId, info) {
    const accs = AppState.accounts || [], me = accs.find(a => a.account_id === accId);
    const read = info.account_number || '';
    const match = read ? statementAccountMatches(read, me?.account_number) : null;
    const other = read && match !== true ? accs.find(a => a.account_id !== accId && statementAccountMatches(read, a.account_number) === true) : null;
    const rows = info.rows || [], dates = rows.map(r => String(r.date).slice(0, 10)).filter(Boolean).sort();
    const sIn = rows.filter(r => r.type !== 'EXPENSE').reduce((t, r) => t + Math.abs(+r.amount || 0), 0);
    const sOut = rows.filter(r => r.type === 'EXPENSE').reduce((t, r) => t + Math.abs(+r.amount || 0), 0);
    const f = n => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    /* 💰 ยอดยกมา (2026-10-15 · North: "บัญชีธนาคารไม่รวมยอดยกมา"): เทียบยอดยกมาในไฟล์กับยอดในระบบ ณ วันแรกของไฟล์
       ยังไม่มีรายการก่อนหน้า → เสนอสร้างยอดยกมาให้ (ชุดยอดยกมาของบัญชีนี้ ณ วันแรก · ฝั่งตรงข้ามรอใส่ใน ตั้งค่า → ยอดยกมา)
       มีรายการก่อนหน้าแล้วแต่ยอดไม่ตรง → เตือน (ผิดบัญชี / มีช่วงที่ยังไม่ได้นำเข้า) */
    const firstDate = [...(info.rows || [])].map(r => String(r.date).slice(0, 10)).filter(Boolean).sort()[0];
    const isCredit = me?.account_type === 'CREDIT';
    const wantOpen = info.opening != null && !isNaN(+info.opening) ? (isCredit ? -Math.abs(+info.opening) : +info.opening) : null;
    let bal = null;
    if (wantOpen != null && firstDate) { try { const r = await fetch(`${API_BASE}/api/accounts/balance-at?account_id=${encodeURIComponent(accId)}&date=${firstDate}`); if (r.ok) bal = await r.json(); } catch { /* */ } }
    const fm = n => { const v = Number(n || 0), t = Math.abs(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); return v < 0 ? `(${t})` : t; };
    let openHtml = '';
    if (bal && bal.count === 0 && Math.abs(wantOpen) >= 0.005)
        openHtml = `<label style="display:flex;gap:8px;align-items:flex-start;padding:10px 12px;border-radius:12px;background:#F3F0FF;margin-top:10px;cursor:pointer"><input type="checkbox" id="pc-open" checked style="margin-top:4px">
            <span>💰 บัญชีนี้ยังไม่มียอดยกมา — <b>สร้างยอดยกมา ${fm(wantOpen)}</b> ณ ${firstDate} ให้เลย<br><small style="color:#5C5872">ยอดบัญชีจะตรงกับ statement · อีกฝั่ง (ทุน/บัญชีพัก) ไปใส่ต่อที่ ตั้งค่า → ยอดยกมา</small></span></label>`;
    else if (bal && bal.count > 0 && Math.abs(bal.balance - wantOpen) >= 0.01)
        openHtml = `<div style="padding:10px 12px;border-radius:12px;background:#FFF5F5;color:#C92A2A;margin-top:10px">⚠️ ยอดยกมาในไฟล์ <b>${fm(wantOpen)}</b> ไม่ตรงกับยอดในระบบ ณ ${firstDate} <b>${fm(bal.balance)}</b> (ต่าง ${fm(wantOpen - bal.balance)})<br><small>อาจเลือกบัญชีผิด หรือยังมีช่วงก่อนหน้าที่ไม่ได้นำเข้า</small></div>`;
    else if (bal && bal.count > 0)
        openHtml = `<div style="padding:8px 12px;border-radius:12px;background:#E6FCF5;color:#087F5B;margin-top:10px">✅ ยอดยกมาในไฟล์ตรงกับยอดในระบบ (${fm(wantOpen)})</div>`;
    let state, note;
    if (match === true) { state = 'ok'; note = `✅ เลขบัญชีในไฟล์ <b>${esc(read)}</b> ตรงกับบัญชีที่เลือก`; }
    else if (match === false) { state = 'bad'; note = `❌ เลขบัญชีในไฟล์ <b>${esc(read)}</b> <u>ไม่ตรง</u> กับบัญชีที่เลือก (${esc(me?.account_number || '-')})`; }
    else if (read && !me?.account_number) { state = 'warn'; note = `⚠️ ไฟล์เป็นบัญชี <b>${esc(read)}</b> แต่บัญชีที่เลือกยังไม่ได้ใส่เลขบัญชีในตั้งค่า — เทียบไม่ได้`; }
    else { state = 'warn'; note = '⚠️ อ่านเลขบัญชีจากไฟล์ไม่ได้ — ตรวจชื่อบัญชีให้แน่ใจก่อนกดนำเข้า'; }
    const html = `<div style="text-align:left;font-size:.92rem;line-height:1.6">
        <div style="padding:10px 12px;border-radius:12px;margin-bottom:10px;background:${state === 'ok' ? '#E6FCF5' : state === 'bad' ? '#FFF5F5' : '#FFF9DB'};color:${state === 'ok' ? '#087F5B' : state === 'bad' ? '#C92A2A' : '#7A4A00'}">${note}
          ${other ? `<br>👉 ตรงกับบัญชี <b>${esc(other.name)}</b> (${esc(other.account_number)})` : ''}</div>
        <div>🏦 นำเข้าเข้าบัญชี: <b>${esc(me?.name || accId)}</b></div>
        <div>📅 ช่วงวันที่: <b>${dates[0] || '-'} ถึง ${dates[dates.length - 1] || '-'}</b></div>
        <div>🧾 จำนวน: <b>${rows.length.toLocaleString('en-US')} รายการ</b> · เข้า <b style="color:#087F5B">${f(sIn)}</b> · ออก <b style="color:#C92A2A">(${f(sOut)})</b></div>
        ${info.opening != null || info.closing != null ? `<div>💰 ยอดยกมา ${f(info.opening)} → ยอดยกไป ${f(info.closing)}</div>` : ''}
        ${openHtml}
        <div style="color:#5C5872;font-size:.8rem;margin-top:6px">รายการที่มีอยู่แล้วจะถูกข้าม · รายการที่ตรงกับสลิป/ที่บันทึกไว้ก่อนจะจับคู่ ไม่สร้างซ้ำ</div></div>`;
    if (!window.Swal) {
        if (other && confirm(`${note.replace(/<[^>]+>/g, '')}\nไฟล์นี้ตรงกับบัญชี ${other.name}\nกดตกลง = นำเข้าเข้าบัญชี ${other.name}`)) return other.account_id;
        return confirm(`นำเข้า ${rows.length} รายการ เข้าบัญชี ${me?.name || accId}?`) ? accId : null;
    }
    const r = await Swal.fire({ title: 'ตรวจก่อนนำเข้า', html, width: 560, icon: state === 'bad' ? 'warning' : undefined,
        showCancelButton: true, cancelButtonText: 'ยกเลิก',
        showDenyButton: !!other, denyButtonText: other ? `นำเข้าเข้า ${other.name}` : '', denyButtonColor: '#087F5B',
        confirmButtonText: state === 'bad' ? `ยืนยัน นำเข้าเข้า ${me?.name || ''}` : 'นำเข้า', confirmButtonColor: state === 'bad' ? '#C92A2A' : '#5F3DC4',
        focusConfirm: state !== 'bad', focusCancel: state === 'bad', preConfirm: () => ({ open: !!document.getElementById('pc-open')?.checked }) });
    let closeVal = info.closing != null && info.closing !== '' && !isNaN(+info.closing) ? +info.closing : null;
    /* 2026-10-31: ไม่มียอดยกไปแยก (AI อ่าน / ไฟล์ที่ไม่มีบรรทัดยกไป) → ใช้ยอดคงเหลือของบรรทัดสุดท้าย → ขึ้น Bank ใน Balance Check */
    if (closeVal == null) { const withBal = rows.filter(r => r.balance != null && r.balance !== '' && isFinite(+r.balance)); if (withBal.length) closeVal = +withBal[withBal.length - 1].balance; }
    const setCp = id => { const a = accs.find(x => x.account_id === id); window._rrCheckpoint = closeVal == null || !dates.length ? null
        : { account_id: id, as_of: dates[dates.length - 1], balance: a?.account_type === 'CREDIT' ? -Math.abs(closeVal) : closeVal }; };
    if (r.isDenied && other) { const sel = document.getElementById('import-account-selector'); if (sel) sel.value = other.account_id; setCp(other.account_id); return other.account_id; }
    if (r.isConfirmed) setCp(accId);
    if (r.isConfirmed && r.value?.open && bal?.count === 0) {
        try {
            const res = await fetch(`${API_BASE}/api/inbox/opening`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({
                set_id: null, name: `ยอดยกมา ${me?.name || accId} (จาก statement)`, date: firstDate, entity_id: me?.entity_id || null, anchor_account_id: null,
                lines: [{ kind: 'ACC', account_id: accId, side: wantOpen >= 0 ? 'DR' : 'CR', amount: Math.abs(wantOpen) }] }) });
            const j = await res.json().catch(() => ({}));
            if (!res.ok || j.error) alert('สร้างยอดยกมาไม่สำเร็จ: ' + (j.error || res.status) + '\n(นำเข้ารายการต่อได้ · ใส่ยอดยกมาเองที่ ตั้งค่า → ยอดยกมา)');
            else try { showToast(`💰 สร้างยอดยกมา ${fm(wantOpen)} แล้ว`); } catch { /* */ }
        } catch (e) { alert('สร้างยอดยกมาไม่สำเร็จ: ' + e.message); }
    }
    return r.isConfirmed ? accId : null;
}

/* 📄 แถว "ยอดธนาคาร" ในการ์ดตรวจยอด (2026-10-30)
   มียอดธนาคาร → แสดงวันที่ + ✅ ตรง / ⚠️ ต่าง + ปุ่มปรับ · ยังไม่มี → ปุ่มใส่ยอดธนาคาร */
function toggleBalanceCheck() {
    let open = false; try { open = localStorage.getItem('rr_bk_open') === '1'; localStorage.setItem('rr_bk_open', open ? '0' : '1'); } catch { AppState._bkOpenMem = !AppState._bkOpenMem; }
    renderSharedStatusSummary();
}
function bankCheckHtml(accId, cp, acc) {
    const isCredit = acc?.account_type === 'CREDIT';
    if (!cp) return `<button type="button" class="acc-recon" onclick="recordBankBalance('${accId}')" title="ใส่ยอดคงเหลือตามธนาคาร เพื่อตรวจว่าข้อมูลครบไหม">📝 ใส่ยอดธนาคาร</button>`;
    const d = String(cp.as_of || '').split('-'), dd = d.length === 3 ? `${d[2]}/${d[1]}/${d[0].slice(2)}` : cp.as_of;
    const ok = Math.abs(cp.diff || 0) < 0.005;
    const shown = cp.bank;
    return `<div class="bank-chk">
        <div class="bc-row"><span>📄 ธนาคาร ณ ${dd}${cp.source === 'STATEMENT' ? '' : ' ✍️'}</span><b>${formatCurrency(shown)}</b>
          <button type="button" class="bc-edit" title="ใส่ยอดธนาคารใหม่" onclick="recordBankBalance('${accId}')">✏️</button></div>
        <div class="bc-row"><span>🧮 ระบบ ณ ${dd}</span><b>${formatCurrency(cp.system)}</b><span class="bc-sp"></span></div>
        ${ok ? `<div class="bc-ok">✅ ตรงกับธนาคาร</div>`
             : `<div class="bc-bad">⚠️ ต่าง ${formatCurrency(Math.abs(cp.diff))} · ${Math.abs(cp.bank) > Math.abs(cp.system) ? 'ธนาคารมากกว่า' : 'ระบบมากกว่า'}<small>ขาดรายการ / ยอดยกมาไม่ครบ / นำเข้าซ้ำ</small></div>
                <button type="button" class="acc-recon" onclick="reconcileAccount('${accId}', ${Number(cp.system) || 0}, ${Number(cp.bank) || 0})" title="ปรับยอดยกมาให้ยอดในระบบเท่าธนาคาร">⚖️ ปรับยอดยกมาให้ตรง</button>`}
    </div>`;
}

/* 📝 ใส่ยอดธนาคารเอง (วันที่ + ยอด) → บันทึกเป็นจุดตรวจ · บัตรเครดิตใส่ยอดค้างเป็นบวก */
async function recordBankBalance(accId) {
    const acc = (AppState.accounts || []).find(a => a.account_id === accId) || { name: accId };
    const isCredit = acc.account_type === 'CREDIT', today = new Date().toISOString().slice(0, 10);
    let asOf, raw;
    if (window.Swal) {
        const r = await Swal.fire({ title: `📝 ยอดธนาคาร · ${acc.name}`, width: 420, showCancelButton: true, cancelButtonText: 'ยกเลิก', confirmButtonText: 'บันทึก', confirmButtonColor: '#5F3DC4',
            html: `<div style="text-align:left;display:grid;gap:10px">
                <label>📅 ณ วันที่<input id="bb-date" type="date" class="swal2-input" style="margin:6px 0 0;width:100%" value="${today}"></label>
                <label>💰 ยอดคงเหลือ${isCredit ? ' (ยอดค้างชำระ ใส่เป็นบวก)' : ''}<input id="bb-amt" inputmode="decimal" class="swal2-input" style="margin:6px 0 0;width:100%" placeholder="0.00"></label>
                <small style="color:#5C5872">ดูจากแอปธนาคาร หรือยอดยกไปใน statement · ระบบจะเทียบกับยอดที่บันทึกไว้ถึงสิ้นวันนั้น</small></div>`,
            preConfirm: () => ({ d: document.getElementById('bb-date').value, a: document.getElementById('bb-amt').value }) });
        if (!r.isConfirmed) return;
        asOf = r.value.d; raw = r.value.a;
    } else {
        asOf = prompt('ณ วันที่ (YYYY-MM-DD)', today); if (!asOf) return;
        raw = prompt(`ยอดคงเหลือตามธนาคาร${isCredit ? ' (ยอดค้างชำระ ใส่เป็นบวก)' : ''}`); if (raw == null) return;
    }
    let bal = Number(String(raw || '').replace(/[,\s฿]/g, '').replace(/^\((.*)\)$/, '-$1'));
    if (!/^\d{4}-\d{2}-\d{2}$/.test(asOf || '') || !isFinite(bal) || String(raw).trim() === '') { alert('วันที่หรือตัวเลขไม่ถูกต้อง'); return; }
    if (isCredit) bal = -Math.abs(bal);
    const res = await fetch(`${API_BASE}/api/accounts/checkpoint`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ account_id: accId, as_of: asOf, balance: bal, source: 'MANUAL' }) });
    const j = await res.json().catch(() => ({}));
    if (!res.ok || j.error) { alert('บันทึกไม่สำเร็จ: ' + (j.error || res.status)); return; }
    renderSharedStatusSummary();
}

/* หลังนำเข้า statement: เก็บยอดยกไปเป็นจุดตรวจของบัญชี (ตั้งค่าใน statementPrecheck · ส่งใน importStatementRows) */
async function saveStatementCheckpoint(accId) {
    const cp = window._rrCheckpoint; window._rrCheckpoint = null;
    if (!cp || cp.account_id !== accId || !isFinite(cp.balance) || !cp.as_of) return;
    try { await fetch(`${API_BASE}/api/accounts/checkpoint`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...cp, source: 'STATEMENT' }) }); } catch { /* ไม่เป็นไร */ }
}

/* ⚖️ ปรับให้ตรงธนาคาร (2026-10-15 · North: "ยอดยังไม่ตรงกับยอดยกมา")
   ใส่ยอดคงเหลือจริงตามธนาคาร (ณ วันล่าสุดที่นำเข้า) → ส่วนต่างจากยอดในระบบ (ยืนยัน + รอตรวจ) ไปปรับที่ "ยอดยกมา" ของบัญชีนั้น
   มีชุดยอดยกมาที่มีบัญชีนี้อยู่แล้ว → แก้ยอดบรรทัดนั้น · ยังไม่มี → สร้างชุดใหม่ ณ วันที่รายการแรกของบัญชี */
async function reconcileAccount(accId, systemTotal, bankKnown) {
    const acc = (AppState.accounts || []).find(a => a.account_id === accId) || { name: accId };
    const f = n => { const v = Number(n || 0), t = Math.abs(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); return v < 0 ? `(${t})` : t; };
    const isCredit = acc.account_type === 'CREDIT';
    const raw = bankKnown != null ? String(isCredit ? Math.abs(bankKnown) : bankKnown) : prompt(`⚖️ ${acc.name}\nยอดในระบบตอนนี้ (ยืนยัน + รอตรวจ) = ${f(systemTotal)}\n\nใส่ยอดคงเหลือจริงตามธนาคาร ณ วันล่าสุดที่นำเข้า${isCredit ? '\n(บัตรเครดิต: ใส่ยอดค้างชำระเป็นบวก)' : ''}:`);
    if (raw == null) return;
    let target = Number(String(raw).replace(/[,\s฿]/g, '').replace(/^\((.*)\)$/, '-$1'));
    if (!isFinite(target)) { alert('ตัวเลขไม่ถูกต้อง'); return; }
    if (isCredit) target = -Math.abs(target);
    const diff = Math.round((target - systemTotal) * 100) / 100;
    if (Math.abs(diff) < 0.005) { try { showToast('✅ ยอดตรงกับธนาคารแล้ว'); } catch { /* */ } return; }
    try {
        const ob = await (await fetch(`${API_BASE}/api/inbox/opening`)).json();
        const set = (ob.sets || []).find(s => (s.lines || []).some(l => l.kind === 'ACC' && l.account_id === accId));
        let body;
        if (set) {
            const lines = set.lines.map(l => ({ kind: l.kind, account_id: l.account_id || undefined, category_id: l.category_id || undefined, contact_id: l.contact_id || null, debt_id: l.debt_id || undefined, side: l.side, amount: Math.abs(Number(l.amount) || 0), note: l.note || '' }));
            const line = lines.find(l => l.kind === 'ACC' && l.account_id === accId);
            const cur = line.side === 'CR' ? -line.amount : line.amount, nxt = Math.round((cur + diff) * 100) / 100;
            line.side = nxt >= 0 ? 'DR' : 'CR'; line.amount = Math.abs(nxt);
            if (!confirm(`ยอดยกมาของ "${acc.name}" ในชุด "${set.name}" (ณ ${set.date})\nจาก ${f(cur)} → ${f(nxt)} (ปรับ ${f(diff)})\n\nบัญชีพักยอดยกมาจะเปลี่ยนตาม — ปรับเลยไหม?`)) return;
            body = { set_id: set.set_id, name: set.name, date: set.date, entity_id: set.entity_id || null, anchor_account_id: set.anchor_account_id || null, lines: lines.filter(l => l.amount) };
        } else {
            const ba = await (await fetch(`${API_BASE}/api/accounts/balance-at?account_id=${encodeURIComponent(accId)}&date=9999-12-31`)).json();
            const date = ba.first_date || new Date().toISOString().slice(0, 10);
            if (!confirm(`"${acc.name}" ยังไม่มียอดยกมา\nสร้างยอดยกมา ${f(diff)} ณ ${date} (วันที่รายการแรก)?\n\nอีกฝั่ง (ทุน ฯลฯ) ไปใส่ต่อที่ ตั้งค่า → ยอดยกมา`)) return;
            body = { set_id: null, name: `ยอดยกมา ${acc.name}`, date, entity_id: acc.entity_id || null, anchor_account_id: null, lines: [{ kind: 'ACC', account_id: accId, side: diff >= 0 ? 'DR' : 'CR', amount: Math.abs(diff) }] };
        }
        const r = await fetch(`${API_BASE}/api/inbox/opening`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
        const j = await r.json().catch(() => ({}));
        if (!r.ok || j.error) { alert('ปรับไม่สำเร็จ: ' + (j.error || r.status)); return; }
        try { showToast(`⚖️ ปรับยอดยกมาแล้ว · ${acc.name} ตรงธนาคาร`); } catch { /* */ }
        fetchMasterData(); loadPending();
    } catch (e) { alert('ปรับไม่สำเร็จ: ' + e.message); }
}

/* 🗑️ ลบทั้งชุดที่นำเข้า (2026-10-15): รายการรอตรวจที่มาจาก statement เดียวกัน = บัญชีเดียวกัน + เวลานำเข้าใกล้กัน (≤15 นาที)
   ลบเฉพาะที่ยังรอตรวจสอบ · ที่ยืนยันไปแล้วต้องลบในหน้าประวัติ */
function pendingImportBatches() {
    const list = (AppState.pendingTransactions || []).filter(t => t.source === 'PDF_IMPORT');
    const by = {};
    for (const t of list) (by[t.account_id] = by[t.account_id] || []).push(t);
    const out = [];
    for (const [acc, txs] of Object.entries(by)) {
        txs.sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
        let cur = null;
        for (const t of txs) {
            const at = Date.parse(String(t.created_at || '').replace(' ', 'T') + (String(t.created_at || '').includes('Z') ? '' : 'Z')) || 0;
            if (!cur || at - cur.last > 15 * 60e3) { cur = { account_id: acc, first: at, last: at, txs: [] }; out.push(cur); }
            cur.last = at; cur.txs.push(t);
        }
    }
    return out.sort((a, b) => b.first - a.first);
}
async function deleteImportBatch() {
    const batches = pendingImportBatches();
    if (!batches.length) { try { showToast('ไม่มีรายการรอตรวจที่มาจากการนำเข้า statement', 'error'); } catch { /* */ } return; }
    const acc = id => (AppState.accounts || []).find(a => a.account_id === id)?.name || id;
    const when = ms => ms ? new Date(ms).toLocaleString('th-TH', { dateStyle: 'medium', timeStyle: 'short' }) : '-';
    const range = b => { const d = b.txs.map(t => String(t.date).slice(0, 10)).sort(); return `${d[0]} ถึง ${d[d.length - 1]}`; };
    const html = `<div style="text-align:left">${batches.map((b, i) => `<label style="display:flex;gap:10px;align-items:flex-start;padding:10px;border:1px solid #E9E3FA;border-radius:12px;margin-bottom:8px;cursor:pointer">
        <input type="radio" name="ib" value="${i}" ${i === 0 ? 'checked' : ''} style="margin-top:4px">
        <span><b>${acc(b.account_id)}</b> · ${b.txs.length} รายการ<br><small style="color:#5C5872">นำเข้าเมื่อ ${when(b.first)} · รายการวันที่ ${range(b)}</small></span></label>`).join('')}
        <div style="font-size:.8rem;color:#C92A2A">ลบเฉพาะรายการที่ยังรอตรวจสอบ · กู้คืนไม่ได้ (นำเข้าไฟล์ใหม่ได้)</div></div>`;
    const r = await Swal.fire({ title: 'ลบทั้งชุดที่นำเข้า', html, width: 560, showCancelButton: true, cancelButtonText: 'ยกเลิก', confirmButtonText: '🗑️ ลบชุดที่เลือก', confirmButtonColor: '#C92A2A',
        preConfirm: () => Number(document.querySelector('input[name="ib"]:checked')?.value) });
    if (!r.isConfirmed) return;
    const b = batches[r.value];
    if (!confirm(`ยืนยันลบ ${b.txs.length} รายการของ ${acc(b.account_id)}?`)) return;
    const res = await fetch(`${API_BASE}/api/transactions/bulk-delete`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ transaction_ids: b.txs.map(t => t.transaction_id) }) });
    const j = await res.json().catch(() => ({}));
    if (!res.ok) { alert('ลบไม่สำเร็จ: ' + (j.error || res.status)); return; }
    try { showToast(`🗑️ ลบแล้ว ${j.deleted} รายการ`); } catch { /* */ }
    fetchMasterData(); loadPending();
}

/* 📎 อัปโหลดสลิป / ใบเสร็จ / รายการซื้อของ จากเว็บ (2026-10-15) — ทางเดียวกับส่งใน LINE
   สลิป → จับคู่รายการที่ยอดตรง (±3 วัน) หรือสร้างรายการรอตรวจ · ใบเสร็จ/ออเดอร์ → แนบกับรายการจ่ายที่ยอดตรง หรือรอไว้
   ส่งทีละไฟล์ (พร้อมกัน 2) เพื่อไม่ให้คำขอเดียวนานเกิน */
async function uploadSlipFiles(files) {
    files = [...(files || [])]; if (!files.length) return;
    if (files.length > 3) return SlipQueue.upload(files);   // 📥 v260 หลายรูป → อัปไว้ก่อน ระบบทยอยอ่านเอง
    const go = document.getElementById('ph-slip-go'); const orig = go ? go.innerHTML : '';
    let done = 0, matched = 0, created = 0, waiting = 0, failed = 0, dup = 0; const ids = [];
    const q = files.slice();
    const worker = async () => { while (q.length) { const f = q.shift();
        const fd = new FormData(); fd.append('file', f, f.name);
        try { const r = await fetch(`${API_BASE}/api/inbox/upload`, { method: 'POST', body: fd }); const j = await r.json().catch(() => ({}));
            const o = j.results?.[0] || {};
            if (o.doc?.doc_id) ids.push(o.doc.doc_id);
            if (!r.ok || o.error) failed++; else if (o.duplicate) dup++; else if (o.outcome === 'MATCHED' || o.outcome === 'ATTACHED') matched++; else if (o.outcome === 'SUGGESTED') created++; else waiting++;
        } catch { failed++; }
        done++; if (go) go.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> ${done}/${files.length}`; } };
    await Promise.all([worker(), worker()]);
    if (go) go.innerHTML = orig;
    const msg = `อ่านแล้ว ${files.length} ไฟล์\n🔗 จับคู่กับรายการที่มีอยู่ ${matched}\n🆕 สร้างเป็นรายการรอตรวจ ${created}\n⏳ รอเลือก/รอจับคู่ ${waiting}` + (dup ? `\n♻️ เคยส่งแล้ว ${dup}` : '') + (failed ? `\n⚠️ ไม่สำเร็จ ${failed}` : '');
    /* 🧾 2026-10-30: อ่านเสร็จ → เปิดหน้าตรวจสลิปทีละใบ (ดูรูป + ข้อมูลที่อ่าน + รายการที่จับคู่ ก่อนยืนยัน) */
    const left = created + waiting;
    if (ids.length && left && confirm(msg + `\n\nมีสลิปที่ยังไม่เจอใน statement / ต้องเลือก ${left} ใบ — เปิดดูทีละใบเลยไหม?\n(ที่จับคู่แล้ว ตรวจต่อในหน้ารอตรวจสอบ ตัวกรอง 📎 มีสลิป)`)) SlipReview.open(ids);
    else { alert(msg + (matched ? '\n\nที่จับคู่แล้ว: ดูในหน้ารอตรวจสอบ ตัวกรอง 📎 มีสลิป' : '')); loadPending(); }
}
/* หลังนำเข้า statement: ใบเสร็จ/สลิปที่รอจับคู่ ลองจับคู่ใหม่อีกรอบ (ไม่ต้องรอ) */
async function rematchWaitingDocs() {
    try {
        const r = await fetch(`${API_BASE}/api/inbox?adopt=0`); if (!r.ok) return;
        const docs = ((await r.json()).docs || []).filter(d => ['STORED', 'NEEDS_CHOICE'].includes(d.status)).slice(0, 30);
        for (const d of docs) await fetch(`${API_BASE}/api/inbox/${d.doc_id}/rematch`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }).catch(() => {});
    } catch { /* ไม่เป็นไร */ }
}

/* สร้างรายการรอตรวจสอบจากบรรทัด statement (ใช้ทั้งทางอ่านเองและทาง AI) */
/* คีย์ผู้รับ/ผู้จ่าย — ต้องเหมือน payeeKey() ใน backend/src/index.js (ตัดชื่อธนาคารปลายทาง/พร้อมเพย์) */
const PAYEE_DROP = new Set(['bay', 'scb', 'kbank', 'ktb', 'bbl', 'ttb', 'gsb', 'kma', 'baac', 'uob', 'cimb', 'lhb', 'ghb', 'tisco', 'kkp', 'พร้อมเพย์', 'promptpay', 'x', 'for', 'tha', 'th', 'bangkok']);
function payeeKey(k) { const p = String(k || '').split(' ').filter(w => w && !PAYEE_DROP.has(w)).join(' '); return p.length >= 3 ? p : null; }
/* คีย์ข้อความธนาคาร — ต้องเหมือน statementKey() ใน backend/src/index.js */
function statementKey(desc) {
    const k = String(desc || '').toLowerCase().replace(/[x*]{2,}/g, ' ').replace(/[0-9]+/g, ' ').replace(/[^a-z\u0e00-\u0e7f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
    return k.length >= 3 ? k : null;
}
async function importStatementRows(accId, transactions, onProgress, meta = null) {
    const entityId = AppState.allowedEntities[0] || null;
    /* 📒 หัว statement (2026-10-30): ช่วงวันที่ · ยอดยกมา/ยกไป · ไฟล์ → stmt_id ใส่ทุกบรรทัด พร้อมลำดับ + ยอดคงเหลือที่ธนาคารพิมพ์
       (ใช้ในรายงานยอดสะสมต่อ statement · ถ้าบันทึกหัวไม่ได้ก็นำเข้าต่อตามเดิม) */
    let stmtId = null;
    const seqOf = new Map(transactions.map((t, i) => [t, i]));
    if (meta) {
        const dates = transactions.map(t => String(t.date || '').slice(0, 10)).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d)).sort();
        if (dates.length) try {
            const hr = await fetch(`${API_BASE}/api/statements/header`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ account_id: accId,
                period_from: meta.period_from || dates[0], period_to: meta.period_to || dates[dates.length - 1], opening: meta.opening ?? null, closing: meta.closing ?? null, line_count: transactions.length,
                file_name: meta.file_name || null, source_kind: meta.source_kind || null }) });
            if (hr.ok) stmtId = (await hr.json()).stmt_id || null;
        } catch { /* ไม่มีหัวก็นำเข้าได้ */ }
    }
    /* 🔢 รายการเหมือนกันทุกช่องในไฟล์ (บัตร: ร้านเดิม ยอดเดิม วันเดิม) → ลำดับที่ 0,1,2… ส่งเป็น dup_idx (ไฟล์คือความจริง) */
    const keyOf = t => [String(t.date).slice(0, 10), t.time || '', Math.round(Math.abs(t.amount) * 100) / 100, t.type === 'EXPENSE' ? '-' : '+', t.statement_desc || ''].join('|');
    const occ = new Map(), dupIdx = new Map();
    for (const t of transactions) { const k = keyOf(t), n = occ.get(k) || 0; dupIdx.set(t, n); occ.set(k, n + 1); }
    let removedCount = 0;
    /* 🧹 ซิงก์กับไฟล์ก่อนนำเข้า (2026-10-30): รายการรอตรวจจาก statement ที่ในระบบมีมากกว่าในไฟล์ (นำเข้าซ้ำ) → ลบส่วนเกิน */
    if (stmtId && transactions.length) {
        const dates = transactions.map(t => String(t.date).slice(0, 10)).sort();
        const keys = [...occ.entries()].map(([k, n]) => { const [date, time, amount, sg, ...d] = k.split('|'); return { date, time, amount: (sg === '-' ? -1 : 1) * Number(amount), desc: d.join('|'), count: n }; });
        try { const sr = await fetch(`${API_BASE}/api/statements/sync`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ account_id: accId, period_from: dates[0], period_to: dates[dates.length - 1], keys }) });
            if (sr.ok) removedCount = (await sr.json()).removed || 0; } catch { /* ซิงก์ไม่ได้ก็นำเข้าต่อ */ }
    }
    const addedDetails = [];
    let importedCount = 0, skippedCount = 0, errorCount = 0, mergedCount = 0, autoCatCount = 0, done = 0;
    /* 🏷️ จำหมวดจากรายการเดิม (2026-10-15): ร้าน/ผู้รับโอนเดิม → เติมหมวด คู่ค้า Company ให้เลย (ยังต้องกดตรวจ/บันทึกเหมือนเดิม) */
    let hints = {};
    try { const hr = await fetch(`${API_BASE}/api/transactions/category-hints`); if (hr.ok) hints = (await hr.json()).hints || {}; } catch { /* ไม่มีก็ได้ */ }
    const skippedDetails = [];
    const queue = transactions.slice();
    const worker = async () => {
        while (queue.length) {
            const tx = queue.shift();
            const payload = {
                /* 2026-10-30: รหัสต้องแยก ซื้อ/คืนเงิน (ยอดเท่ากัน วันเดียวกัน) และบรรทัดที่เหมือนกันทุกช่อง (ลำดับ _1,_2) — เดิมรหัสชนกันแล้วบันทึกทับ (1,139 / -1,139 หายไป 1 แถว) */
                transaction_id: generateTxId(tx.date, accId, tx.type === 'EXPENSE' ? -Math.abs(tx.amount) : Math.abs(tx.amount), 'PDF', { refCode: tx.ref_code, statementDesc: tx.statement_desc, time: tx.time }) + ((dupIdx.get(tx) || 0) ? '_' + dupIdx.get(tx) : ''),
                // ยอดติดเครื่องหมายตามจริง (จ่าย = ลบ) ให้ตรงกับรายการจาก LINE/ที่บันทึกแล้ว · match_existing = จับคู่สลิปที่บันทึกไว้ก่อน (2026-10-15)
                account_id: accId, date: tx.date, time: tx.time, statement_desc: tx.statement_desc, total_amount: tx.type === 'EXPENSE' ? -Math.abs(tx.amount) : Math.abs(tx.amount), ref_code: tx.ref_code,
                status: 'PENDING_REVIEW', source: 'PDF_IMPORT', match_existing: true,
                ...(stmtId ? { stmt_id: stmtId, stmt_seq: seqOf.get(tx), stmt_balance: (tx.balance == null || tx.balance === '' || !isFinite(tx.balance)) ? null : Number(tx.balance) } : {}),
                dup_idx: dupIdx.get(tx) || 0,
                details: [(() => { const k = statementKey(tx.statement_desc), h = k && hints[(tx.type === 'EXPENSE' ? 'OUT' : 'IN') + '|' + k];
                    const d = { amount: tx.type === 'EXPENSE' ? -Math.abs(tx.amount) : Math.abs(tx.amount), fee: 0, wht: 0, category_id: null, entity_id: AccDefaults.of(accId) || null /* 🏢 v256: ว่าง ยกเว้นบัญชีที่ตั้ง Company เริ่มต้น */, note: tx.note || stmtDetailNote(tx.statement_desc) || null, type: tx.type };   // v255: Detail = ข้อความ statement
                    /* v265 ภาษีหัก ณ ที่จ่าย (กรุงไทย ดอกเบี้ย 38.26 หัก 0.38 → เข้าจริง 37.88): หัว = ยอดเข้าจริง · บรรทัดย่อย = ยอดเต็ม + WHT */
                    if (Number(tx.wht) > 0) { d.amount = Math.round((d.amount + Number(tx.wht)) * 100) / 100; d.wht = Number(tx.wht); if (!d.note) d.note = (d.note || '') + ''; }
                    if (tx.category_id) { d.category_id = tx.category_id; if (tx.detail_type) d.type = tx.detail_type; d._hint = 1; }   // หมวดที่กำหนดมาจากตัวนำเข้า (wePAY · 2026-10-31)
                    else if (h) { d.category_id = h.category_id; d.contact_id = h.contact_id; if (h.type) d.type = h.type; d._hint = 1; }   // v256: Company ไม่เดาจากประวัติ (ใช้ค่าเริ่มต้นของบัญชี)
                    /* 💳 ชำระบัตร (ใบแจ้งยอดบัตร) = โอนระหว่างบัญชี ไม่ใช่รายรับ (2026-10-30) */
                    else if (tx.note === 'ชำระบัตร' && (AppState.categories || []).some(c => c.category_id === 'Bank_Transfer')) { d.category_id = 'Bank_Transfer'; d.type = 'TRANSFER'; d._hint = 1; }
                    return d; })()]
            };
            try {
                const r = await fetch(`${API_BASE}/api/transactions`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-user-id': encodeURIComponent(getUserIdHeader()) }, body: JSON.stringify(payload) });
                const json = await r.json().catch(() => ({}));
                if (!r.ok) errorCount++;
                else if (json.merged) mergedCount++;
                else if (!json.skipped && payload.details[0]._hint) { importedCount++; autoCatCount++; addedDetails.push(`${tx.date} ${tx.amount.toLocaleString('en-US', { minimumFractionDigits: 2 })} ${tx.statement_desc || ''}`); }
                else if (json.skipped) { skippedCount++; skippedDetails.push(json.message || `${tx.date} | ${tx.amount}`); }
                else { importedCount++; addedDetails.push(`${tx.date} ${tx.amount.toLocaleString('en-US', { minimumFractionDigits: 2 })} ${tx.statement_desc || ''}`); }
            } catch { errorCount++; }
            onProgress?.(++done, transactions.length);
        }
    };
    await Promise.all(Array.from({ length: Math.min(6, transactions.length) }, worker));
    await saveStatementCheckpoint(accId);
    try { localStorage.setItem('rr_last_import', JSON.stringify({ imported: importedCount, skipped: skippedCount, merged: mergedCount, errors: errorCount, at: new Date().toISOString() })); } catch { /* */ }
    /* ⚡ v257 กฎอัตโนมัติ: รายการที่ตรงกฎ → ใส่หมวด + ยืนยันให้เลย */
    if (importedCount) try { const j = await AutoRules.apply(); if (j.applied) window.showToast?.(`⚡ ยืนยันตามกฎอัตโนมัติ ${j.applied.toLocaleString('en-US')} รายการ`); } catch { /* ไม่มีกฎก็ได้ */ }
    rematchWaitingDocs();
    /* 📌 จำรูปแบบนำเข้าของบัญชีนี้ (2026-10-31): นำเข้าสำเร็จ + ยอดเดินตรง (หรือตรวจไม่ได้) → เก็บไว้เทียบครั้งหน้า */
    if (meta?.format && meta.walk !== false && !errorCount) {
        const fmt = meta.format;
        fetch(`${API_BASE}/api/accounts/import-format`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ account_id: accId, format: fmt }) })
            .then(r => r.ok ? r.json() : null).then(j => { const a = (AppState.accounts || []).find(x => x.account_id === accId); if (a && j?.format) a.import_format = JSON.stringify(j.format); }).catch(() => {});
    }
    return { importedCount, skippedCount, errorCount, mergedCount, autoCatCount, skippedDetails, removedCount, addedDetails, stmtId };
}

// batch_statement_import.js
/* 📚 นำเข้า statement หลายไฟล์พร้อมกัน (2026-10-30 · North เลือก ก: "ระบบจะตรวจสอบเลขที่บัญชีหรือข้อมูลซ้ำด้วยไหม")
   ตรวจ 4 ชั้นก่อนนำเข้า:
   ① เลขบัญชี/เลขบัตรในไฟล์ → หาบัญชีให้เอง (ไม่เจอ/เจอหลายบัญชี = ให้เลือก · ไม่เลือก = ไม่นำเข้าไฟล์นั้น)
   ② ยอดเดินในไฟล์ (ยกมา + รายการ = ยกไป)  ③ ต่อเนื่อง: ยกมาของไฟล์ = ยกไปของไฟล์ก่อนหน้า (บัญชีเดียวกัน) หรือ = ยอดในระบบ ณ วันแรก
   ④ ซ้ำ: statement นี้เคยนำเข้าแล้ว (บัญชี+ช่วงวัน+ยกไป เดิม) → ไม่ติ๊กให้ · ไฟล์ซ้ำกันในชุด → ข้าม · รายการซ้ำรายบรรทัด → ระบบข้าม/จับคู่ให้เหมือนเดิม
   อ่านเฉพาะไฟล์ที่มีตัวหนังสือ (ไม่ใช้ AI) · ไฟล์สแกน/Print to PDF → แจ้งให้นำเข้าทีละไฟล์ */
/* ⏳ ปุ่มนำเข้าเป็นปุ่มไอคอนเล็ก (32px) → ตอนทำงานแสดงนาฬิกาทราย ข้อความไปอยู่ใน tooltip (North 2026-10-31: ข้อความไทยเกินขอบ) */
function setUploadBtnBusy(btn, tip) {
    if (!btn) return;
    if (!btn.dataset.idleHtml) btn.dataset.idleHtml = btn.innerHTML;
    btn.innerHTML = '<i class="fa-solid fa-hourglass-half rr-hg"></i>'; btn.title = tip || 'กำลังทำงาน…'; btn.setAttribute('aria-busy', 'true');
}
function setUploadBtnIdle(btn) {
    if (!btn) return;
    btn.innerHTML = btn.dataset.idleHtml || '<i class="fa-solid fa-cloud-arrow-up" style="font-size: 0.8rem;"></i>'; btn.title = 'อัปโหลด PDF Statement'; btn.removeAttribute('aria-busy');
}
async function batchImportStatements(files, btn) {
  const accs = AppState.accounts || [], f = n => n == null || n === '' ? '-' : Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const dTh = d => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d || ''); return m ? `${m[3]}/${m[2]}/${(+m[1] + 543) % 100}` : '-'; };
  const r2 = n => Math.round((Number(n) || 0) * 100) / 100;
  const setBtn = t => { if (btn) btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> ${t}`; };
  const findAcc = (read, last4, credit) => {
    let hit = accs.filter(a => statementAccountMatches(read, a.account_number) === true);
    /* 2026-10-30: เลขเดียวกันอยู่หลายบัญชี (เช่น เลขบัตรใส่ไว้ทั้งบัญชีบัตรและบัญชีธนาคาร) → บัตรเลือกบัญชีบัตร · statement ธนาคารเลือกบัญชีที่ไม่ใช่บัตร */
    if (hit.length > 1) { const t = hit.filter(a => (a.account_type === 'CREDIT') === !!credit); if (t.length) hit = t; }
    if (hit.length === 1) return hit[0].account_id;
    if (credit && last4) { const t = accs.filter(a => a.account_type === 'CREDIT' && String(a.account_number || '').split(/[,;\n/|]+/).some(x => x.replace(/[^0-9]/g, '').endsWith(last4))); if (t.length === 1) return t[0].account_id; }
    return '';
  };
  /* ── อ่านทุกไฟล์ ── */
  const items = [], skipped = [], seenHash = new Set();
  for (const [i, file] of files.entries()) {
    setBtn(`อ่านไฟล์ ${i + 1}/${files.length}`);
    try {
      const buf = await file.arrayBuffer();
      const hash = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', buf))).slice(0, 12).map(b => b.toString(16).padStart(2, '0')).join('');
      if (seenHash.has(hash)) { skipped.push({ name: file.name, why: '♻️ ไฟล์ซ้ำกับไฟล์อื่นในชุดนี้' }); continue; }
      seenHash.add(hash);
      const opened = await openStatementPdf(buf, document.getElementById('import-account-selector')?.value || '');
      if (opened.needPassword) { skipped.push({ name: file.name, why: '🔒 รหัส PDF ไม่ตรงกับบัญชีใด — ตั้งรหัสที่ ตั้งค่า→บัญชี' }); continue; }
      if (!opened.pdf) { skipped.push({ name: file.name, why: '⚠️ เปิดไฟล์ไม่ได้' }); continue; }
      /* 2026-10-30: ลองอ่านแบบใบแจ้งยอดบัตรก่อน — ตัวอ่าน statement ธนาคารเคยอ่านบรรทัดสรุปของบัตร CardX
         ("18/11/25 51,000.00 4,080.00") เป็นรายการเดียว แล้วใช้ยอดขั้นต่ำเป็นยอดคงเหลือ */
      const card0 = await parseCardStatement(opened.pdf).catch(() => ({ ok: false }));
      const bank = card0.ok ? { ok: false } : await parseTextStatement(opened.pdf).catch(() => ({ ok: false }));
      if (bank.ok) {
        const txs = bank.lines.map(l => ({ date: l.date, time: l.time ? (l.time.length === 5 ? l.time + ':00' : l.time) : '00:00:00', type: l.amount > 0 ? 'INCOME' : 'EXPENSE',
          amount: Math.abs(l.amount), ref_code: null, statement_desc: l.description, note: null, balance: l.balance ?? null, wht: l.wht || 0 }));
        const sum = r2(bank.lines.reduce((t, l) => t + l.amount, 0));
        items.push({ file: file.name, fileObj: file, kind: 'BANK', issuer: bank.issuer, read: bank.account_number || '', acc: findAcc(bank.account_number || '', '', false), txs, opening: bank.opening, closing: bank.closing,
          walk: bank.opening != null && bank.closing != null ? Math.abs(r2(bank.opening + sum) - r2(bank.closing)) < 0.01 : null, sign: 1 });
        continue;
      }
      const card = card0;
      if (card.ok) {
        for (const c of card.cards) items.push({ file: file.name, fileObj: file, kind: 'CARD', issuer: card.issuer, read: c.masked, label: c.type, acc: findAcc(c.masked, c.last4, true), txs: c.txs, opening: c.opening, closing: c.closing,
          walk: c.agree, sign: -1, asOf: card.statementDate });
        continue;
      }
      skipped.push({ name: file.name, why: `🤖 ${bank.reason || 'อ่านตัวหนังสือในไฟล์ไม่ได้'} — นำเข้าไฟล์นี้ทีละไฟล์ (ระบบใช้ AI อ่าน)` });
    } catch (e) { skipped.push({ name: file.name, why: '⚠️ ' + e.message }); }
  }
  if (!items.length) { alert('ไม่มีไฟล์ที่นำเข้าได้\n\n' + skipped.map(s => `${s.name}: ${s.why}`).join('\n')); return; }
  for (const it of items) { const d = it.txs.map(t => t.date).sort(); it.from = d[0]; it.to = d[d.length - 1];
    const cy = it.kind === 'CARD' ? cardCycle(it.asOf, it.txs) : {}; it.pf = cy.period_from || it.from; it.pt = cy.period_to || it.to; }
  /* ── เคยนำเข้าแล้วไหม + ต่อเนื่อง (คิดใหม่ทุกครั้งที่เปลี่ยนบัญชี) ── */
  const checkDup = async it => {
    it.dup = null; if (!it.acc) return;
    try { const r = await fetch(`${API_BASE}/api/statements/header`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ account_id: it.acc, period_from: it.pf, period_to: it.pt, closing: it.closing, check_only: true }) });
      const j = await r.json(); if (j.exists) it.dup = j; } catch { /* */ }
  };
  /* 📌 เทียบกับรูปแบบที่จำไว้ของบัญชี + ประเภทบัญชี (2026-10-31) — อ่านผิดแบบ (บัตร ↔ ธนาคาร) → เตือนและไม่ติ๊กให้ */
  const KIND_TH = k => k === 'CARD' ? 'ใบแจ้งยอดบัตร' : 'statement ธนาคาร';
  const fmtCheck = it => {
    it.fmtBad = ''; it.fmtNote = '';
    const a = accs.find(x => x.account_id === it.acc); if (!a) return;
    let fm = null; try { fm = a.import_format ? JSON.parse(a.import_format) : null; } catch { /* */ }
    if (a.account_type && (a.account_type === 'CREDIT') !== (it.kind === 'CARD')) it.fmtBad = `บัญชีนี้เป็น${a.account_type === 'CREDIT' ? 'บัตรเครดิต' : 'บัญชีธนาคาร'} แต่ไฟล์อ่านได้เป็น${KIND_TH(it.kind)}`;
    else if (fm && fm.kind && fm.kind !== it.kind) it.fmtBad = `ครั้งก่อนบัญชีนี้นำเข้าเป็น${KIND_TH(fm.kind)}${fm.issuer ? ' ' + fm.issuer : ''} แต่ไฟล์นี้อ่านได้เป็น${KIND_TH(it.kind)}`;
    else if (fm && fm.issuer && it.issuer && fm.issuer !== it.issuer) it.fmtNote = `⚠️ ผู้ออกต่างจากครั้งก่อน (เดิม ${fm.issuer} · ไฟล์นี้ ${it.issuer})`;
    else if (fm) it.fmtNote = `📌 รูปแบบเดิม: ${KIND_TH(fm.kind)}${fm.issuer ? ' ' + fm.issuer : ''}`;
  };
  const sysOpen = {};
  const continuity = async () => {
    const byAcc = {};
    for (const it of items) if (it.acc) (byAcc[it.acc] = byAcc[it.acc] || []).push(it);
    for (const [acc, list] of Object.entries(byAcc)) {
      list.sort((a, b) => a.from.localeCompare(b.from));
      list.forEach((it, i) => {
        const prev = list[i - 1];
        if (prev) { it.cont = prev.closing != null && it.opening != null ? (Math.abs(r2(prev.closing) - r2(it.opening)) < 0.01 ? 'ok' : 'gap') : null;
          const days = (Date.parse(it.from) - Date.parse(prev.to)) / 864e5;
          it.contNote = (prev.closing != null ? `ยกไปไฟล์ก่อน ${f(prev.closing)}` : '') + (it.cont === 'gap' && days > 20 ? ` · น่าจะขาด statement ช่วง ${dTh(prev.to)} – ${dTh(it.from)}` : ''); return; }
        const k = acc + '|' + it.from;
        it.cont = null; it.contNote = '';
        /* ไฟล์แรกของบัญชี: ยกมาในไฟล์ เทียบยอดในระบบ ณ วันแรก (บัตรเก็บติดลบในระบบ) */
        if (sysOpen[k] != null && it.opening != null) { const sys = sysOpen[k], want = it.kind === 'CARD' ? -Math.abs(it.opening) : it.opening;
          it.cont = sys.count === 0 ? 'new' : Math.abs(r2(sys.balance) - r2(want)) < 0.01 ? 'ok' : 'gap';
          it.contNote = sys.count === 0 ? 'บัญชีนี้ยังไม่มีรายการก่อนหน้า' : `ยอดในระบบ ${f(it.kind === 'CARD' ? -sys.balance : sys.balance)}`; }
      });
    }
  };
  setBtn('ตรวจซ้ำ/ความต่อเนื่อง…');
  for (const it of items) {
    await checkDup(it);
    if (it.acc && !(it.acc + '|' + it.from in sysOpen)) { try { const r = await fetch(`${API_BASE}/api/accounts/balance-at?account_id=${encodeURIComponent(it.acc)}&date=${it.from}`); if (r.ok) sysOpen[it.acc + '|' + it.from] = await r.json(); } catch { /* */ } }
    fmtCheck(it);
    it.on = !!it.acc && !it.dup && !it.fmtBad;
  }
  await continuity();
  /* ── ตารางตรวจก่อนนำเข้า ── */
  const accOpts = sel => `<option value="">— เลือกบัญชี —</option>` + accs.map(a => `<option value="${esc(a.account_id)}"${a.account_id === sel ? ' selected' : ''}>${a.account_type === 'CREDIT' ? '💳' : '🏦'} ${esc(a.name)}</option>`).join('');
  const rowHtml = (it, i) => `<tr class="${it.on ? '' : 'bi-off'}"><td><input type="checkbox" data-on="${i}"${it.on ? ' checked' : ''}${it.acc ? '' : ' disabled'}></td>
    <td><b>${esc(it.file)}</b><br><small>${it.kind === 'CARD' ? '💳' : '🏦'} ${esc(it.read || 'ไม่พบเลขบัญชีในไฟล์')} ${esc(it.label || '')}</small></td>
    <td><select data-acc="${i}">${accOpts(it.acc)}</select>${it.acc ? '' : '<br><small style="color:#E67700">① หาบัญชีจากเลขในไฟล์ไม่เจอ</small>'}${it.fmtBad ? `<br><small style="color:#C92A2A">⚠️ ${esc(it.fmtBad)}</small>` : it.fmtNote ? `<br><small style="color:${it.fmtNote.startsWith('⚠️') ? '#E67700' : '#5C5872'}">${esc(it.fmtNote)}</small>` : ''}</td>
    <td>${dTh(it.from)} – ${dTh(it.to)}<br><small>${it.txs.length} รายการ</small></td>
    <td class="r">${f(it.opening)} → ${f(it.closing)}<br><small>${it.walk === true ? '② ✅ ยอดเดินตรง' : it.walk === false ? '<span style="color:#C92A2A">② ⚠️ ยอดเดินไม่ตรง</span>' : '② ไม่มียอดให้ตรวจ'}</small></td>
    <td><small>${it.cont === 'ok' ? '③ ✅ ต่อเนื่อง' : it.cont === 'gap' ? '<span style="color:#C92A2A">③ ⚠️ ไม่ต่อเนื่อง</span>' : it.cont === 'new' ? '③ 🆕 เริ่มบัญชี' : '③ -'} ${esc(it.contNote || '')}</small>
      ${it.dup ? `<br><small style="color:#C92A2A">④ ♻️ เคยนำเข้าแล้ว (ในระบบ ${it.dup.lines_in_system} บรรทัด) — ติ๊กเพื่อนำเข้าซ้ำ (เติมยอดรายบรรทัด · รายการซ้ำจะถูกข้าม)</small>` : ''}</td></tr>`;
  const html = () => `<div style="text-align:left;font-size:.85rem">
    <div style="margin-bottom:8px">อ่านได้ <b>${items.length}</b> statement จาก ${files.length} ไฟล์ · เลือกแล้ว <b id="bi-n">${items.filter(i => i.on).length}</b></div>
    <div style="max-height:56vh;overflow:auto"><table class="bi-tbl"><thead><tr><th></th><th>ไฟล์</th><th>บัญชี</th><th>ช่วงวันที่</th><th>ยกมา → ยกไป</th><th>ตรวจ</th></tr></thead><tbody>${items.map(rowHtml).join('')}</tbody></table></div>
    ${skipped.length ? `<div style="margin-top:10px;padding:8px 10px;border-radius:10px;background:#FFF5F5;color:#862E2E"><b>ไม่ได้นำเข้า ${skipped.length} ไฟล์</b><br>${skipped.map(s => `${esc(s.name)} — ${esc(s.why)}`).join('<br>')}</div>` : ''}
    <div style="margin-top:8px;color:#5C5872;font-size:.78rem">รายการซ้ำรายบรรทัด (มีอยู่แล้ว / ตรงกับสลิปหรือข้อมูลเก่า) ระบบข้ามหรือจับคู่ให้อัตโนมัติ · ทุกรายการเข้า "รอตรวจ" ก่อน</div></div>`;
  if (!document.getElementById('bi-css')) { const st = document.createElement('style'); st.id = 'bi-css'; st.textContent = `.bi-tbl{width:100%;border-collapse:collapse;font-size:.8rem}.bi-tbl th{background:#5F3DC4;color:#fff;padding:6px;position:sticky;top:0}.bi-tbl td{padding:6px;border-bottom:1px solid #E9E3FA;vertical-align:top}.bi-tbl td.r{text-align:right;white-space:nowrap}.bi-tbl select{max-width:190px;min-height:34px;border-radius:8px}.bi-tbl tr.bi-off td{opacity:.55}`; document.head.appendChild(st); }
  const go = await Swal.fire({ title: '📚 นำเข้า statement หลายไฟล์', html: html(), width: 980, showCancelButton: true, confirmButtonText: 'นำเข้าที่เลือก', cancelButtonText: 'ยกเลิก',
    didOpen: el => {
      const wire = () => {
        el.querySelectorAll('[data-on]').forEach(c => c.onchange = () => { items[+c.dataset.on].on = c.checked; c.closest('tr').classList.toggle('bi-off', !c.checked); el.querySelector('#bi-n').textContent = items.filter(i => i.on).length; });
        el.querySelectorAll('[data-acc]').forEach(s => s.onchange = async () => {
          const it = items[+s.dataset.acc]; it.acc = s.value; await checkDup(it);
          if (it.acc && !(it.acc + '|' + it.from in sysOpen)) { try { const r = await fetch(`${API_BASE}/api/accounts/balance-at?account_id=${encodeURIComponent(it.acc)}&date=${it.from}`); if (r.ok) sysOpen[it.acc + '|' + it.from] = await r.json(); } catch { /* */ } }
          fmtCheck(it); it.on = !!it.acc && !it.dup && !it.fmtBad; await continuity(); Swal.update({ html: html() }); wire(); });
      };
      wire();
    } });
  if (!go.isConfirmed) return;
  /* ── นำเข้า: เรียงตามบัญชี แล้วตามวันที่ ── */
  const todo = items.filter(i => i.on && i.acc).sort((a, b) => a.acc.localeCompare(b.acc) || a.from.localeCompare(b.from));
  const out = [];
  for (const [k, it] of todo.entries()) {
    if (it.closing != null) window._rrCheckpoint = { account_id: it.acc, as_of: it.asOf || it.to, balance: it.kind === 'CARD' ? -Math.abs(it.closing) : it.closing };
    const res = await importStatementRows(it.acc, it.txs, (d, n) => setBtn(`ไฟล์ ${k + 1}/${todo.length} · ${d}/${n}`),
      { opening: it.opening, closing: it.closing, source_kind: it.kind === 'CARD' ? 'CREDIT_CARD' : 'BANK', file_name: it.kind === 'CARD' ? `${it.file} · ${it.read}` : it.file,
        ...(it.kind === 'CARD' ? cardCycle(it.asOf, it.txs) : {}), format: { kind: it.kind, issuer: it.issuer, parser: it.kind === 'CARD' ? 'card' : 'text', read: it.read }, walk: it.walk });
    if (it.fileObj && res.stmtId) DriveStore.saveStatement(it.fileObj, it.acc, res.stmtId, it.asOf || it.to);   // 📁 Drive (2026-10-31)
    out.push(`${it.kind === 'CARD' ? '💳' : '🏦'} ${(accs.find(a => a.account_id === it.acc) || {}).name || it.acc} · ${dTh(it.from)}–${dTh(it.to)}: นำเข้า ${res.importedCount}` +
      (res.mergedCount ? ` · จับคู่ ${res.mergedCount}` : '') + (res.skippedCount ? ` · มีอยู่แล้ว ${res.skippedCount}` : '') + (res.removedCount ? ` · 🧹 ลบที่ซ้ำ ${res.removedCount}` : '') + (res.errorCount ? ` · ⚠️ ไม่สำเร็จ ${res.errorCount}` : '') +
      (res.skippedCount && res.addedDetails?.length && res.addedDetails.length <= 10 ? `\n     ➕ ${res.addedDetails.join('\n     ➕ ')}` : ''));
  }
  alert(`📚 นำเข้าเสร็จ ${todo.length} statement\n\n${out.join('\n')}` + (skipped.length ? `\n\nไม่ได้นำเข้า ${skipped.length} ไฟล์:\n` + skipped.map(s => `${s.name} — ${s.why}`).join('\n') : '') +
    '\n\nตรวจความครบได้ที่ รายงาน → ยอดสะสม statement');
  loadPending();
}

function bindPDFUpload() {
    const triggerUploadBtn = document.getElementById("btn-trigger-statement-upload");
    const pdfInput = document.getElementById("statement-pdf-input");
    
    if (triggerUploadBtn && pdfInput) {
        triggerUploadBtn.addEventListener("click", () => {
            const importAccSel = document.getElementById("import-account-selector");
            /* 2026-10-30: ไม่บังคับเลือกบัญชีก่อน — หลายไฟล์ระบบหาบัญชีเอง · ไฟล์เดียวยังต้องเลือก (เตือนตอนเลือกไฟล์) */
            pdfInput.click();
        });

        pdfInput.addEventListener("change", async (e) => {
            const file = e.target.files[0];
            if (!file) return;
            /* 📚 เลือก PDF หลายไฟล์ → นำเข้าหลายไฟล์ (หาบัญชีจากเลขในไฟล์ · ไม่ต้องเลือกบัญชีก่อน) 2026-10-30 */
            const pdfs = [...e.target.files].filter(f => /pdf/i.test(f.type) || /\.pdf$/i.test(f.name));
            if (pdfs.length > 1 && pdfs.length === e.target.files.length) {
                const orig = triggerUploadBtn.innerHTML; triggerUploadBtn.disabled = true;
                try { await batchImportStatements(pdfs, triggerUploadBtn); } catch (err) { alert('นำเข้าหลายไฟล์ไม่สำเร็จ: ' + err.message); }
                triggerUploadBtn.disabled = false; setUploadBtnIdle(triggerUploadBtn); pdfInput.value = ''; return;
            }
            
            const importAccSel = document.getElementById("import-account-selector");
            let selectedAccId = importAccSel ? importAccSel.value : '';
            if (!selectedAccId) {
                alert("กรุณาเลือกบัญชีธนาคารก่อนอัปโหลดไฟล์ PDF");
                pdfInput.value = '';
                return;
            }
            
            const btnIcon = triggerUploadBtn.querySelector("i");
            const originalIconClass = btnIcon ? btnIcon.className : 'fa-solid fa-upload';
            if (!triggerUploadBtn.dataset.idleHtml) triggerUploadBtn.dataset.idleHtml = triggerUploadBtn.innerHTML;   // เก็บไอคอนเดิมก่อนเปลี่ยนเป็น ⏳
            triggerUploadBtn.disabled = true;
            setUploadBtnBusy(triggerUploadBtn, `กำลังประมวลผล...`);

            /* 📸 ภาพแคป (2026-10-15): ประวัติ TrueMoney/ShopeePay · รายการสั่งซื้อ Shopee/Lazada · ใบแจ้งยอดบัตรที่ถ่าย/แคปมา
               เลือกได้หลายภาพของบัญชีเดียวกัน → ย่อภาพ → AI อ่านทุกแถว → ตรวจก่อนนำเข้า → นำเข้า (จับคู่สลิปเดิม/กันซ้ำเหมือน PDF) */
            const allFiles = [...e.target.files];
            /* 📱 บัญชี wePAY + รูปหน้าจอ → ใช้ตัวอ่าน wePAY (เข้าใจหน้า "รายการล่าสุด"/"กล่องข้อความ" · หักเงินคืน · ตัดซ้ำ) แทนตัวอ่าน statement ทั่วไป (2026-10-31) */
            const selAcc = (AppState.accounts || []).find(a => a.account_id === selectedAccId);
            if (selAcc && /we\s*pay/i.test(`${selAcc.name} ${selAcc.bank_name || ''}`) && allFiles.every(f => /^image\//.test(f.type)) && typeof WePay !== "undefined") {
                triggerUploadBtn.disabled = false; setUploadBtnIdle(triggerUploadBtn);
                try { await WePay.run(allFiles); } finally { pdfInput.value = ''; }
                return;
            }
            if (allFiles.some(f => /^image\//.test(f.type))) {
                const done = () => { triggerUploadBtn.disabled = false; setUploadBtnIdle(triggerUploadBtn); pdfInput.value = ''; };
                try {
                    const shrink = f => new Promise((ok, bad) => { const img = new Image(), url = URL.createObjectURL(f);
                        img.onload = () => { const k = Math.min(1, 1800 / Math.max(img.width, img.height)); const c = document.createElement('canvas');
                            c.width = Math.round(img.width * k); c.height = Math.round(img.height * k); c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
                            URL.revokeObjectURL(url); ok(c.toDataURL('image/jpeg', 0.85)); };
                        img.onerror = () => { URL.revokeObjectURL(url); bad(new Error('เปิดภาพไม่ได้: ' + f.name)); }; img.src = url; });
                    const imgs = [];
                    for (const f of allFiles.filter(f => /^image\//.test(f.type)).slice(0, 20)) imgs.push(await shrink(f));
                    setUploadBtnBusy(triggerUploadBtn, `AI กำลังอ่าน ${imgs.length} ภาพ...`);
                    const r = await fetch(`${API_BASE}/api/statement-ocr`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ imagesBase64: imgs }) });
                    const data = await r.json().catch(() => ({}));
                    if (!r.ok || data.error) throw new Error(data.error || `อ่านภาพไม่สำเร็จ (${r.status})`);
                    if (!data.transactions?.length) { alert('ไม่พบรายการเงินในภาพ'); done(); return; }
                    const useAcc = await statementPrecheck(selectedAccId, { account_number: data.account_number, rows: data.transactions, opening: data.opening_balance, closing: data.closing_balance });
                    if (!useAcc) { done(); return; }
                    const res = await importStatementRows(useAcc, data.transactions, (d, n) => { setUploadBtnBusy(triggerUploadBtn, `กำลังบันทึก ${d}/${n}`); },
                        { opening: data.opening_balance, closing: data.closing_balance, source_kind: data.source_kind, file_name: allFiles.map(f => f.name).join(', ').slice(0, 200) });
                    alert(`อ่านจากภาพด้วย AI ${data.transactions.length} รายการ\nนำเข้า ${res.importedCount} รายการ` + (res.mergedCount ? `\n🔗 จับคู่กับสลิป/รายการที่บันทึกไว้แล้ว ${res.mergedCount}` : '') + (res.autoCatCount ? `\n🏷️ ใส่หมวดอัตโนมัติ ${res.autoCatCount}` : '')
                        + (res.skippedCount ? `\nข้ามรายการซ้ำ ${res.skippedCount}` : '') + (res.errorCount ? `\n⚠️ ไม่สำเร็จ ${res.errorCount}` : '')
                        + `\n\n⚠️ ภาพแคปอาจตกหล่นบางแถว — ตรวจกับยอดในแอปอีกครั้ง`);
                    loadPending();
                } catch (err) { alert('อ่านภาพไม่สำเร็จ: ' + err.message); }
                done(); return;
            }

            const resetUploadBtn = () => {
                triggerUploadBtn.disabled = false;
                setUploadBtnIdle(triggerUploadBtn);
                pdfInput.value = '';
            };
            let foundPassword = null;
            // ── ยกเครื่อง 2026-10-12: อ่านตัวหนังสือใน PDF เองก่อน (ไม่ใช้ AI) ──
            try {
                const opened = await openStatementPdf(await file.arrayBuffer(), selectedAccId);
                if (opened.needPassword) {
                    alert("ไฟล์ PDF นี้มีรหัสผ่าน แต่ไม่ตรงกับรหัสที่ตั้งไว้ในบัญชีใดเลย\nตั้งรหัสที่ ตั้งค่าระบบ → Statement → รหัสผ่าน PDF แล้วลองใหม่");
                    resetUploadBtn(); return;
                }
                foundPassword = opened.password;
                if (opened.pdf) {
                    /* 2026-10-30: ใบแจ้งยอดบัตรก่อน แล้วค่อย statement ธนาคาร (ดูเหตุผลที่ batchImportStatements) */
                    const card0 = await parseCardStatement(opened.pdf).catch(() => ({ ok: false }));
                    /* v269 (North: "ระบบไม่อ่านภาษีอีกแล้ว" — ไฟล์กรุงไทย 06–08/69 ถูก AI อ่านแทน): อ่านไฟล์เองได้แล้ว แต่ขั้นตรวจ/บันทึกผิดพลาด
                       → เดิมตกไปส่ง AI อ่านซ้ำเงียบ ๆ (ได้ข้อความ/ยอดแบบ AI · ภาษีหาย) · ตอนนี้แจ้งข้อผิดพลาด ไม่ส่ง AI */
                    const noAi = async (what, fn) => { try { await fn(); } catch (e) { console.error(what, e);
                        alert(`อ่านไฟล์ได้ครบแล้ว แต่${what}ไม่สำเร็จ: ${e?.message || e}\n\nระบบไม่ได้ส่งให้ AI อ่านแทน — ลองนำเข้าไฟล์เดิมอีกครั้ง (รายการที่บันทึกไปแล้วจะถูกข้าม) หรือส่งข้อความนี้ให้ผู้ดูแล`); } resetUploadBtn(); };
                    if (card0.ok) return noAi('บันทึกใบแจ้งยอดบัตร', () => importCardStatement(card0, selectedAccId, file.name, triggerUploadBtn, file));
                    const parsed = await parseTextStatement(opened.pdf).catch(e => { console.error('parseTextStatement', e); return { ok: false }; });
                    if (parsed.ok) return noAi('บันทึกรายการ', async () => {
                        const txs = parsed.lines.map(l => ({ date: l.date, time: l.time ? (l.time.length === 5 ? l.time + ':00' : l.time) : '00:00:00',
                            type: l.amount > 0 ? 'INCOME' : 'EXPENSE', amount: Math.abs(l.amount), ref_code: null, statement_desc: l.description, note: null, balance: l.balance ?? null, wht: l.wht || 0 }));
                        const useAcc = await statementPrecheck(selectedAccId, { account_number: parsed.account_number, rows: txs, opening: parsed.opening, closing: parsed.closing });
                        if (!useAcc) return;
                        selectedAccId = useAcc;
                        const res = await importStatementRows(selectedAccId, txs, (d, n) => { setUploadBtnBusy(triggerUploadBtn, `กำลังบันทึก ${d}/${n}`); },
                            { opening: parsed.opening, closing: parsed.closing, source_kind: 'BANK', file_name: file.name,
                              format: { kind: 'BANK', issuer: parsed.issuer, parser: 'text', read: parsed.account_number }, walk: parsed.checkable ? parsed.agree === parsed.checkable : null });
                        if (res.stmtId) DriveStore.saveStatement(file, selectedAccId, res.stmtId, txs.map(t => t.date).sort().pop());   // 📁 Drive (2026-10-31)
                        const sumIn = parsed.lines.filter(l => l.amount > 0).reduce((t, l) => t + l.amount, 0), sumOut = -parsed.lines.filter(l => l.amount < 0).reduce((t, l) => t + l.amount, 0);
                        let msg = `อ่านจากตัวหนังสือในไฟล์ (ไม่ใช้ AI) ${parsed.lines.length} รายการ\n` +
                            `ยอดยกมา ${Number(parsed.opening ?? 0).toLocaleString('en-US', { minimumFractionDigits: 2 })} · ยอดยกไป ${Number(parsed.closing ?? 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}\n` +
                            `ฝาก ${sumIn.toLocaleString('en-US', { minimumFractionDigits: 2 })} · ถอน ${sumOut.toLocaleString('en-US', { minimumFractionDigits: 2 })} · ยอดคงเหลือเดินลงทุกแถว ✅\n\n` +
                            `นำเข้า ${res.importedCount} รายการ` + (res.mergedCount ? `\n🔗 จับคู่กับสลิป/รายการที่บันทึกไว้แล้ว ${res.mergedCount} รายการ (ไม่สร้างซ้ำ)` : '') + (res.autoCatCount ? `\n🏷️ ใส่หมวดให้อัตโนมัติจากรายการเดิม ${res.autoCatCount} รายการ (ตรวจแล้วกดบันทึก)` : '');
                        if (res.skippedCount) msg += `\nข้ามรายการซ้ำ ${res.skippedCount} รายการ:\n` + res.skippedDetails.slice(0, 10).join('\n') + (res.skippedDetails.length > 10 ? `\n...และอีก ${res.skippedDetails.length - 10} รายการ` : '');
                        if (res.errorCount) msg += `\n⚠️ บันทึกไม่สำเร็จ ${res.errorCount} รายการ — นำเข้าไฟล์เดิมอีกครั้งได้ (รายการที่มีแล้วจะถูกข้าม)`;
                        alert(msg);
                        loadPending();
                    });
                    /* 💳 ใบแจ้งยอดบัตรเครดิต (ไม่มียอดคงเหลือรายบรรทัด) · หลายบัตรในไฟล์เดียว → แยกบัญชีตามเลขบัตร (2026-10-30) */
                    const card = await parseCardStatement(opened.pdf).catch(() => ({ ok: false }));
                    if (card.ok) return noAi('บันทึกใบแจ้งยอดบัตร', () => importCardStatement(card, selectedAccId, file.name, triggerUploadBtn, file));
                }
            } catch (err) { console.warn('อ่านตัวหนังสือใน PDF ไม่ได้ → ใช้ AI', err); }

            try {
                const accObj = AppState.accounts.find(a => a.account_id === selectedAccId);
                const pdfPassword = foundPassword || (accObj ? accObj.pdf_password : null);

                const reader = new FileReader();
                reader.readAsArrayBuffer(file);
                reader.onload = async (evt) => {
                    const fileBytes = evt.target.result;
                    let finalPdfBase64 = null;
                    let finalImagesBase64 = null;
                    
                    try {
                        let pdfDoc = await PDFLib.PDFDocument.load(fileBytes);
                        const unencryptedBytes = await pdfDoc.save();
                        let binary = '';
                        const bytes = new Uint8Array(unencryptedBytes);
                        for (let i = 0; i < bytes.byteLength; i++) {
                            binary += String.fromCharCode(bytes[i]);
                        }
                        finalPdfBase64 = "data:application/pdf;base64," + window.btoa(binary);
                    } catch (err) {
                        if (err.message && (err.message.toLowerCase().includes('encrypted') || err.message.toLowerCase().includes('password'))) {
                            if (!pdfPassword) {
                                alert("ไฟล์ PDF นี้ถูกเข้ารหัสไว้ แต่คุณยังไม่ได้ตั้งค่า 'รหัสผ่าน PDF' สำหรับบัญชีนี้ในการตั้งค่าระบบ");
                                if(btnIcon) btnIcon.className = originalIconClass;
                                triggerUploadBtn.disabled = false;
                                setUploadBtnIdle(triggerUploadBtn);
                                return;
                            }
                            
                            // (เดิมมี alert แสดงรหัสผ่าน PDF บนจอ — ลบออก 2026-10-10 เพื่อความปลอดภัย)

                            try {
                                let pdfDoc = await PDFLib.PDFDocument.load(fileBytes, { password: pdfPassword });
                                const unencryptedBytes = await pdfDoc.save();
                                let binary = '';
                                const bytes = new Uint8Array(unencryptedBytes);
                                for (let i = 0; i < bytes.byteLength; i++) {
                                    binary += String.fromCharCode(bytes[i]);
                                }
                                finalPdfBase64 = "data:application/pdf;base64," + window.btoa(binary);
                            } catch (pwdErr) {
                                // Fallback to pdf.js for unsupported encryption (e.g., AES-256)
                                try {
                                    if (typeof pdfjsLib === 'undefined') {
                                        throw new Error("pdf.js library is not loaded.");
                                    }
                                    const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(fileBytes), password: pdfPassword });
                                    const pdfDocument = await loadingTask.promise;
                                    const numPages = pdfDocument.numPages;
                                    const imagesBase64 = [];
                                    
                                    for (let i = 1; i <= numPages; i++) {
                                        const page = await pdfDocument.getPage(i);
                                        const viewport = page.getViewport({ scale: 2.0 });
                                        const canvas = document.createElement('canvas');
                                        const context = canvas.getContext('2d');
                                        canvas.height = viewport.height;
                                        canvas.width = viewport.width;
                                        await page.render({ canvasContext: context, viewport: viewport }).promise;
                                        imagesBase64.push(canvas.toDataURL('image/jpeg', 0.85));
                                    }
                                    finalImagesBase64 = imagesBase64;
                                } catch (fallbackErr) {
                                    alert("ไม่สามารถถอดรหัส PDF ได้ รหัสผ่านที่ตั้งไว้ในระบบอาจไม่ถูกต้อง (หรือไฟล์เสียหาย)");
                                    if(btnIcon) btnIcon.className = originalIconClass;
                                    triggerUploadBtn.disabled = false;
                                    setUploadBtnIdle(triggerUploadBtn);
                                    return;
                                }
                            }
                        } else {
                            alert("เกิดข้อผิดพลาดในการอ่านไฟล์ PDF: " + err.message);
                            if(btnIcon) btnIcon.className = originalIconClass;
                            triggerUploadBtn.disabled = false;
                            setUploadBtnIdle(triggerUploadBtn);
                            return;
                        }
                    }

                    const payload = {};
                    if (finalPdfBase64) payload.pdfBase64 = finalPdfBase64;
                    if (finalImagesBase64) payload.imagesBase64 = finalImagesBase64;

                    const res = await fetch(`${API_BASE}/api/statement-ocr`, {
                        method: 'POST',
                        headers: { 
                            'Content-Type': 'application/json',
                            'x-user-id': encodeURIComponent(getUserIdHeader())
                        },
                        body: JSON.stringify(payload)
                    });
                    
                    if (res.ok) {
                        const data = await res.json();
                        if (data && data.transactions && data.transactions.length > 0) {
                            const useAcc = await statementPrecheck(selectedAccId, { account_number: data.account_number, rows: data.transactions, opening: data.opening_balance, closing: data.closing_balance });
                            if (!useAcc) { if(btnIcon) btnIcon.className = originalIconClass; triggerUploadBtn.disabled = false; setUploadBtnIdle(triggerUploadBtn); pdfInput.value = ''; return; }
                            selectedAccId = useAcc;
                            const res = await importStatementRows(selectedAccId, data.transactions, (d, n) => { setUploadBtnBusy(triggerUploadBtn, `กำลังบันทึก ${d}/${n}`); },
                                { opening: data.opening_balance, closing: data.closing_balance, source_kind: data.source_kind, file_name: file?.name || null });
                            let msg = `อ่านด้วย AI · นำเข้า ${res.importedCount} รายการ` + (res.mergedCount ? `\n🔗 จับคู่กับสลิป/รายการที่บันทึกไว้แล้ว ${res.mergedCount} รายการ (ไม่สร้างซ้ำ)` : '') + (res.autoCatCount ? `\n🏷️ ใส่หมวดให้อัตโนมัติจากรายการเดิม ${res.autoCatCount} รายการ (ตรวจแล้วกดบันทึก)` : '');
                            if (res.skippedCount > 0) {
                                msg += `\n\nข้ามรายการซ้ำ ${res.skippedCount} รายการ:\n` + res.skippedDetails.slice(0, 10).join('\n');
                                if (res.skippedDetails.length > 10) msg += `\n...และอีก ${res.skippedDetails.length - 10} รายการ`;
                            }
                            if (res.errorCount) msg += `\n⚠️ บันทึกไม่สำเร็จ ${res.errorCount} รายการ — นำเข้าไฟล์เดิมอีกครั้งได้`;
                            alert(msg);
                            loadPending();
                        } else {
                            alert("ไม่พบรายการธุรกรรมในไฟล์นี้");
                        }
                    } else {
                        const err = await res.json();
                        alert(`เกิดข้อผิดพลาด: ${err.error}`);
                    }
                    
                    triggerUploadBtn.disabled = false;
                    setUploadBtnIdle(triggerUploadBtn);
                    pdfInput.value = '';
                };
            } catch (err) {
                console.error("PDF Upload Error:", err);
                alert("เกิดข้อผิดพลาดในการประมวลผลไฟล์");
                triggerUploadBtn.disabled = false;
                setUploadBtnIdle(triggerUploadBtn);
                pdfInput.value = '';
            }
        });
    }
}

