    const fmt = (dg, trail) => { let o = dg.slice(0, 2); if (dg.length >= 2 && (dg.length > 2 || trail)) o += '/'; o += dg.slice(2, 4); if (dg.length >= 4 && (dg.length > 4 || trail)) o += '/'; return o + dg.slice(4, 8); };
