        CASH: { ico: 'fa-wallet', cls: 'av-k-cash', lbl: 'เงินสด' },
        WALLET: { ico: 'fa-mobile-screen', cls: 'av-k-wallet', lbl: 'กระเป๋าเงินอิเล็กทรอนิกส์' }
